        boot(g)
        g.warp(30810)
        st = g.start_battle(105)
        boss = st.unit("Masked Man")
        assert boss is not None
        assert boss["hp"] == 1200 and boss["hp_raw"] == 11200, boss
        zidane = st.unit("Zidane")
        assert zidane["hp"] == zidane["hp_raw"], "an ordinary unit's two HPs agree"


