        g.ROUTE_NPC_REPLANS = 0
        stood = _step_in_front(g, (a, (120, 120), [(120, 120), (-700, -700)], 3.0),
                               (b, (0, -170), [(0, -170), (0, 900)], 3.0))
        rec = g.route_to(450.0, 0.0, walkmesh=_flat_bgi(), prior=_prior(), npcs=True, smooth=True)
