        assert [r.k for r in g.story_rows()] == ["e"]
        with path.open("a", encoding="utf-8") as fh:
            fh.write(',"oops":1}\n')                                         # ...and it lands broken
        with pytest.raises(HarnessError, match="breaks the row contract"):
            g.story_rows()


