def test_o3_drive_voids_an_unregistered_battle(game):
    """V10 for a battle the registry does not answer (research/o3_design.md 2.3 step 1), each the GAME's, its cell the
    visit's place and SC: scene 337 at "62" (another scene); scene 338 at "61" (another place); and the same row twice
    (a same-field battle -- its row lands in "62" -- answered, then a second battle 338 in "62"). No battle row for an
    unanswered battle. Break: drop the answered set (the second battle is fought)."""
    SD = _segment_modules()
    for case in ("scene", "place", "twice"):
        fake = _o3_fake(game, exit_to=None if case == "twice" else 30810)
        pred = _o3_pred(battles=[_o3_row(lands=30821)]) if case == "twice" else _o3_pred()
        log: list = []
        if case == "scene":
            phases = _o3_route(scene=337, end=False)
        elif case == "place":
            phases = _o3_route(battle_in=61)
        else:                       # the second battle once the driver has landed the first (its row is logged)
            phases = _o3_route(end=False)[:3] + [
                (lambda f: any(r.get("k") == "battle" for r in log) and _o3_idle(f),
                 lambda f: f.start_battle(338, units=_o3_units()))]
        with session(game, fake) as g:
            _o3_start(g)
            err, log = _o3_drive(g, fake, pred, phases=phases, log=log)
            epoch = fake.battle_epoch
        assert isinstance(err, SD.RouteVoid) and (err.v, err.by) == ("V10", "game"), (case, err)
        where = 30820 if case == "place" else 30821
        assert err.cell == [where, 1155] and f"an unregistered battle: scene {337 if case == 'scene' else 338} " \
                                             f"(epoch {epoch}) in {where} (place {where}) at SC 1155" in str(err), err
        rows = [r for r in log if r["k"] == "battle"]
        assert len(rows) == (1 if case == "twice" else 0), (case, rows)


def test_o3_drive_fights_through_an_end_that_beats_its_command(game):
    """The "twice" case above with its -n 6 flake PINNED: King Leo's scripted end (result 2) lands between fight()'s
    read of "asking slot 0" and its second command (the fake's ``battle_end_on_command``; the latch off, so nothing
    else ends it), and the agent refuses that command -- no battle HUD. The battle is gone with its result: the driver
    logs its row (result 2, one turn, not timed out) and goes on to V10 on the second battle 338, exactly as the
    unraced case does. Break: let fight() pass the refusal on (a StepRefused out of the drive, the flake's traceback)."""
    SD = _segment_modules()
    fake = _o3_fake(game)
    fake.battle_script_end = None
    fake.battle_end_on_command = {"result": 2, "nth": 2}
    log: list = []
    phases = _o3_route(end=False)[:3] + [
        (lambda f: any(r.get("k") == "battle" for r in log) and _o3_idle(f),
         lambda f: f.start_battle(338, units=_o3_units()))]
    with session(game, fake) as g:
        _o3_start(g)
        err, log = _o3_drive(g, fake, _o3_pred(battles=[_o3_row(lands=30821)]), phases=phases, log=log)
    assert isinstance(err, SD.RouteVoid) and (err.v, err.by) == ("V10", "game"), err
    assert len([s for s in fake.executed if s[0] == "battlecmd"]) == 2, fake.executed
    rows = [r for r in log if r["k"] == "battle"]
    assert len(rows) == 1, rows
    b = rows[0]
    assert (b["result"], b["turns"], b["timed_out"], b["v"], b["landed"]) == (2, 1, False, None, 30821), b


def test_o3_drive_fights_through_an_end_that_beats_its_menu(game):
    """The race above a step EARLIER, through the driver: King Leo's scripted end (result 2) lands between the ack of
    the second command's ``menus`` step and the read of its menu (the fake's ``battle_end_on_command``, ``op``
    "menus", ``after`` 0: the end in the step's own frame, so no sample carries that menu; the latch off), and
    menus() raises BattleGone. The battle is gone with its result: the driver logs its row (result 2, one turn, not
    timed out) and goes on to V10 on the second battle 338, exactly as the unraced case does; no second battlecmd.
    Break: let menus() wait for the menu alone (a plain HarnessError out of the drive after its 10 s), or let fight()
    pass BattleGone on."""
    SD = _segment_modules()
    fake = _o3_fake(game)
    fake.battle_script_end = None
    fake.battle_end_on_command = {"result": 2, "nth": 2, "op": "menus", "after": 0}
    log: list = []
    phases = _o3_route(end=False)[:3] + [
        (lambda f: any(r.get("k") == "battle" for r in log) and _o3_idle(f),
         lambda f: f.start_battle(338, units=_o3_units()))]
    with session(game, fake) as g:
        _o3_start(g)
        err, log = _o3_drive(g, fake, _o3_pred(battles=[_o3_row(lands=30821)]), phases=phases, log=log)
    assert isinstance(err, SD.RouteVoid) and (err.v, err.by) == ("V10", "game"), err
    steps = [s[0] for s in fake.executed if s[0] in ("menus", "battlecmd")]
    assert steps == ["menus", "battlecmd", "menus"], steps
    rows = [r for r in log if r["k"] == "battle"]
    assert len(rows) == 1, rows
    b = rows[0]
    assert (b["result"], b["turns"], b["timed_out"], b["v"], b["landed"]) == (2, 1, False, None, 30821), b


def test_o3_drive_voids_a_battle_with_no_result(game):
    """V15 (research/o3_design.md 2.3 step 2, 2.6): the registered battle reaches no result within the row's own
    bounds -- the DRIVER's (its policy and bounds own the fight). A King Leo no attack can end (10^7 HP, no scripted
    end) with ``timeout_s`` 3: V15 after about 3 s, the battle row ``timed_out``; with ``max_turns`` 0 (R-BATTLE-VOID's
    row): V15 at the first command prompt -- no battlecmd executed, still mid-fight in BattleHUD. Break: let fight()'s
    FightTimeout propagate (the run is STOPPED, V13)."""
    SD = _segment_modules()
    for bounds, want in (({"timeout_s": 3}, "within 3 s / 40 turns"), ({"max_turns": 0}, "within 60 s / 0 turns")):
        fake = _o3_fake(game, exit_to=30810)
        fake.battle_script_end = None
        pred = _o3_pred(battles=[_o3_row(**bounds)])
        with session(game, fake) as g:
            _o3_start(g)
            err, log = _o3_drive(g, fake, pred, phases=_o3_route(units=_o3_units(10 ** 7), end=False), budget=180.0)
            st = g.state
        assert isinstance(err, SD.RouteVoid) and (err.v, err.by, err.cell) == ("V15", "driver", [30821, 1155]), err
        assert f"battle 338 reached no result {want}" in str(err), err
        b = [r for r in log if r["k"] == "battle"][0]
        assert b["timed_out"] is True and b["v"] == "V15" and b["result"] is None, b
        if bounds.get("max_turns") == 0:
            assert b["turns"] == 0 and not [s for s in fake.executed if s[0] == "battlecmd"], fake.executed
            assert st.in_battle and st.ui_state == "BattleHUD" and st.battle_result == 0, st


def test_o3_drive_stops_on_a_battle_gone_without_a_result(game):
    """A registered battle whose scene GOES with no result while its bounds hold (the review, research/o3_design.md
    11.7 #2): fight()'s FightTimeout kind "gone" -- no bound ran out -- is an instrument stop, never V15 (the driver's
    bound, "reached no result within 60 s") nor the budget's message: the executor logs its battle row (v V13, by
    driver, result None, timed_out False, the scene-gone why) and raises HarnessError, which the session records as
    STOPPED (V13). The scene goes a second into the fight (the battle ends with result 0 on the fake's own thread; no
    ATB, so no command prompt races it). Break: read every FightTimeout as a bound (V15)."""
    SD = _segment_modules()
    fake = _o3_fake(game)
    fake.battle_script_end = None
    fake.atb_gain = 0                                       # no command prompt: the fight only waits
    started: dict = {}
    phases = _o3_route(units=_o3_units(10 ** 7), end=False)[:3] + [
        (lambda f: f.battle_active, lambda f: started.update(frame=f.frame)),
        (lambda f: "frame" in started and f.frame >= started["frame"] + 240, lambda f: _o3_end_on_the_fake(f, 0))]
    log: list = []
    with session(game, fake) as g:
        _o3_start(g)
        with pytest.raises(HarnessError, match="went away with no result") as err:
            _o3_drive(g, fake, _o3_pred(), phases=phases, log=log, budget=180.0)
    assert not isinstance(err.value, SD.RouteVoid) and "reached no result within" not in str(err.value), err.value
    b = [r for r in log if r["k"] == "battle"][0]
    assert (b["v"], b["by"], b["result"], b["timed_out"], b["turns"]) == ("V13", "driver", None, False, 0), b
    assert b["why"].startswith("battle 338's scene went away with no result"), b


def test_o3_drive_bounds_the_leave_by_its_row(game):
    """The leave is bounded (the review, research/o3_design.md 11.7 #1): the executor passes leave_battle
    ``timeout=min(the row's land_cap_s, the run's time left)``. A battle whose BattleResult never hands over
    (``result_frames`` 10^6), ``land_cap_s`` 2: the leave stops "timeout" short of its 40 Confirms, each Confirm it made
    a press row, and the landing's own cap then ends the run -- V14, no field within 2 s. Break: call leave_battle
    without its bound (it presses all 40 first)."""
    SD = _segment_modules()
    fake = _o3_fake(game, exit_to=30810, result_frames=10 ** 6)
    pred = _o3_pred(battles=[_o3_row(land_s=1.0, land_cap_s=2.0)])
    with session(game, fake) as g:
        _o3_start(g)
        err, log = _o3_drive(g, fake, pred, phases=_o3_route(end=False), budget=120.0)
    assert isinstance(err, SD.RouteVoid) and (err.v, err.by) == ("V14", "game"), err
    b = [r for r in log if r["k"] == "battle"][0]
    assert b["leave"]["stopped"] == "timeout" and 0 < b["leave"]["presses"] < 40, b["leave"]
    assert len([r for r in log if r["k"] == "press" and r["why"] == "leave_battle"]) == b["leave"]["presses"], log


def test_o3_drive_logs_leave_battle_presses_as_press_rows(game):
    """The leave's Confirms are evidence (research/o3_design.md 2.3 step 3): each is a ``press`` row -- ``why``
    "leave_battle", ``pre`` the sample it was decided on (in the battle), ``post`` None, ``near`` [] -- as many as the
    leave pressed and the battle row counts, every one executed by the game. Break: log no press rows."""
    fake = _o3_fake(game, exit_to=30810, cls=_StampFake)
    with session(game, fake) as g:
        _o3_start(g)
        out, log = _o3_drive(g, fake, _o3_pred(), phases=_o3_route())
        leave = g.last_leave
    assert not isinstance(out, Exception) and out["end"] == "reached", out
    rows = [r for r in log if r["k"] == "press" and r["why"] == "leave_battle"]
    assert rows and len(rows) == len(leave["presses"]) == out["battles"][0]["leave"]["presses"], (rows, leave)
    assert [r["pre"] for r in rows] == leave["presses"], (rows, leave)
    assert all(r["post"] is None and r["near"] == [] and r["pre"]["in_battle"] and r["visit"] == 2 for r in rows), rows
    first, landed = min(r["pre"]["frame"] for r in rows), out["battles"][0]["land_frame"]
    fired = [f for _t, f, s in fake.stamped if s[:2] == ["press", "confirm"] and first <= f < landed]
    assert len(fired) == len(rows), (fired, rows)


def test_o3_drive_stops_on_a_stop_page(game):
    """Rule 7's stop pages (research/o3_design.md 2.2, 2.6): 61-63's error window ("Error Env Play()  Slot=n", which an
    incoming Byte[13]/[14] of 2 or 9 opens) VOIDs the run as V5 with NOTHING pressed -- the DRIVER's in the run's first
    visit, the start place (the warp's start state), the GAME's in a later visit (a fork's deviation). Break: page
    the window (a Confirm closes it and the run goes on)."""
    SD = _segment_modules()
    for at, by, where in ((61, "driver", 30820), (62, "game", 30821)):
        fake = _o3_fake(game, exit_to=30810, cls=_StampFake)
        up = {}

        def error_page(f, up=up):
            up["frame"] = f.frame
            f.scene(_O3_ERROR, control=False)
        if at == 61:
            phases = [(lambda f: f.field_id == 30820, error_page)]
        else:
            phases = [(lambda f: f.field_id == 30820, lambda f: f.scene("Narrator\n“Ladies and gentlemen!”",
                                                                        control=False)),
                      (lambda f: f.field_id == 30820 and _o3_idle(f), lambda f: (_o2_move(f, 30821),
                                                                                 error_page(f)))]
        with session(game, fake) as g:
            _o3_start(g)
            err, log = _o3_drive(g, fake, _o3_pred(), phases=phases)
        assert isinstance(err, SD.RouteVoid) and (err.v, err.by, err.cell) == ("V5", by, [where, 1155]), (at, err)
        assert "Env Play()" in str(err) and "Error Env Play()" in str(err), err
        # a press FOR the window executes at a later frame than the one it went up in: it must be published, sampled
        # and requested first (61's own last page press can share that frame -- the director answers it at once)
        late = [f for _t, f, s in fake.stamped if s[:2] == ["press", "confirm"] and f > up["frame"]]
        assert late == [], (at, late)


def test_o3_drive_answers_a_skip_dialog_at_its_default(game):
    """The skip-movie rule (research/o3_design.md 2.5): during 61's movie a stray Confirm (the director's: the driver
    presses only on pages) opens the skip dialog; the rule answers it at the game's own cursor -- No -- the movie
    resumes for exactly the frames it had left, the page after it is turned, and the run reaches the end. Break: drop
    the rule (V1)."""
    fake = _o3_fake(game)
    movie = {"movie": 600, "skip": dict(_O3_SKIP)}
    phases = [(lambda f: f.field_id == 30820, lambda f: f.scene(movie, "Narrator\n“The curtain rises.”",
                                                                control=False)),
              (lambda f: f._movie is not None and f.movies[-1]["played"] >= 60,
               lambda f: f.queue.append(["press", "confirm", "4"])),
              (lambda f: _o3_idle(f) and f.movies and f.movies[-1]["end"] is not None, lambda f: _o2_move(f, _O3_END))]
    with session(game, fake) as g:
        _o3_start(g)
        out, log = _o3_drive(g, fake, _o3_pred(), phases=phases)
    assert not isinstance(out, Exception) and out["end"] == "reached", out
    assert fake.answered == [1] and len(fake.movies) == 1, (fake.answered, fake.movies)
    assert (fake.movies[0]["played"], fake.movies[0]["skips"], fake.movies[0]["ended"]) == (600, 1, "played")
    assert [(c["index"], c["rule"], c["selected"]) for c in out["choices"]] == [("default", 0, 1)], out["choices"]
    assert out["pages"] == ["Narrator\n“The curtain rises.”"], out["pages"]


def test_o3_drive_watchdog_against_a_long_movie(game):
    """The stall watchdog against a movie (research/o3_design.md 4.12, 11.1 #4): the agent publishes no movie state,
    so a movie longer than ``no_progress_s`` is V14 (game) -- and with ``no_progress_s`` above the movie the run reaches
    the end. The sizing rule, pinned on the fake. Break: count the movie as progress (the short budget then reaches
    the end)."""
    SD = _segment_modules()
    got = {}
    for no_progress_s in (1.0, 15.0):
        fake = _o3_fake(game)
        phases = [(lambda f: f.field_id == 30820, lambda f: f.scene("Narrator\n“Lights.”", {"movie": 960},
                                                                    "Narrator\n“Curtain.”", control=False)),
                  (lambda f: _o3_idle(f) and f.movies and f.movies[-1]["end"] is not None,
                   lambda f: _o2_move(f, _O3_END))]
        pred = _o3_pred()
        pred["budget"]["no_progress_s"] = no_progress_s
        with session(game, fake) as g:
            _o3_start(g)
            got[no_progress_s] = _o3_drive(g, fake, pred, phases=phases, budget=40.0)[0], dict(fake.movies[0])
    err, mv = got[1.0]
    assert isinstance(err, SD.RouteVoid) and (err.v, err.by, err.cell) == ("V14", "game", [30820, 1155]), err
    assert "no progress for 1 s in 30820" in str(err) and mv["end"] is None, (err, mv)
    out, mv = got[15.0]
    assert not isinstance(out, Exception) and out["end"] == "reached" and mv["ended"] == "played", (out, mv)


def test_o3_drive_waits_for_the_end_places_first_row(game):
    """Rule 1's opt-in end row (``budget.end_row_s``; research/o3_design.md 2.2, 11.7 #3). Rule 1 fires on the first
    poll that publishes the end field and the session closes the trace right after the drive returns: story-o1e closed
    it 1-4 frames after the field changed, its run 3 S before any row of the end field (no end cut). The end field's
    first store here comes 240 frames after the arrival. With ``end_row_s`` 3 the drive waits for it: the ``end`` row
    records ``end_row`` {seen True, f its frame, s the wait}, and the row is in the trace when the drive returns. A row
    that never comes is waited for ``end_row_s`` (0.5) and no longer: seen False, no VOID (the analysis's A-NOEND).
    Without the key -- O1's and O2's rule 1 -- no wait and no ``end_row``: the drive returns before the store, and the
    trace holds no row of the end field (the race, reproduced). Break: return before the row (no wait)."""
    got = {}
    for wait, store in ((3.0, True), (0.5, False), (None, True)):
        fake = _o3_fake(game)
        pred = _o3_pred()
        if wait is not None:
            pred["budget"]["end_row_s"] = wait
        arrived: dict = {}

        def to_end(f, arrived=arrived):
            arrived["frame"] = f.frame
            _o2_move(f, _O3_END)
        phases = [(lambda f: f.field_id == 30820, lambda f: f.scene("Narrator\n“Lights.”", control=False)),
                  (lambda f: f.field_id == 30820 and _o3_idle(f), to_end)]
        if store:                                # 64's Main_Init: its first store, 240 frames after the arrival
            phases.append((lambda f, arrived=arrived: f.field_id == _O3_END and f.frame >= arrived["frame"] + 240,
                           lambda f: f.script_store(0, 0, 22, 191 >> 3, "Bit", 0, bit=191)))
        with session(game, fake) as g:
            _o3_start(g)
            g.storytrace(True)
            t0 = time.time()
            out, log = _o3_drive(g, fake, pred, phases=phases)
            took = time.time() - t0
            rows = [r for r in g.story_rows() if r.k == "w" and r.fld == _O3_END]
        assert not isinstance(out, Exception) and out["end"] == "reached", (wait, out)
        got[(wait, store)] = ([r for r in log if r["k"] == "end"][-1], rows, took)
    end, rows, _took = got[(3.0, True)]
    er = end["end_row"]
    assert er["seen"] is True and len(rows) == 1 and er["f"] == rows[0].f, (er, rows)
    assert 0.5 <= er["s"] < 3.0, er                        # it waited for the store, and not for its bound
    end, rows, _took = got[(0.5, False)]
    assert end["end_row"]["seen"] is False and end["end_row"]["f"] is None and rows == [], end
    assert 0.5 <= end["end_row"]["s"] < 2.0, end["end_row"]
    end, rows, _took = got[(None, True)]
    assert "end_row" not in end and rows == [], (end, rows)    # O1's and O2's rule 1: the trace closes before the row


def test_o3_drive_battle_of_rejects_a_bad_row():
    """The registry row, strict (research/o3_design.md 2.1, section 8's battle-row unit): 2.1's row passes (a copy);
    ValueError on ``won`` [1, 2, 3] (a defeat counted won), [2] and []; on a beat not in ``beats``; on a beat a naming
    rule, a table step, a choice rule or a battle row of ANOTHER slot also names; on ``max_turns`` -1 and on True (a
    bool is no int); on ``land_s`` above ``land_cap_s``; on an unknown or a missing key; ``max_turns`` 0 passes --
    R-BATTLE-VOID's override of the SAME slot, checked against the predictions it overrides. And a driver refuses a
    bad row before anything is driven. Break: compare ``won`` by equality alone ([True, 2] then passes)."""
    SD = _segment_modules()
    pred = _o3_pred()
    row = pred["battles"][0]
    got = SD.battle_of(pred, row)
    assert got == row and got is not row
    assert SD.battle_of(pred, dict(row, max_turns=0))["max_turns"] == 0
    other = _o3_pred(battles=[_o3_row(sc=None, won=[1])])          # any SC; WinPose on: won [1]
    assert SD.battle_of(other, other["battles"][0])["won"] == [1]

    def refused(match, **change):
        with pytest.raises(ValueError, match=match):
            SD.battle_of(pred, {**row, **change})
    for won in ([1, 2, 3], [2], [], [True, 2], (1, 2.0)):
        refused("won is", won=won)
    refused("is not one of the predictions' beats", beat="garnet")
    refused("max_turns is an int >= 0", max_turns=-1)
    refused("max_turns is an int >= 0", max_turns=True)
    refused("max_turns is an int >= 0", max_turns=2.5)
    refused("is above land_cap_s", land_s=200)
    refused("positive numbers", timeout_s=0)
    refused("of the wrong type", scene="338")
    refused("of the wrong type", sc=True)
    with pytest.raises(ValueError, match="unknown key"):
        SD.battle_of(pred, {**row, "lands_in": 63})
    with pytest.raises(ValueError, match="missing"):
        SD.battle_of(pred, {k: v for k, v in row.items() if k != "land_cap_s"})
    for where in ("naming", "choices", "table", "battles"):
        p = _o3_pred()
        if where == "naming":
            p["naming"] = [{"donor": 30821, "sc": 1155, "beat": "leo"}]
        elif where == "choices":
            p["choices"] = p["choices"] + [{"donor": 30821, "sc": None, "match": "x", "pick": "y", "beat": "leo"}]
        elif where == "table":
            p["table"] = [{"donor": 30821, "sc": 1155, "steps": [{"kind": "trigger", "goal": [0, 0], "until": {"x_le": 1},
                                                                 "beat": "leo"}]}]
        else:
            p["battles"] = p["battles"] + [_o3_row(scene=339)]
        with pytest.raises(ValueError, match="is also named by"):
            SD.battle_of(p, p["battles"][0])
    bad = _o3_pred(battles=[_o3_row(won=[1, 2, 3])])
    with pytest.raises(ValueError, match="won is"):
        SD.drive(None, bad, "S", [], deadline=time.time() + 1, floor_for=lambda d, c: None, prior_for=lambda d: None)


# ---- THE MOVIE-SKIP POLICY (opt-in, ``pred["movies"]``; studies/story-trace/PLAN.md "Movie skip (opt-in)"). On the
# fake's "61" (30820) at SC 1155: a movie beat -- with H9's skip dialog (FieldHUD.cs:275-286, the cursor on No), or
# none -- then a page, then the end. Each test's movie and timings are its own; 240 fake frames are a second.

_O3_PAGE = "Narrator\n“The curtain rises.”"


def _o3_movies(**over):
    """A policy registering "61" at SC 1155: a press 0.5 s into the visit, again every second, three at most; its next
    page registered 25 s into the visit."""
    cell = {"donor": 30820, "sc": 1155, "after_s": 0.5, "next_page_s": 25.0,
            "why": "61 e2 t1 ip159 Cinematic(0,8,1,1): FMV003, on the fake"}
    cell.update(over.pop("cell", {}))
    return {"policy": "skip", "press_every_s": 1.0, "max_presses": 3, "cells": [cell], **over}


def _o3_movie_route(*beats):
    """61's scene (``beats``: the movie and what follows it), then the end once it is over."""
    return [(lambda f: f.field_id == 30820, lambda f: f.scene(*beats, control=False)),
            (lambda f: f.field_id == 30820 and _o3_idle(f) and f.movies and f.movies[-1]["end"] is not None,
             lambda f: _o2_move(f, _O3_END))]


def _o3_movie_run(game, pred, phases, *, budget=60.0):
    """One drive on a fresh fake: ``(outcome or the RouteVoid raised, log, fake)``."""
    fake = _o3_fake(game)
    with session(game, fake) as g:
        _o3_start(g)
        out, log = _o3_drive(g, fake, pred, phases=phases, budget=budget)
    return out, log, fake


def _presses(log, why):
    return [r for r in log if r["k"] == "press" and r["why"] == why]


def test_segment_movie_skip_answer_reads_only_the_skip_dialog():
    """skip_answer (pure): the engine's skip dialog -- US "the movie?", UK "this cutscene?", each option line as
    published or short its first character (O1's "ight the candle"), the prompt published EMPTY with the text in the
    rendered box -- answers absolute option 0, FieldHUD's skip. Never a skip: another prompt (and an empty one whose
    box says something else), three lines, the pair reversed, Yes at absolute index 1 (a disabled line before it), a
    line that is only a fragment ("s"), no choice. A policy's own ``match``/``yes``/``no`` replace the US text. Break:
    match the lines alone (the "save" dialog then answers 0)."""
    SD = _segment_modules()
    us = {"options": ["Do you want to skip\nthe movie?", "Yes", "No"], "active": [0, 1], "selected": 1, "count": 2}
    assert SD.skip_answer(us) == 0 and SD.skip_answer(dict(us, active=None)) == 0
    assert SD.skip_answer(dict(us, options=["Do you want to skip\nthis cutscene?", "Yes", "No"])) == 0
    assert SD.skip_answer(dict(us, options=["o you want to skip\nthe movie?", "es", "o"])) == 0
    box = ["Do you want to skip\nthe movie?\nYes\nNo"]
    assert SD.skip_answer(dict(us, options=["", "Yes", "No"]), box) == 0
    assert SD.skip_answer(dict(us, options=["", "Yes", "No"]), ["Save the game?\nYes\nNo"]) is None
    assert SD.skip_answer(dict(us, options=["", "Yes", "No"])) is None
    for options in (["Do you want to save\nthe game?", "Yes", "No"], ["Do you want to skip\nthe movie?", "Yes", "No",
                                                                        "Maybe"],
                    ["Do you want to skip\nthe movie?", "No", "Yes"], ["Do you want to skip\nthe movie?", "s", "No"],
                    ["Do you want to skip\nthe movie?", "", "No"], ["Do you want to skip\nthe movie?", "Yes"]):
        assert SD.skip_answer(dict(us, options=options), box) is None, options
    assert SD.skip_answer(dict(us, active=[1, 2])) is None
    assert SD.skip_answer(None) is None and SD.skip_answer({"options": []}) is None
    fr = {"match": "passer", "yes": "Oui", "no": "Non"}
    assert SD.skip_answer({"options": ["Voulez-vous passer\nles cinématiques ?", "Oui", "Non"]}, (), fr) == 0
    assert SD.skip_answer(us, (), fr) is None


def test_segment_movie_skip_policy_is_strict():
    """movies_of: the policy (``pred["movies"]``) is checked STRICT before anything is driven, as a battle row is.
    None without the key (the driver is O3's exactly); a good policy comes back a copy with the engine's US text filled
    in. ValueError on: a policy that is no dict, an unknown or a missing key, a policy other than "skip", empty cells,
    a non-positive ``press_every_s``, ``max_presses`` 0 or True (a bool is no int), an empty ``match``; a cell with an
    unknown or missing key (``length_s`` among the unknown: the span is registered to the NEXT PAGE, ``next_page_s``,
    and a name that read as the movie's own length is refused), a string donor, a bool SC, a non-positive ``after_s``
    or ``next_page_s``, an empty ``why``; two cells one place and SC would both match (an SC None is every SC); a cell
    whose last press and its wait end past its next page. And a driver refuses a bad policy before anything is driven.
    Break: accept unknown keys (a typo'd ``max_press`` then registers nothing)."""
    SD = _segment_modules()
    assert SD.movies_of(_o3_pred()) is None
    pol = _o3_movies()
    got = SD.movies_of({"movies": pol})
    assert got is not pol and got["cells"] == pol["cells"] and got["cells"][0] is not pol["cells"][0]
    assert (got["match"], got["yes"], got["no"]) == ("want to skip", "Yes", "No")
    assert SD.movies_of({"movies": dict(pol, match="passer", yes="Oui", no="Non")})["yes"] == "Oui"
    assert SD.movies_of({"movies": _o3_movies(cell={"sc": None, "next_page_s": None})})["cells"][0]["sc"] is None
    cell = pol["cells"][0]
    no_span = {k: v for k, v in cell.items() if k != "next_page_s"}
    assert SD.movies_of({"movies": dict(pol, cells=[no_span])})["cells"] == [no_span]       # the span is optional

    def refused(match, policy):
        with pytest.raises(ValueError, match=match):
            SD.movies_of({"movies": policy})
    refused("the policy is a dict", ["skip"])
    refused("unknown key", dict(pol, max_press=2))
    refused("missing", {k: v for k, v in pol.items() if k != "max_presses"})
    refused("is not one of", dict(pol, policy="play"))
    refused("non-empty list", dict(pol, cells=[]))
    refused("press_every_s", dict(pol, press_every_s=0))
    for most in (0, True, 1.5):
        refused("max_presses", dict(pol, max_presses=most))
    refused("non-empty strings", dict(pol, match=""))
    refused("a cell is a dict", dict(pol, cells=[61]))
    refused("unknown key", dict(pol, cells=[dict(cell, field=61)]))
    refused(r"unknown key\(s\) \['length_s'\]", dict(pol, cells=[dict(no_span, length_s=25.0)]))
    refused("missing", dict(pol, cells=[{k: v for k, v in cell.items() if k != "after_s"}]))
    for change in ({"donor": "61"}, {"sc": True}, {"after_s": 0}, {"next_page_s": -1}, {"why": ""},
                   {"after_s": False}):
        refused("of the wrong type", dict(pol, cells=[dict(cell, **change)]))
    refused("registered twice", dict(pol, cells=[cell, dict(cell, after_s=2.0)]))
    refused("registered twice", dict(pol, cells=[cell, dict(cell, sc=None)]))
    refused("past its next page at 25 s", dict(pol, cells=[dict(cell, after_s=22.5)]))     # 22.5 + 2 + 1 > 25
    assert SD.movies_of({"movies": dict(pol, cells=[dict(cell, after_s=21.0)])})          # 21 + 2 + 1 = 24 <= 25
    assert SD.movies_of({"movies": dict(pol, cells=[cell, dict(cell, donor=30821)])})      # another place: fine
    with pytest.raises(ValueError, match="unknown key"):
        SD.drive(None, _o3_pred(movies=dict(pol, every=1)), "S", [], deadline=time.time() + 1,
                 floor_for=lambda d, c: None, prior_for=lambda d: None)


def test_o3_drive_movie_skip_presses_once_and_answers_yes(game):
    """The policy's skip (PLAN.md "Movie skip (opt-in)"): in the registered cell, nothing on screen and control off,
    0.5 s into the visit, ONE Confirm (a ``press`` row, "movie_skip", its frame) opens the skip dialog; the policy
    answers it YES -- option 0, over the game's cursor on No -- so the movie ends at once and its wait goes on: the page
    after it is turned and the run reaches the end, long before the movie's 25 s. The visit's ``movie`` row: one press,
    the dialog as published (prompt, options, active [0, 1], selected 1), the frame and the seconds it was skipped at,
    the next page as registered (``next_page_s`` 25) and ``left_s`` -- 25 s less those seconds, the most the skip can
    save -- and NO ``saved_s``: what a skip saved is the A/B's to measure, from the drive times; its ``choice`` row
    (rule "movie_skip", index 0, selected 1). Break: answer the dialog's default (the movie then plays out)."""
    pred = _o3_pred(movies=_o3_movies())
    phases = _o3_movie_route({"movie": 6000, "skip": dict(_O3_SKIP)}, _O3_PAGE)
    out, log, fake = _o3_movie_run(game, pred, phases)
    assert not isinstance(out, Exception) and out["end"] == "reached", out
    assert fake.answered == [0] and len(fake.movies) == 1, (fake.answered, fake.movies)
    mv = fake.movies[0]
    assert (mv["skips"], mv["ended"]) == (1, "skipped") and mv["played"] < 6000 // 4, mv
    presses = _presses(log, "movie_skip")
    assert len(presses) == 1 and presses[0]["pre"]["control"] is False and presses[0]["donor"] == 30820, presses
    row = out["movies"][0]
    assert out["movies"] == [r for r in log if r["k"] == "movie"] and len(out["movies"]) == 1, out["movies"]
    assert (row["outcome"], row["missed"], row["cell"], row["visit"], row["sc"]) == ("skipped", None, 0, 1, 1155), row
    assert row["presses"] == [{"frame": presses[0]["pre"]["frame"], "t": row["presses"][0]["t"]}], row["presses"]
    assert 0.5 <= row["presses"][0]["t"] < row["t"] < 10.0, row
    assert row["dialog"] == {"options": ["Do you want to skip\nthe movie?", "Yes", "No"], "active": [0, 1],
                             "selected": 1, "count": 2}, row["dialog"]
    assert row["frame"] > presses[0]["pre"]["frame"] and row["next_page_s"] == 25.0, row
    assert row["left_s"] == round(25.0 - row["t"], 1) and "saved_s" not in row and "length_s" not in row, row
    assert [(c["rule"], c["index"], c["selected"]) for c in out["choices"]] == [("movie_skip", 0, 1)], out["choices"]
    assert out["pages"] == [_O3_PAGE] and len(_presses(log, "page")) >= 1, out["pages"]
    assert out["t"] < 15.0, out["t"]


def test_o3_drive_movie_skip_is_off_without_the_policy(game):
    """No policy, the driver as it is today: during the same movie it presses nothing; a stray Confirm (the
    director's) opens the skip dialog and O1's rule answers it at the game's default (No), the movie resumes and plays
    out, and the outcome carries no ``movies`` key. With the policy ON in that very cell but its press not yet due
    (``after_s`` past the movie), the stray dialog is still O1's to answer -- the policy answers only the dialog its
    own press opened -- and no ``movie`` row opens. Break: answer any skip dialog of a registered cell YES."""
    phases = [(lambda f: f.field_id == 30820, lambda f: f.scene({"movie": 960, "skip": dict(_O3_SKIP)}, _O3_PAGE,
                                                                control=False)),
              (lambda f: f._movie is not None and f.movies[-1]["played"] >= 60,
               lambda f: f.queue.append(["press", "confirm", "4"])),
              (lambda f: _o3_idle(f) and f.movies and f.movies[-1]["end"] is not None, lambda f: _o2_move(f, _O3_END))]
    for policy in (None, _o3_movies(cell={"after_s": 20.0})):
        pred = _o3_pred() if policy is None else _o3_pred(movies=policy)
        out, log, fake = _o3_movie_run(game, pred, list(phases))
        assert not isinstance(out, Exception) and out["end"] == "reached", (policy, out)
        assert fake.answered == [1], (policy, fake.answered)
        assert (fake.movies[0]["played"], fake.movies[0]["skips"], fake.movies[0]["ended"]) == (960, 1, "played")
        assert [(c["index"], c["rule"], c["selected"]) for c in out["choices"]] == [("default", 0, 1)], out["choices"]
        assert _presses(log, "movie_skip") == [] and not [r for r in log if r["k"] == "movie"], policy
        assert ("movies" in out) is (policy is not None) and out.get("movies", []) == [], (policy, out.get("movies"))


def test_o3_drive_movie_skip_presses_only_in_a_registered_cell(game):
    """No press outside a registered cell: the same movie (4 s, its skip dialog) under a policy that registers
    another place ("62"), another SC (1000), or this cell with ``after_s`` past the movie -- each run presses nothing,
    the movie plays out and the run reaches the end with no ``movie`` row. Break: press in any cell."""
    for cell in ({"donor": 30821}, {"sc": 1000}, {"after_s": 20.0}):
        pred = _o3_pred(movies=_o3_movies(cell=cell))
        out, log, fake = _o3_movie_run(game, pred, _o3_movie_route({"movie": 960, "skip": dict(_O3_SKIP)}, _O3_PAGE))
        assert not isinstance(out, Exception) and out["end"] == "reached", (cell, out)
        assert _presses(log, "movie_skip") == [] and out["movies"] == [] and fake.answered == [], (cell, log)
        assert (fake.movies[0]["played"], fake.movies[0]["skips"], fake.movies[0]["ended"]) == (960, 0, "played")


def test_o3_drive_movie_skip_retries_then_gives_up_without_a_void(game):
    """The bounded retries. A hit area that arms 120 frames into the movie (``armed_after``): the first press, a
    quarter second in, finds none; the second -- ``press_every_s`` (2 s) later -- opens the dialog, answered YES:
    skipped after two presses. A movie with no hit area at all (no skip dialog, ever): three presses, each
    ``press_every_s`` after the last, then -- that long after the third -- 'movie-skip missed', no fourth press, and the
    movie plays out: the run reaches the end, never a VOID. (The fake runs about 195 frames a second here: the margins
    hold from about 80 to 240.) Break: drop ``max_presses`` (a fourth press comes)."""
    pred = _o3_pred(movies=_o3_movies(cell={"after_s": 0.25}, press_every_s=2.0))
    out, log, fake = _o3_movie_run(game, pred, _o3_movie_route(
        {"movie": 2400, "skip": dict(_O3_SKIP, armed_after=120)}, _O3_PAGE))
    assert not isinstance(out, Exception) and out["end"] == "reached", out
    row = out["movies"][0]
    assert (row["outcome"], len(row["presses"]), fake.answered) == ("skipped", 2, [0]), (row, fake.answered)
    assert row["presses"][1]["t"] - row["presses"][0]["t"] >= 2.0 - 0.05, row["presses"]
    assert (fake.movies[0]["skips"], fake.movies[0]["ended"]) == (1, "skipped"), fake.movies
    pred = _o3_pred(movies=_o3_movies(cell={"after_s": 0.25}))
    out, log, fake = _o3_movie_run(game, pred, _o3_movie_route({"movie": 1200}, _O3_PAGE))
    assert not isinstance(out, Exception) and out["end"] == "reached" and out["void"] is None, out
    row = out["movies"][0]
    ts = [p["t"] for p in row["presses"]]
    assert len(_presses(log, "movie_skip")) == 3 and len(ts) == 3, row
    assert all(b - a >= 1.0 - 0.05 for a, b in zip(ts, ts[1:])), ts
    assert row["outcome"] == "missed" and row["missed"].startswith("movie-skip missed: no skip dialog after 3 "
                                                                   "press(es)"), row
    assert (fake.movies[0]["played"], fake.movies[0]["ended"]) == (1200, "played") and fake.answered == []
    assert out["pages"] == [_O3_PAGE], out["pages"]


def test_o3_drive_movie_skip_turns_a_page_that_comes_instead(game):
    """A page that opens instead of the skip dialog: the policy's press finds no hit area (none on this movie), the
    movie ends and a page opens before the next press is due -- the ORDINARY page rule turns it (a "page" press, the
    page in ``pages``), nothing is answered as a skip, and the visit's skip is given up there ('movie-skip missed: a
    page opened instead ...'): when a second gap follows (another movie, then a page), the policy presses nothing more.
    Break: keep the visit's row open after the page (a second press lands in the second gap)."""
    pred = _o3_pred(movies=_o3_movies(cell={"after_s": 0.25}, press_every_s=3.0))
    after = "Narrator\n“Act I.”"
    out, log, fake = _o3_movie_run(game, pred, _o3_movie_route({"movie": 120}, _O3_PAGE, {"movie": 1440}, after))
    assert not isinstance(out, Exception) and out["end"] == "reached", out
    assert len(_presses(log, "movie_skip")) == 1 and fake.answered == [], _presses(log, "movie_skip")
    row = out["movies"][0]
    assert row["outcome"] == "missed" and row["missed"].startswith("movie-skip missed: a page opened instead of the "
                                                                   "skip dialog"), row
    assert "The curtain rises." in row["missed"] and out["pages"] == [_O3_PAGE, after], out["pages"]
    whys = [r["why"] for r in log if r["k"] == "press"]
    assert whys[0] == "movie_skip" and whys[1:] and set(whys[1:]) == {"page"}, whys
    assert [m["ended"] for m in fake.movies] == ["played", "played"], fake.movies


def test_o3_drive_movie_skip_refuses_a_dialog_that_is_not_the_skip_text(game):
    """The skip answer requires the skip dialog's TEXT: here the policy's press opens a dialog that asks something
    else ("Do you want to save / the game?", Yes / No, the cursor on No). The policy refuses it (kept on its row as
    ``refused``, once) and the ordinary rules answer it -- a registered rule for it, at its default (No); pressed
    again ``press_every_s`` later, the same; after ``max_presses`` the visit gives up and the movie plays out.
    Nothing is ever answered 0. Break: match the option lines alone (the dialog is then answered YES and the movie
    ends)."""
    save = {"header": "Do you want to save\nthe game?", "options": ["Yes", "No"], "default": 1}
    pred = _o3_pred(movies=_o3_movies(cell={"after_s": 0.25}, max_presses=2))
    pred["choices"] = pred["choices"] + [{"donor": None, "sc": None, "match": "want to save", "pick": "default",
                                          "once": False, "beat": None}]
    out, log, fake = _o3_movie_run(game, pred, _o3_movie_route({"movie": 1200, "skip": save}, _O3_PAGE))
    assert not isinstance(out, Exception) and out["end"] == "reached", out
    assert fake.answered == [1, 1] and (fake.movies[0]["skips"], fake.movies[0]["ended"]) == (2, "played"), \
        (fake.answered, fake.movies)
    row = out["movies"][0]
    assert row["outcome"] == "missed" and len(row["presses"]) == 2 and row["dialog"] is None, row
    assert [r["options"] for r in row["refused"]] == [["Do you want to save\nthe game?", "Yes", "No"]], row["refused"]
    assert [(c["index"], c["rule"]) for c in out["choices"]] == [("default", 1), ("default", 1)], out["choices"]


def test_o3_drive_movie_skip_answers_an_unread_skip_dialog_at_its_default(game):
    """The policy's own press opens a dialog the skip reader refuses and NO frozen rule answers either: the skip dialog
    in a text it cannot read -- the engine localizes it (FieldHUD.cs:281: "Voulez-vous passer / la vidéo ?", Oui / Non,
    under the default US ``match``), or a prompt published EMPTY whose box lacks the match. The policy answers it at the
    game's own default, No -- the engine resumes the movie on any answer but 0 (:428-440) -- keeps it on its row as
    ``refused`` (once), and its attempts count on to 'movie-skip missed': the movie plays out, the run reaches its end,
    never a VOID, and nothing is ever answered 0. Its ``choice`` rows: index "default", rule "movie_skip_default", the
    cursor 1. A dialog no skip dialog can be -- THREE lines (the engine's has two: [PCHC=2,1]) -- is not the policy's to
    answer: with no rule for it the run VOIDs V1, the game's, as with no policy at all. Break: leave every refused
    dialog to the frozen rules (the first dialog then VOIDs V1 'game')."""
    SD = _segment_modules()
    pred = _o3_pred(movies=_o3_movies(cell={"after_s": 0.25}, max_presses=2))
    fr = {"header": "Voulez-vous passer\nla vidéo ?", "options": ["Oui", "Non"]}
    empty = {"header": "", "options": ["Yes", "No"]}
    for dialog in (fr, empty):
        out, log, fake = _o3_movie_run(game, pred, _o3_movie_route({"movie": 1200, "skip": dialog}, _O3_PAGE))
        assert not isinstance(out, Exception) and out["end"] == "reached" and out["void"] is None, (dialog, out)
        assert fake.answered == [1, 1] and (fake.movies[0]["skips"], fake.movies[0]["ended"]) == (2, "played"), \
            (dialog, fake.answered, fake.movies)
        row = out["movies"][0]
        assert row["outcome"] == "missed" and len(row["presses"]) == 2 and row["dialog"] is None, row
        assert "1 dialog(s) refused as not the skip text" in row["missed"], row["missed"]
        assert [r["options"] for r in row["refused"]] == [[dialog["header"], *dialog["options"]]], row["refused"]
        assert [(c["index"], c["rule"], c["selected"]) for c in out["choices"]] == \
            [("default", "movie_skip_default", 1)] * 2, out["choices"]
        assert out["pages"] == [_O3_PAGE], out["pages"]
    three = dict(fr, options=["Oui", "Non", "Plus tard"])
    err, log, fake = _o3_movie_run(game, pred, _o3_movie_route({"movie": 1200, "skip": three}, _O3_PAGE))
    assert isinstance(err, SD.RouteVoid) and (err.v, err.by) == ("V1", "game") and "with no rule" in str(err), err
    assert fake.answered == [] and len(_presses(log, "movie_skip")) == 1, (fake.answered, log)


def test_o2_drive_voids_a_battle_without_a_registry(game):
    """S4 is opt-in (research/o3_design.md 1.2, 1.4): O2-shaped predictions -- no ``battles`` key, or an empty
    registry -- read a battle on screen exactly as O2's driver did: rule 5's V10 (game) with O2's message, the cell
    the place and SC it happened in, and nothing fought. The one test that puts a battle up under O2's shape (G12 runs
    it). Break: run rule 1b with no registry (V10 with the registry's message)."""
    SD = _segment_modules()
    for registry in (None, []):
        fake = FakeGame(game)
        pred = _o2_pred([])
        if registry is not None:
            pred["battles"] = registry
        with session(game, fake) as g:
            _o2_start(g, fake)
            fake.control = False
            g.start_battle(338)
            with pytest.raises(SD.RouteVoid) as err:
                _o2_drive(g, pred, budget=20.0)
        assert (err.value.v, err.value.by, err.value.cell) == ("V10", "game", [30820, 1000]), err.value
        assert str(err.value) == "a battle in 30820 (place 30820) at SC 1000, where the route registers none", err.value
        assert not fake.battle_commands and not [s for s in fake.executed if s[0] in ("battlecmd", "menus")]


def _o3_raw_warp(g, field):
    """start_run's warp shape (no wait for control): the raw step, then the field and FieldHUD."""
    g.send(f"warp {field} -1 -1")
    return g.wait_for(lambda s: s.field_id == field and s.ui_state == "FieldHUD", timeout=10.0, what=f"field {field}")


def _o3_quick_ladder(g):
    """The recovery ladder's two waiting rungs on short clocks: a combo the game swallows would otherwise cost the
    soft reset's 45 s (and close_ui's 20 s) each time."""
    import functools
    g.soft_reset = functools.partial(Session.soft_reset, g, timeout=3.0)
    g.close_ui = functools.partial(Session.close_ui, g, timeout=3.0)


def test_segment_end_run_from_a_battle_on_the_fake(game):
    """S3 on H9's knobs (research/o3_design.md 1.2, B5): the fake as the engine -- a warp refused off the field and
    landing without control, the soft reset where the engine fires it. From BattleHUD mid-fight, end_run resets at
    once: the title, NO warp executed (rows recover-in-battle, recover-reset). From the BattleResult phase of a
    battle's four-phase exit it waits for the field the battle hands over, warps to ``recovery`` (whose script gives
    control, as 4600's does) and climbs the ladder to the title (recover-battle-ending, recover-battle-ended,
    recover-warp). With ``soft_reset_ui`` left at today's default, from BattleHUD the combo is swallowed and end_run
    raises "the title could not be restored". Break: reset in every battle state (in BattleResult the title never
    comes)."""
    from harness.fakegame import SOFT_RESET_ENGINE_UI
    ST = _segment_trace()
    seg = ST.Segment()
    seg.recovery = 30821

    def fake_for(ui, **exit_):
        fake = FakeGame(game)
        fake.warp_field_only, fake.warp_arrive_control = True, False
        if ui is not None:
            fake.soft_reset_ui = ui
        if exit_:
            fake.battle_exit = exit_
        return fake
    fake = fake_for(SOFT_RESET_ENGINE_UI)                    # mid-fight: the reset, no warp
    with session(game, fake) as g:
        boot(g)
        _o3_raw_warp(g, 30820)
        g.start_battle(338)
        _o3_quick_ladder(g)
        mark, log = len(fake.executed), []
        seg.end_run(g, log)
        st = g.state
    assert st.ui_state == "Title" and not st.in_battle and fake.soft_resets == 1, st
    assert log == [{"k": "recover-in-battle", "scene": 338, "ui": "BattleHUD", "result": 0}, {"k": "recover-reset"}], log
    assert not [s for s in fake.executed[mark:] if s[0] == "warp"], fake.executed[mark:]
    fake = fake_for(SOFT_RESET_ENGINE_UI, field=30810, fade_frames=10, result_frames=1200, load_frames=60,
                    arrive_control=False)                    # BattleResult: the field, the warp, the ladder
    stop = threading.Event()
    with session(game, fake) as g:
        boot(g)
        _o3_raw_warp(g, 30820)
        g.start_battle(338)
        _o3_end_on_the_fake(fake, 2)
        published(g, lambda s: s.ui_state == "BattleResult" and s.in_battle)
        _o3_quick_ladder(g)
        _o1_director(fake, stop, [(lambda f: f.field_id == 30821, lambda f: setattr(f, "control", True))])
        log = []
        try:
            seg.end_run(g, log)
        finally:
            stop.set()
        st = g.state
    assert st.ui_state == "Title" and fake.soft_resets == 1, st
    assert [r["k"] for r in log] == ["recover-battle-ending", "recover-battle-ended", "recover-warp"], log
    assert (log[0]["ui"], log[0]["result"], log[1]["field"], log[2]["field"]) == ("BattleResult", 1, 30810, 30821), log
    fake = fake_for(None)                                    # today's default set: swallowed in BattleHUD
    with session(game, fake) as g:
        boot(g)
        _o3_raw_warp(g, 30820)
        g.start_battle(338)
        _o3_quick_ladder(g)
        log = []
        with pytest.raises(HarnessError, match="the title could not be restored"):
            seg.end_run(g, log)
    assert [r["k"] for r in log] == ["recover-in-battle", "recover-reset-failed"] and fake.soft_resets == 0, log


def test_segment_end_run_waits_out_the_battle_load_on_the_fake(game):
    """S3 in a battle exit's LOAD (H9's fourth phase; the review, research/o3_design.md 11.7 #8): the scene is gone
    (``in_battle`` False) while the UI still reads BattleResult until the next field's HUD is up -- where a battle()
    that stopped before FieldHUD (V14 past ``land_cap_s``, the budget inside the landing wait) leaves the run. end_run
    takes the end sequence's path there too: it waits for the field the battle hands over (``recover-battle-ending``,
    ui BattleResult, result 1), then ``recover-battle-ended`` and the warp to ``recovery`` (``recover-warp``), then the
    title. Break: test ``in_battle`` alone (the load takes the outside-a-battle path: the warp refused off FieldHUD,
    ``recover-warp-failed``, the ladder from BattleResult)."""
    from harness.fakegame import SOFT_RESET_ENGINE_UI
    ST = _segment_trace()
    seg = ST.Segment()
    seg.recovery = 30821
    fake = FakeGame(game)
    fake.warp_field_only, fake.warp_arrive_control, fake.soft_reset_ui = True, False, SOFT_RESET_ENGINE_UI
    fake.battle_exit = {"field": 30810, "fade_frames": 10, "result_frames": 10, "load_frames": 1200,
                        "arrive_control": False}
    stop = threading.Event()
    with session(game, fake) as g:
        boot(g)
        _o3_raw_warp(g, 30820)
        g.start_battle(338)
        _o3_end_on_the_fake(fake, 2)
        st = published(g, lambda s: s.ui_state == "BattleResult" and not s.in_battle)
        assert st.field_id == 30810 and st.battle_result == 1, st          # premise: the load, its lag published
        _o3_quick_ladder(g)
        _o1_director(fake, stop, [(lambda f: f.field_id == 30821, lambda f: setattr(f, "control", True))])
        log = []
        try:
            seg.end_run(g, log)
        finally:
            stop.set()
        st = g.state
    assert st.ui_state == "Title" and fake.soft_resets == 1, st
    assert [r["k"] for r in log] == ["recover-battle-ending", "recover-battle-ended", "recover-warp"], log
    assert (log[0]["ui"], log[0]["result"], log[1]["field"], log[2]["field"]) == ("BattleResult", 1, 30810, 30821), log


def test_segment_session_end_leaves_a_movie_on_the_fake(game, tmp_path_factory):
    """S5 on H9's movie beat (research/o3_design.md 1.2, B5): a session whose last run stops inside a movie (61's
    FMV003, where the soft reset is dead). With ``end_session_warps`` the session ends through end_run: the warp to
    ``recovery`` ends the movie (the field load destroys MBG), that field gives control, the ladder reaches the title,
    and ``session["ended"]`` says so. Without it (O1's and O2's default) the bare ladder where the run stopped cannot:
    the movie swallows the combo and the game is left in it. Break: ignore the flag."""
    import shutil
    from harness.fakegame import SOFT_RESET_ENGINE_UI
    control = tmp_path_factory.mktemp("control")
    shutil.copytree(game, control, dirs_exist_ok=True)      # a second fake install, as untouched as the first

    def one(root, warps):
        stub, _pred, calls = _stub_segment(root, cue=lambda n, side: "reached", order=("S",), min_covered=1,
                                           rerun={"max": 0})
        stub.end_session_warps = warps
        fake = FakeGame(root)
        fake.warp_field_only, fake.warp_arrive_control, fake.soft_reset_ui = True, False, SOFT_RESET_ENGINE_UI
        real = stub.drive

        def drive(g, pred, side, log, *, deadline, progress=None):
            out = real(g, pred, side, log, deadline=deadline, progress=progress)
            fake.scene({"movie": 10 ** 6, "skip": dict(_O3_SKIP)}, control=False)       # the run stops in a movie
            published(g, lambda s: not s.control and not s.dialog_open)
            return out
        stub.drive = drive
        stop = threading.Event()
        with session(root, fake) as g:
            boot(g)
            assert g.restore_baseline()[0], "the session starts at the title, as a launch does"
            _o3_quick_ladder(g)
            _o1_director(fake, stop, [(lambda f: f.field_id == 30821, lambda f: setattr(f, "control", True))])
            try:
                stub.run(g)
            finally:
                stop.set()
            at = (g.state.ui_state, fake._movie is not None)
        assert calls == ["S"]
        return json.loads((root / "run" / "zz_session.json").read_text(encoding="utf-8")), at, fake

    sess, at, fake = one(game, True)
    assert sess["ended"] == {"log": [{"k": "recover-warp", "field": 30821}], "ok": True, "why": ""}, sess.get("ended")
    assert at == ("Title", False) and fake.movies[0]["ended"] == "warp", (at, fake.movies)
    sess, at, fake = one(control, False)
    assert "ended" not in sess and at == ("FieldHUD", True), (sess.keys(), at)
    assert fake.movies[0]["end"] is None and fake.soft_resets == 1, (fake.movies, fake.soft_resets)


# ---- O3 itself (studies/story-trace/o3_prima_vista.py; research/o3_design.md section 9, PART C). The draft's members
# are O1's deployed chain; the freeze refuses to overwrite, and refuses a registry row battle_of refuses; the launch's
# own readers (P-DONOR-LOG, P-LAUNCH), P-STOCK-BATTLE and P-SETTINGS, each pure, on synthetic logs, folders and inis.

def _o3_module():
    sys.path.insert(0, str(REPO / "studies" / "story-trace"))
    import o3_prima_vista as P
    return P


def test_o3_draft_members_are_o1s_chain(tmp_path):
    """The draft's members and names are O1's deployed chain, read from its campaign.toml (research/o3_design.md 1.3):
    exactly o1_forks.json's twenty, the route members 31211 -> 61, 31212 -> 62, 31213 -> 63, the start 61 / 31211 and
    the end real 64; o3_forks.json carries the same members and names, deployed, nothing to relaunch, and names both
    legacy defects (the US-bytecode languages, uk's US text). A campaign with any other member -- or another name -- is
    refused. Break: drop the assertion (the draft would register another chain). The chain is a machine-local build:
    where it is not, this SKIPS (and says so) -- never a pass."""
    P = _o3_module()
    if not (P.CHAIN_DIR / "campaign.toml").is_file():
        pytest.skip(f"O1's chain is not built here ({P.CHAIN_DIR}): the O3 draft reads its members from it")
    pred = P.draft_predictions()
    o1 = json.loads(P.O1_MANIFEST.read_text(encoding="utf-8"))
    assert pred["members"] == o1["members"] and pred["names"] == o1["names"], pred["members"]
    assert {f: pred["members"][str(f)] for f in (31211, 31212, 31213)} == {31211: 61, 31212: 62, 31213: 63}
    assert pred["start"] == {"S": 61, "F": 31211} and pred["route"] == [61, 62, 63] and pred["end_fields"] == [64]
    man = json.loads(P.MANIFEST.read_text(encoding="utf-8"))
    assert man["members"] == pred["members"] and man["names"] == pred["names"], man
    assert man["deployed"] is True and man["relaunch_needed"] is False and man["text_block"] == 2, man
    assert man["route_members"] == {"31211": 61, "31212": 62, "31213": 63}, man
    assert any("US bytecode" in d for d in man["known_defects"]) and any("uk/field/2.mes" in d
                                                                          for d in man["known_defects"]), man
    text = (P.CHAIN_DIR / "campaign.toml").read_text(encoding="utf-8")
    for old, new in (("source = 63", "source = 64"), ('name = "O1_TH_STG"', 'name = "O1_TH_STG_X"')):
        assert old in text, old
        bad = tmp_path / "campaign.toml"
        bad.write_text(text.replace(old, new, 1), encoding="utf-8")
        with pytest.raises(AssertionError, match="not O1's twenty"):
            P.chain_from_campaign(bad)


def test_o3_freeze_refuses_an_existing_file(tmp_path, monkeypatch):
    """The freeze (research/o3_design.md 0.1, 2.1): the draft is written ONCE -- LF, sorted keys, its sha the bytes' --
    and a second freeze onto the same file refuses, leaving it byte for byte; the CLI's --freeze refuses the same way.
    Before anything is written, every registry row passes segment_drive.battle_of: a row whose ``won`` would count a
    defeat (3) won is refused and no file appears. The lead freezes after the rehearsals: the real
    o3_predictions_v1.json is never touched here, and the chain the draft reads is given (a synthetic one, O1's ids),
    so the rule is tested wherever the suite runs. Break: drop the battle_of pass (the bad row freezes)."""
    import hashlib
    P = _o3_module()
    o1 = json.loads(P.O1_MANIFEST.read_text(encoding="utf-8"))
    chain = ({int(f): int(d) for f, d in o1["members"].items()},
             {int(f): f"O3_SYNTH_{d}" for f, d in o1["members"].items()})
    monkeypatch.setattr(P, "chain_from_campaign", lambda *a, **k: chain)
    path = tmp_path / "o3_predictions_v1.json"
    sha = P.O3.freeze(path)
    data = path.read_bytes()
    assert sha == hashlib.sha256(data).hexdigest() and b"\r" not in data and data.endswith(b"\n")
    assert data.decode("utf-8") == json.dumps(P.draft_predictions(), indent=1, sort_keys=True) + "\n"
    path.write_bytes(data + b" ")                          # the file as frozen, plus one byte a re-freeze would lose
    with pytest.raises(SystemExit, match="frozen"):
        P.O3.freeze(path)
    seg = P.O3Segment()
    seg.predictions = path
    with pytest.raises(SystemExit, match="frozen"):
        seg.main(["--freeze"])
    assert path.read_bytes() == data + b" "
    good = P.draft_predictions
    monkeypatch.setattr(P, "draft_predictions", lambda: dict(good(), battles=[dict(P.battle_row(), won=[1, 2, 3])]))
    fresh = tmp_path / "o3_predictions_v2.json"
    with pytest.raises(ValueError, match="won is"):
        P.O3.freeze(fresh)
    assert not fresh.exists(), "a refused row was frozen"


#: The launch's Memoria.log as today's reads (2026-09-30): its first line's stamp, a collision for a donor off the
#: route (351, one of Dali's stacked forks), the patchers' "Initialized".
_O3_LOG_HEAD = "30.09.2026 19:27:42 |M| [WindowManager] Moving window to (2045,33) with size (1286,749) on monitor 0\n"
_O3_LOG_351 = ("30.09.2026 19:27:44 |W| [DataPatchers] ForkDonorPatch: donor field 351 is forked by both 30831 and "
               "30842 -> remap DISABLED (ambiguous); an event-battle/scripted-boss after-warp from either fork will "
               "LEAK to real field 351. Deploy only one fork of donor 351 at a time.\n")
_O3_LOG_DONE = "30.09.2026 19:27:44 |M| [DataPatchers] Initialized\n"


def test_o3_p_donor_log_reads_the_launchs_warnings():
    """P-DONOR-LOG (research/o3_design.md 6.2; section 8's p-donor-log unit): the engine's donor map is fixed at
    launch and it logs a collision only as a warning (DataPatchers.cs:156-160), so the launch's own Memoria.log is
    read -- "Initialized" (the patchers ran) and no collision line for 61, 62 or 63. Today's shape (a collision for 351,
    off the route) PASSES; a line "donor field 63 is forked by both 31213 and 31299" FAILS naming it; a log with no
    "Initialized" FAILS (it does not show the patchers ran); a donor 630 is not 63. Break: drop the "Initialized"
    requirement."""
    P = _o3_module()
    route = (61, 62, 63)
    ok, detail = P.p_donor_log(_O3_LOG_HEAD + _O3_LOG_351 + _O3_LOG_DONE, route)
    assert ok and "[351]" in detail, detail
    assert P.donor_log(_O3_LOG_HEAD + _O3_LOG_351 + _O3_LOG_DONE, route) == (True, [])
    w63 = _O3_LOG_351.replace("351", "63").replace("30831 and 30842", "31213 and 31299")
    ok, detail = P.p_donor_log(_O3_LOG_HEAD + _O3_LOG_351 + w63 + _O3_LOG_DONE, route)
    assert not ok and "donor field 63 is forked by both 31213 and 31299" in detail, detail
    assert P.donor_log(_O3_LOG_HEAD + w63 + _O3_LOG_DONE, route) == (True, [w63.strip()])
    ok, detail = P.p_donor_log(_O3_LOG_HEAD + _O3_LOG_351, route)
    assert not ok and "Initialized" in detail, detail
    assert not P.p_donor_log("", route)[0] and not P.p_donor_log(None, route)[0]
    w630 = _O3_LOG_351.replace("351", "630")
    assert P.p_donor_log(_O3_LOG_HEAD + w630 + _O3_LOG_DONE, route)[0], "630 is no route donor"


def _o3_touch(path, when, frac=0.0):
    ts = when.timestamp() + frac
    os.utime(path, (ts, ts))


def test_o3_p_launch_fails_a_patch_file_newer_than_the_launch(tmp_path):
    """P-LAUNCH (research/o3_design.md 6.2, claim integrity #1; section 8's p-launch unit): the launch read its patch
    files once (DataPatchers.Initialize), so every stacked folder's DictionaryPatch/BattlePatch/TextPatch/
    ForkDonorPatch and every Memoria.ini the engine read must be EARLIER than the launch's first Memoria.log stamp, to
    the second. Synthetic folders under a log whose first line is 30.09.2026 19:27:42: all older -- PASS; a
    ForkDonorPatch.txt that HOLDS `31213 63` (P-DONOR passes it) but was touched at 19:27:50 -- FAIL "relaunch" naming
    it; a same-second mtime (19:27:42.4) -- FAIL; Memoria.ini after -- FAIL; a TextPatch.txt after -- FAIL; a stacked
    folder's own Memoria.ini after -- FAIL; a first line with no stamp -- FAIL; a folder with no patch file -- PASS
    (nothing to date). Break: compare with <= (the same second passes)."""
    import datetime as dt
    P = _o3_module()
    log = _O3_LOG_HEAD + _O3_LOG_DONE
    launched = P.launch_time(log)
    assert launched == dt.datetime(2026, 9, 30, 19, 27, 42), launched
    game = tmp_path / "game"
    root, bare = game / "FF9CustomMap", game / "MoguriVideo"
    root.mkdir(parents=True)
    bare.mkdir()
    (game / "Memoria.ini").write_text("[Battle]\nSpeed = 5\n", encoding="utf-8")
    (root / "DictionaryPatch.txt").write_text("FieldScene 31213 11 O1_TSHP_TH_STG O1_TSHP_TH_STG 2\n", encoding="utf-8")
    (root / "BattlePatch.txt").write_text("Battle: 67\nMusic: 0\n", encoding="utf-8")
    fdp = root / "ForkDonorPatch.txt"
    fdp.write_text("31211 61\n31212 62\n31213 63\n", encoding="utf-8")
    before = dt.datetime(2026, 9, 30, 19, 27, 4)
    for p, when in ((game / "Memoria.ini", dt.datetime(2026, 9, 24, 12, 57, 35)), (root / "DictionaryPatch.txt", before),
                    (root / "BattlePatch.txt", dt.datetime(2026, 9, 29, 21, 6, 41)), (fdp, before)):
        _o3_touch(p, when)
    roots = [root, bare]

    def check():
        return P.launch_check(P.launch_files(game, roots), launched)
    ok, detail = check()
    assert ok and "4 file(s) older than the launch at 30.09.2026 19:27:42" in detail, detail
    pred = {"route": [61, 62, 63], "members": {"31211": 61, "31212": 62, "31213": 63}}
    for when, frac in ((dt.datetime(2026, 9, 30, 19, 27, 50), 0.0), (launched, 0.4)):
        _o3_touch(fdp, when, frac)
        assert P.p_donor(pred, roots)[0], "the row is in the file"
        ok, detail = check()
        assert not ok and "relaunch:" in detail and "ForkDonorPatch.txt" in detail, (when, detail)
        assert when.strftime("%H:%M:%S") in detail, detail
    _o3_touch(fdp, before)
    _o3_touch(game / "Memoria.ini", dt.datetime(2026, 9, 30, 19, 30, 0))
    ok, detail = check()
    assert not ok and "Memoria.ini changed at 30.09.2026 19:30:00" in detail, detail
    _o3_touch(game / "Memoria.ini", dt.datetime(2026, 9, 24, 12, 57, 35))
    for extra in (root / "TextPatch.txt", bare / "Memoria.ini"):
        extra.write_text("x\n", encoding="utf-8")
        _o3_touch(extra, dt.datetime(2026, 9, 30, 19, 28, 0))
        ok, detail = check()
        assert not ok and extra.name in detail and "relaunch:" in detail, (extra, detail)
        extra.unlink()
    assert check()[0]
    assert P.launch_time("[DataPatchers] Initialized\n") is None and P.launch_time("") is None
    ok, detail = P.launch_check(P.launch_files(game, roots), P.launch_time("[DataPatchers] Initialized\n"))
    assert not ok and "relaunch" in detail and "cannot be dated" in detail, detail
    ok, detail = P.launch_check(P.launch_files(tmp_path / "nothing", [bare]), launched)
    assert ok and detail.startswith("0 file(s)"), detail


#: Battle 338's names as its US battle text gives them (BSC_TH_E002: three enemies, then six attacks).
_O3_338_NAMES = ["King Leo", "Zenero", "Benero", "Taste steel!", "Poly", "Clamp Pinch", "Pyro", "Clamp Pinch", "Pyro"]


def test_o3_p_stock_battle_finds_an_override_of_338(tmp_path):
    """P-STOCK-BATTLE (research/o3_design.md 6.2, claim integrity #4; section 8's p-stock-battle unit): battle 338
    must be stock on BOTH sides, over every stacked folder. Today's live shape -- FF9CustomMap's four LEDGER scene
    overrides, its BattlePatch `Battle:` 67, 67, 336, 337, 334, 335 and FF9CustomMap-msgs's 67 -- PASSES; plus
    `BattleMap/BattleScene/EVT_BATTLE_TH_E002/dbfile0000.raw16.bytes` FAILS; plus
    `EventBinary/Battle/fr/EVT_BATTLE_TH_E002.eb.bytes` FAILS; plus `Battle: 338` or `Battle: BSC_TH_E002` FAILS; plus
    `AnyEnemyByName: King Leo` FAILS (a name selector applies to every scene holding the name); plus
    `AnyEnemyByName: Goblin` PASSES, listed. And DictionaryPatch (the review, research/o3_design.md 11.7 #4): today's
    four LEDGER `BattleScene` lines PASS, listed; plus `BattleScene 338 LEDGER_A BBG_B251` -- battle 338 rebound to
    another scene, script and background, no file under TH_E002's name, no selector: SceneData's setter overwrites the
    reverse entry the battle is looked up by -- FAILS (c); plus `BattleScene 30999 TH_E002 BBG_B065` (BSC_TH_E002's
    forward entry repointed: 338's sequence, text and background follow it) FAILS (c); a `FieldScene 338 ...` line
    PASSES (it sets only EventDB[338], which a battle never reads), and so does a `BattleScene` line whose id does not
    parse (the engine skips it). Break: drop the name selectors; or drop the DictionaryPatch read."""
    P = _o3_module()
    res = "StreamingAssets/assets/resources"
    n = {"case": 0}
    scenes = ("BattleScene 30871 LEDGER_A BBG_B251", "BattleScene 30872 LEDGER_B BBG_B252",
              "BattleScene 30881 LEDGER1W BBG_B253", "BattleScene 30882 LEDGER1S BBG_B254")

    def stack(paths=(), lines=(), dict_lines=()):
        n["case"] += 1
        base = tmp_path / f"stack{n['case']}"
        custom, msgs = base / "FF9CustomMap", base / "FF9CustomMap-msgs"
        for scene in ("LEDGER1S", "LEDGER1W", "LEDGER_A", "LEDGER_B"):
            for rel in (f"{res}/BattleMap/BattleScene/EVT_BATTLE_{scene}/dbfile0000.raw16.bytes",
                        f"{res}/commonasset/eventengine/eventbinary/Battle/us/EVT_BATTLE_{scene}.eb.bytes"):
                (custom / rel).parent.mkdir(parents=True, exist_ok=True)
                (custom / rel).write_bytes(b"x")
        for rel in paths:
            (custom / rel).parent.mkdir(parents=True, exist_ok=True)
            (custom / rel).write_bytes(b"x")
        (custom / "BattlePatch.txt").write_text(
            "".join(f"Battle: {b}\nMusic: 0\n\n" for b in (67, 67, 336, 337, 334, 335)) + "".join(f"{x}\n" for x in lines),
            encoding="utf-8")
        (custom / "DictionaryPatch.txt").write_bytes(("﻿FieldScene 31213 11 O1_TSHP_TH_STG O1_TSHP_TH_STG 2\r\n"
                                                      + "".join(f"{x}\r\n" for x in (*scenes, *dict_lines))
                                                      ).encode("utf-8"))
        msgs.mkdir(parents=True)
        (msgs / "BattlePatch.txt").write_text("Battle: 67\nMusic: 0\n", encoding="utf-8")
        return [custom, msgs]

    def judge(**kw):
        ok, detail, _info = P.battle_stock(stack(**kw), 338, _O3_338_NAMES)
        return ok, detail
    ok, detail = judge()
    assert ok and "EVT_BATTLE_LEDGER1S" in detail and "FF9CustomMap-msgs Battle: 67" in detail, detail
    assert "no name selector" in detail, detail
    assert "BattleScene lines (none on 338 or TH_E002): FF9CustomMap 30871 LEDGER_A, 30872 LEDGER_B, 30881 LEDGER1W, " \
           "30882 LEDGER1S" in detail, detail
    for line, says in (("BattleScene 338 LEDGER_A BBG_B251", "rebinds battle 338 to BSC_LEDGER_A"),
                       ("BattleScene 30999 TH_E002 BBG_B065", "repoints BSC_TH_E002 to 30999")):
        ok, detail = judge(dict_lines=[line])
        assert not ok and f"(c) FF9CustomMap/DictionaryPatch.txt '{line}' {says}" in detail, (line, detail)
    for line in ("FieldScene 338 11 X X 2", "BattleScene x338 LEDGER_A BBG_B251", "BattleScene 30999 th_e002 BBG_B065"):
        ok, detail = judge(dict_lines=[line])
        assert ok, (line, detail)
    for paths in ([f"{res}/BattleMap/BattleScene/EVT_BATTLE_TH_E002/dbfile0000.raw16.bytes"],
                  [f"{res}/commonasset/eventengine/EventBinary/Battle/fr/EVT_BATTLE_TH_E002.eb.bytes"]):
        ok, detail = judge(paths=paths)
        assert not ok and "(a)" in detail and "EVT_BATTLE_TH_E002" in detail, detail
    for line in ("Battle: 338", "Battle: BSC_TH_E002", "AnyEnemyByName: King Leo", "AnyAttackByName: Clamp Pinch"):
        ok, detail = judge(lines=["", line, "MaxHP: 1"])
        assert not ok and "(b)" in detail and line.split(": ", 1)[1] in detail, (line, detail)
    ok, detail = judge(lines=["AnyEnemyByName: Goblin", "MaxHP: 1"])
    assert ok and "AnyEnemyByName: Goblin" in detail, detail
    ok, detail = judge(lines=["// AnyEnemyByName: King Leo"])       # a comment line: the engine skips it
    assert ok, detail


def _o3_ini(settings, *, extra=""):
    lines = ["[Mod]", "FolderNames = \"FF9CustomMap\"", ""]
    for sec, kv in settings.items():
        lines += [f"[{sec}]", "\t; a comment line, as Memoria.ini's are"]
        lines += [f"{k} = {v}" for k, v in kv.items()]
        lines.append("")
    return "\n".join(lines) + extra


def test_o3_settings_read_the_ini_the_engines_way(tmp_path):
    """P-SETTINGS (research/o3_design.md 6.2, 4.13; section 8's p-settings unit): Memoria.ini read the ENGINE's way
    (Memoria.Prime/Ini/IniReader.cs) -- an ini equal to 4.13 PASSES; `Speed = 0` FAILS naming it; a later duplicate
    assignment wins (either way round); a `;` comment line and an inline `; ...` are no value; `;;` adds one `;` and
    the value ends at the next other character (ReadPair's escape falls through: `a;;b` is "a;"); sections and keys are
    case-sensitive (`speed = 0` is no Speed); a stacked folder's own Memoria.ini is read over the root's, the first
    folder's winning. Break: let the FIRST assignment win; or skip the re-armed escape (`a;;b` reads "a;b")."""
    P = _o3_module()
    want = P.SETTINGS
    game = tmp_path / "game"
    game.mkdir()
    ini = game / "Memoria.ini"

    def judge(text, roots=()):
        ini.write_text(text, encoding="utf-8")
        return P.p_settings(want, P.install_settings(game, list(roots), want))
    ok, detail = judge(_o3_ini(want))
    assert ok and detail.startswith("23 keys as frozen") and 'DialogProgressButtons "Confirm"' in detail, detail
    slow = {**want, "Battle": dict(want["Battle"], Speed="0")}
    ok, detail = judge(_o3_ini(slow))
    assert not ok and detail == "[Battle] Speed = '0' (frozen '5')", detail
    assert not judge(_o3_ini(want, extra="\n[Battle]\nSpeed = 0\n"))[0], "the later assignment wins"
    assert judge(_o3_ini(slow, extra="\n[Battle]\nSpeed = 5\n"))[0], "the later assignment wins"
    assert judge(_o3_ini(want, extra="\n[Battle]\n; Speed = 0\n#Speed = 0\n"))[0], "a comment line is no value"
    assert judge(_o3_ini(want, extra="\n[Battle]\nSpeed = 5 ; the default is 0\n"))[0], "an inline comment"
    # IniReader.ReadPair's escape branch has no `continue`: the `;` it appends arms the escape again, so the value
    # ends at the next character that is not a `;` (IniReader.cs:169-185) -- `a;;b` is "a;", never "a;b"
    for raw, value in (("a;;b ; c", "a;"), ("a;;;;b", "a;;;"), ("a;;", "a;"), ("a;b", "a"), (";x", "")):
        assert P.ini_settings(f"[Lang]\nText = {raw}\n") == {"Lang": {"Text": value}}, (raw, value)
    assert P.ini_settings("[Battle]\nSpeed = 5\nOther = 1\n[Graphics]\nTileSize = 64\n",
                          {"Battle": ["Speed", "SFXRework"]}) == {"Battle": {"Speed": "5"}}, "keys: only those it sets"
    assert judge(_o3_ini(want, extra="\n[Battle]\nspeed = 0\n[battle]\nSpeed = 0\n"))[0], "case-sensitive"
    first, second = tmp_path / "FF9CustomMap", tmp_path / "MoguriMain"
    first.mkdir()
    second.mkdir()
    (second / "Memoria.ini").write_text("[Battle]\nSpeed = 0\n", encoding="utf-8")
    ok, detail = judge(_o3_ini(want), roots=[first, second])
    assert not ok and "[Battle] Speed = '0'" in detail, detail
    (first / "Memoria.ini").write_text("[Battle]\nSpeed = 5\n", encoding="utf-8")
    assert judge(_o3_ini(want), roots=[first, second])[0], "the first folder's wins"
    (second / "Memoria.ini").write_text("[Graphics]\nTileSize = 64\n", encoding="utf-8")
    (first / "Memoria.ini").unlink()
    assert judge(_o3_ini(want), roots=[first, second])[0], "today's MoguriMain: no key of 4.13"
    ini.unlink()
    ok, detail = P.p_settings(want, P.install_settings(game, [], want))
    assert not ok and "[Battle] Enabled = None (frozen '1')" in detail, detail


# ---- O3's rehearsals (studies/story-trace/o3_rehearse.py; research/o3_design.md section 7, PART C, C3), on the fake as
# O3's tests model the engine (H9): warps land without control and are refused off the field, the soft reset fires in
# the engine's UI states. end_run's recovery rung is a registered field off every route whose script hands control
# over, as 4600's does.

def _o3_rehearse_module():
    sys.path.insert(0, str(REPO / "studies" / "story-trace"))
    import o3_rehearse as R
    return R


_O3_RECOVERY = 30899


def _o3_launch_files(game):
    """The fake install as a launch reads it: Memoria.ini stacking FF9CustomMap, the 4.13 settings and the in-game
    language in it; the recovery field registered; every file dated an hour back; a Memoria.log whose first line dates
    the launch NOW, the patchers' 'Initialized' and the US localization in it."""
    P = _o3_module()
    patch = game / "FF9CustomMap" / "DictionaryPatch.txt"
    patch.write_text(patch.read_text(encoding="utf-8")
                     + f"FieldScene {_O3_RECOVERY} 11 RECOVERY RECOVERY {_O3_RECOVERY}\n", encoding="utf-8")
    (game / "Memoria.ini").write_text(_o3_ini(P.SETTINGS) + "\n[VoiceActing]\nForceLanguage = -1\n", encoding="utf-8")
    back = time.time() - 3600
    for p in [game / "Memoria.ini", *(game / "FF9CustomMap").iterdir()]:
        if p.is_file():
            os.utime(p, (back, back))
    now = time.strftime("%d.%m.%Y %H:%M:%S")
    (game / "x64" / "Memoria.log").write_text(
        f"{now} |M| [WindowManager] Moving window to (2045,33)\n{now} |M| [DataPatchers] Initialized\n"
        f"{now} |M| Updating text localization [English(US)]\n", encoding="utf-8")


def _o3_grant_in(fake, stop, field=_O3_RECOVERY):
    """The recovery field's script on the fake: control handed over whenever he stands there idle without it."""
    def loop():
        while not stop.is_set():
            if fake.field_id == field and not fake.control and fake.ui_state == "FieldHUD" and not fake._beats:
                fake.control = True
            time.sleep(0.005)
    threading.Thread(target=loop, daemon=True).start()


def _o3_rehearse_pred(**over):
    """_o3_pred with what O3's trace summary reads too: the legacy battle noise, landing.before (62's ip1285 on the
    fake's places), the end state, the SC and FieldEntrance bytes."""
    return _o3_pred(noise=[{"not_m": 1, "target": "Global.Byte[206]", "why": "King Leo's AI, on the fake"}],
                    landing={"before": {"place": 30821, "sid": 4, "tag": 1, "ip": 1285, "target": "Global.Int16[2]",
                                        "value": 0}},
                    end_state={"Global.Int16[2]": 0}, sc_bytes=[0, 1], entrance_bytes=[2, 3], **over)


#: 338's names on the fake: P-STOCK-BATTLE's census, standing in for the install's scene read.
_O3_CENSUS = staticmethod(lambda name: {"enemies": ["King Leo", "Zenero", "Benero"], "attacks": ["Taste steel!"]})


def test_o3_rehearse_plumbing_on_the_fake(game):
    """C3 (research/o3_design.md 7.1-7.2): one traced stage on the fake, chosen by ``O3_STAGE`` as a launch chooses it
    (another stage, which would run too, does not), played from "61" (a movie, then a page) through "62" (a page, then
    battle 338: King Leo's latch, the four-phase exit into "63") to "63" (a page) and the end "64": the capabilities
    (P-CAP, P-OBJECTS, P-LANG, P-DONOR-LOG and P-LAUNCH on the launch's own Memoria.log), the launch's readings (the
    settings, P-SETTINGS, P-STOCK-BATTLE), New Game, the raw warp at entrance 0 and SC 1155, the beat-table driver with
    the recorder on every poll, the trace collected, end_run to the title through the recovery warp, and
    o3_rehearsal.json holding every section of 7.2 -- no control grant, the pages, the published choices, the press
    evidence (the leave's presses among them), the battle rows with battle_epoch0, fight()'s and leave_battle()'s own
    records, the longest no-progress stretch, the movie's arrival and first page, the end (its state, end_run's
    result and its recovery rows) and O3's trace summary (the start residue, the battle-mode rows, the first field row
    after 62's ip1285, the end cut's row). The rehearsal report prints them. The stage order a launch takes is pinned
    too. Break: drop the battle rows from the record."""
    P, R = _o3_module(), _o3_rehearse_module()
    assert R.select(R.STAGES, env={}) == ["R-START", "F-SMOKE", "R-62", "R-FULL", "R-BATTLE-VOID"]
    assert R.select(R.STAGES, 61, env={}) == ["R-START"] and R.select(R.STAGES, 62, env={}) == ["R-62"]
    assert R.select(R.STAGES, env={"O3_STAGE": "R-SKIP"}) == ["R-SKIP"]
    with pytest.raises(ValueError, match="no stage"):
        R.select(R.STAGES, env={"O3_STAGE": "R-NONE"})
    _o3_launch_files(game)
    stages = {"R-TEST": {"field": 30820, "entrance": 0, "sc": 1155, "end": [_O3_END], "runs": 1, "run_s": 120,
                         "cost_s": 5, "movie": {"donor": 30820}, "settles": "the plumbing"},
              "R-OTHER": {"field": 30821, "entrance": 0, "sc": 1155, "end": [_O3_END], "runs": 1, "run_s": 5,
                          "cost_s": 1, "settles": "never run: O3_STAGE names R-TEST"}}
    pages = ("Narrator\n“Ladies and gentlemen!”", "Cinna\n“Act I!”", "Zidane\n“Phew.”")
    fake = _o3_fake(game, exit_to=30810)
    seen = {}

    def bit191(f, ip):
        f.script_store(0, 0, ip, 191 >> 3, "Bit", 0, bit=191)

    def fight(f):
        f.script_store(4, 1, 1285, 2, "Int16", 0)                       # landing.before: 62's chain row
        seen["epoch"] = f.battle_epoch + 1
        f.start_battle(338, units=_o3_units())
        f.script_store(1, 1, 267, 206, "Byte", 77)                      # King Leo's AI store: a battle-mode row
    phases = [(lambda f: f.field_id == 30820 and f.story_on,
               lambda f: (bit191(f, 22), f.scene({"movie": 120}, pages[0], control=False))),
              (lambda f: f.field_id == 30820 and _o3_idle(f) and f.movies and f.movies[-1]["end"] is not None,
               lambda f: (_o2_move(f, 30821), bit191(f, 26), f.scene(pages[1], control=False))),
              (lambda f: f.field_id == 30821 and _o3_idle(f), fight),
              (lambda f: f.battle_epoch == seen.get("epoch") and f.field_id == 30810 and _o3_idle(f),
               lambda f: (bit191(f, 22), f.scene(pages[2], control=False))),
              (lambda f: f.field_id == 30810 and _o3_idle(f), lambda f: (_o2_move(f, _O3_END), bit191(f, 22)))]
    stop = threading.Event()
    with session(game, fake) as g:
        boot(g)
        assert g.restore_baseline()[0], "a launch starts at the title"
        _o1_director(fake, stop, phases)
        _o3_grant_in(fake, stop)
        try:
            R.run(g, stages=stages, pred=_o3_rehearse_pred(), floor_for=lambda d, closed: _flat_bgi(),
                  prior_for=lambda d: _prior(), stock=lambda fid: None, recovery=_O3_RECOVERY,
                  env={"O3_STAGE": "R-TEST"}, census=_O3_CENSUS.__func__)
        finally:
            stop.set()
        title = g.state.ui_state
    run_dir = game / "run"
    doc = json.loads((run_dir / "o3_rehearsal.json").read_text(encoding="utf-8"))
    assert list(doc["stages"]) == ["R-TEST"] and doc["stages_run"] == ["R-TEST"] and doc.get("finished"), doc.keys()
    caps = {c[1].split(":")[0]: c[0] for c in doc["capabilities"]}
    assert caps == {"P-CAP": True, "P-OBJECTS": True, "P-LANG": True, "P-DONOR-LOG": True, "P-LAUNCH": True}, \
        doc["capabilities"]
    launch = doc["launch"]
    assert launch["roots"] == ["FF9CustomMap"] and launch["settings"] == P.SETTINGS, launch
    assert [(c[0], c[1].split(":")[0]) for c in launch["checks"]] == [(True, "P-SETTINGS"), (True, "P-STOCK-BATTLE")]
    rec = doc["stages"]["R-TEST"][0]
    assert rec["outcome"]["end"] == "reached" and rec["outcome"]["why"] == f"field {_O3_END}", rec["outcome"]
    for section in ("grants", "choices", "published_choices", "pages", "evidence", "battles", "fight", "leave",
                    "no_progress", "movie", "skip", "end", "trace"):
        assert section in rec, section
    assert rec["grants"] == [] and rec["published_choices"] == [] and rec["skip"] is None, rec["grants"]
    assert [p["text"] for p in rec["pages"]] == list(pages), rec["pages"]
    whys = [p["why"] for p in rec["evidence"]["press"]]
    assert whys.count("page") >= 3 and "leave_battle" in whys, whys
    bt = rec["battles"]
    b = bt["rows"]
    assert len(b) == 1 and (b[0]["scene"], b[0]["result"], b[0]["landed"], b[0]["v"]) == (338, 2, 30810, None), b
    assert b[0]["epoch"] == bt["battle_epoch0"] + 1, bt
    assert rec["fight"]["result"] == 2 and rec["fight"]["timed_out"] is False, rec["fight"]
    assert rec["leave"]["presses"] and rec["leave"]["stopped"] in ("scene-gone", "field"), rec["leave"]
    assert rec["no_progress"]["longest_s"] >= 0 and rec["no_progress"]["where"] is not None, rec["no_progress"]
    mv = rec["movie"]
    assert None not in (mv["arrival_frame"], mv["first_page_frame"]) and mv["first_page_frame"] > mv["arrival_frame"], mv
    end = rec["end"]
    assert end["end_state"] == {"Global.Int16[2]": 0}, end
    assert end["end_run"]["ok"] and end["end_run"]["title"] and title == "Title", end["end_run"]
    assert [x["k"] for x in end["end_run"]["how"]] == ["recover-warp"], end["end_run"]["how"]
    tr = rec["trace"]
    assert tr["start"] is not None and [x[1:] for x in tr["residue_before"]] == [[0, 0, 131], [1, 0, 4]], tr
    assert tr["sc"] == [] and tr["battle"]["w"] == 1 and tr["battle"]["sites"] == ["m2 e1 t1 ip267 Global.Byte[206]"]
    assert tr["after_before"] == "30810 e0 t0 ip22 Global.Bit[191]=0", tr["after_before"]
    assert tr["end_row"] == f"w {_O3_END} e0 t0 ip22 Global.Bit[191]=0", tr["end_row"]
    assert (run_dir / rec["trace_file"]).is_file() and (run_dir / rec["log_file"]).is_file()
    report = P.rehearsal_report(run_dir)
    for want in ("== R-TEST: warp 30820 0 1155 -> [30830]", "PASS  P-LAUNCH", "PASS  P-DONOR-LOG",
                 "PASS  P-STOCK-BATTLE", "launch: settings", "grants: 0 (there must be none)",
                 "battle: scene 338 epoch", "landed 30810", "movie: ", "end: state", "rows ['recover-warp']",
                 "trace: start line", "battle-mode w rows 1", "the first field row after 62 ip1285: 30810 e0 t0 ip22",
                 f"the end cut's row: w {_O3_END} e0 t0 ip22"):
        assert want in report, (want, report[:2500])


def test_o3_rehearse_smoke_sends_no_storytrace_on_the_fake(game):
    """F-SMOKE (research/o3_design.md 7.1, F5) on the fake: three members and their stock twins, each by start_run's
    RAW warp (New Game, ``warp <id> 0 1155``, a wait for the field on FieldHUD) -- never Session.warp(), whose wait for
    control the fake (as 61-63) never grants: it would hang 60 s a warp in the game -- then the field's published
    object sids, and end_run after each warp (the recovery warp, the title). No ``storytrace`` step is ever executed
    (no fork data before the freeze). Each member's sids are compared with its twin's: two pairs equal, the third
    (a body missing) different. Break: warp through Session.warp()."""
    P, R = _o3_module(), _o3_rehearse_module()
    _o3_register(game)
    _o3_launch_files(game)
    pairs = [[31211, 30820], [31212, 30821], [31213, 30810]]
    stages = {"F-SMOKE": dict(R.STAGES["F-SMOKE"], pairs=pairs, smoke_s=0.3, warp_s=10.0)}
    sids = {31211: [2, 7, 8, 14, 16], 30820: [2, 7, 8, 14, 16], 31212: [12, 12, 20, 18], 30821: [12, 12, 20, 18],
            31213: [11, 6], 30810: [11, 6, 8]}
    fake = _o3_fake(game)
    fake.blockers = {fid: [{"x": 300.0 + 60 * i, "z": 300.0, "r": 30.0, "sid": s, "uid": 128 + i}
                           for i, s in enumerate(v)] for fid, v in sids.items()}
    stop = threading.Event()
    with session(game, fake) as g:
        boot(g)
        assert g.restore_baseline()[0]
        real_warp = g.warp

        def warp(field, *a, **k):                 # end_run's recovery rung only: the smoke itself warps raw
            if field != _O3_RECOVERY:
                raise AssertionError(f"Session.warp({field}) inside the smoke")
            return real_warp(field, *a, **k)
        g.warp = warp
        _o3_grant_in(fake, stop)
        try:
            R.run(g, stages=stages, pred=_o3_rehearse_pred(), recovery=_O3_RECOVERY, env={"O3_STAGE": "F-SMOKE"},
                  census=_O3_CENSUS.__func__)
        finally:
            stop.set()
    doc = json.loads((game / "run" / "o3_rehearsal.json").read_text(encoding="utf-8"))
    assert doc.get("finished") and "stopped" not in doc, doc.get("stopped")
    assert not [s for s in fake.executed if s[0] == "storytrace"], "a storytrace step in the smoke"
    order = [31211, 31212, 31213, 30820, 30821, 30810]
    recs = doc["stages"]["F-SMOKE"]
    assert [r["field"] for r in recs] == order, recs
    for r in recs:
        reach = r["reached"]
        assert (reach["field"], reach["ui"], reach["control"]) == (r["field"], "FieldHUD", False), r
        assert r["sids"] == sorted(sids[r["field"]]) and r["objects_status"] == "listed", r
        assert r["exceptions"] == [] and isinstance(r["log_lines"], list), r
        assert r["end_run"]["ok"] and r["end_run"]["title"], r["end_run"]
        assert [x["k"] for x in r["end_run"]["how"]] == ["recover-warp"], r["end_run"]
    warps = [s for s in fake.executed if s[0] == "warp"]
    for f in order:
        assert ["warp", str(f), "0", "1155"] in warps and ["warp", str(f), "-1", "-1"] not in warps, (f, warps)
    assert warps.count(["warp", str(_O3_RECOVERY), "-1", "-1"]) == len(order), warps
    twins = doc["twins"]["F-SMOKE"]
    assert [(t["member"], t["twin"], t["equal"]) for t in twins] == [(31211, 30820, True), (31212, 30821, True),
                                                                     (31213, 30810, False)], twins
    report = P.rehearsal_report(game / "run")
    for want in ("== F-SMOKE: the load smoke", "warp 1: 31211 -> field 31211 FieldHUD", "twin 31211 vs 30820: EQUAL",
                 "twin 31213 vs 30810: DIFFERENT"):
        assert want in report, (want, report[:2000])


def test_o3_rehearse_battle_void_stops_mid_fight_on_the_fake(game):
    """R-BATTLE-VOID (research/o3_design.md 7.1, F3) on the fake: the stage's ``battle_override`` (``max_turns`` 0)
    makes fight() raise FightTimeout at the FIRST command prompt -- V15, the driver's, 0 turns, no battlecmd executed --
    so the run stops mid-fight in BattleHUD by construction; end_run then takes S3's soft reset from BattleHUD: the rows
    recover-in-battle (ui BattleHUD, result 0) and recover-reset, no recover-reset-failed, and the title, with no warp.
    F3's rows, as the launch records them. Break: leave the override off (the fight attacks, and runs out of its
    time)."""
    _P, R = _o3_module(), _o3_rehearse_module()
    _o3_launch_files(game)
    stages = {"R-BATTLE-VOID": dict(R.STAGES["R-BATTLE-VOID"], field=30821, end=[_O3_END], run_s=60)}
    fake = _o3_fake(game, exit_to=30810)
    fake.battle_script_end = None                 # nothing would end it: no attack is ever made
    phases = [(lambda f: f.field_id == 30821 and f.story_on, lambda f: f.scene("Cinna\n“Act I!”", control=False)),
              (lambda f: f.field_id == 30821 and _o3_idle(f), lambda f: f.start_battle(338, units=_o3_units()))]
    stop = threading.Event()
    with session(game, fake) as g:
        boot(g)
        assert g.restore_baseline()[0]
        resets = fake.soft_resets                 # the launch's own way to the title, before the stage
        _o1_director(fake, stop, phases)
        try:
            R.run(g, stages=stages, pred=_o3_rehearse_pred(battles=[_o3_row(timeout_s=5)]),
                  floor_for=lambda d, closed: _flat_bgi(), prior_for=lambda d: _prior(), stock=lambda fid: None,
                  recovery=_O3_RECOVERY, env={"O3_STAGE": "R-BATTLE-VOID"}, census=_O3_CENSUS.__func__)
        finally:
            stop.set()
        title = g.state.ui_state
    doc = json.loads((game / "run" / "o3_rehearsal.json").read_text(encoding="utf-8"))
    rec = doc["stages"]["R-BATTLE-VOID"][0]
    assert (rec["outcome"]["end"], rec["outcome"]["v"], rec["outcome"]["by"]) == ("void", "V15", "driver"), rec["outcome"]
    b = rec["battles"]["rows"]
    assert len(b) == 1 and (b[0]["turns"], b[0]["timed_out"], b[0]["v"], b[0]["result"]) == (0, True, "V15", None), b
    assert rec["fight"]["turns"] == 0 and rec["fight"]["timed_out"] is True, rec["fight"]
    assert not [s for s in fake.executed if s[0] == "battlecmd"], "an attack was made"
    er = rec["end"]["end_run"]
    assert [x["k"] for x in er["how"]] == ["recover-in-battle", "recover-reset"], er["how"]
    assert (er["how"][0]["ui"], er["how"][0]["result"], er["how"][0]["scene"]) == ("BattleHUD", 0, 338), er["how"]
    assert er["ok"] and er["title"] and title == "Title" and fake.soft_resets == resets + 1, (er, fake.soft_resets)
    assert not [s for s in fake.executed if s[0] == "warp" and s[1] == str(_O3_RECOVERY)], "end_run warped"
    assert doc.get("finished") and "stopped" not in doc, doc.get("stopped")


def test_o3_rehearse_clears_the_last_fight_between_runs_on_the_fake(game):
    """Each traced run records ITS OWN fight() and leave_battle() (research/o3_design.md 7.2; the review, 11.7 #7):
    the Session clears ``last_fight`` and ``last_leave`` only at a suite member's start, so ``one()`` clears them before
    every run. Two runs of one stage on the fake: run 1 fights battle 338 from "62" (King Leo's latch, the four-phase
    exit into "63") and reaches the end; run 2 never fights -- control comes back in "62", V4 after the settle. Run 1's
    record holds its fight (result 2) and its leave (its presses); run 2's holds None for both, never run 1's. Break:
    drop the clearing (run 2 records run 1's fight and leave as its own)."""
    _P, R = _o3_module(), _o3_rehearse_module()
    _o3_launch_files(game)
    stages = {"R-TWO": {"field": 30821, "entrance": 0, "sc": 1155, "end": [_O3_END], "runs": 2, "run_s": 60,
                        "cost_s": 5, "settles": "each run's own fight and leave"}}
    fake = _o3_fake(game, exit_to=30810)
    seen = {}

    def fight(f):
        seen["epoch"] = f.battle_epoch + 1
        f.start_battle(338, units=_o3_units())
    phases = [(lambda f: f.field_id == 30821 and f.story_on, lambda f: f.scene("Cinna\n“Act I!”", control=False)),
              (lambda f: f.field_id == 30821 and _o3_idle(f), fight),
              (lambda f: f.battle_epoch == seen.get("epoch") and f.field_id == 30810 and _o3_idle(f),
               lambda f: f.scene("Zidane\n“Phew.”", control=False)),
              (lambda f: f.field_id == 30810 and _o3_idle(f), lambda f: _o2_move(f, _O3_END)),
              # run 2 (New Game and the warp again): control comes back in "62" -- no battle, V4 after the settle
              (lambda f: f.field_id == 30821 and f.story_on and not f._beats,
               lambda f: setattr(f, "control", True))]
    stop = threading.Event()
    with session(game, fake) as g:
        boot(g)
        assert g.restore_baseline()[0], "a launch starts at the title"
        _o1_director(fake, stop, phases)
        _o3_grant_in(fake, stop)
        try:
            R.run(g, stages=stages, pred=_o3_rehearse_pred(), floor_for=lambda d, closed: _flat_bgi(),
                  prior_for=lambda d: _prior(), stock=lambda fid: None, recovery=_O3_RECOVERY,
                  env={"O3_STAGE": "R-TWO"}, census=_O3_CENSUS.__func__)
        finally:
            stop.set()
    doc = json.loads((game / "run" / "o3_rehearsal.json").read_text(encoding="utf-8"))
    assert doc.get("finished") and "stopped" not in doc, doc.get("stopped")
    first, second = doc["stages"]["R-TWO"]
    assert first["outcome"]["end"] == "reached" and len(first["battles"]["rows"]) == 1, first["outcome"]
    assert first["fight"]["result"] == 2 and first["leave"]["presses"], (first["fight"], first["leave"])
    assert (second["outcome"]["end"], second["outcome"]["v"]) == ("void", "V4"), second["outcome"]
    assert second["battles"]["rows"] == [], second["battles"]
    assert second["fight"] is None and second["leave"] is None, (second["fight"], second["leave"])


# ---- THE MOVIE-SKIP A/B (studies/story-trace/PLAN.md "Movie skip (opt-in)"): R-FULL-SKIP, the stock rehearsal that
# carries the policy as its own overlay, and ``o3_prima_vista.py --skip-ab``, which reads it against R-FULL.

def test_o3_rehearse_movie_skip_stage_on_the_fake(game):
    """R-FULL-SKIP (PLAN.md "Movie skip (opt-in)"): R-FULL's warp and end with 61's FMV003 registered for skipping. It
    is picked by name only -- never by the default order or by ``--field 61`` -- and carries the policy as its OWN
    prediction overlay, as R-BATTLE-VOID carries its battle_override: stage_pred puts ``movies`` on a copy (checked
    strict: a bad overlay refuses before anything is driven) and leaves the predictions it was given, and the frozen
    v1, without one. On the fake, a stage with a policy plays "61": the policy's press opens the movie's skip dialog,
    answered YES, then the page and the end; its record holds the ``movies`` rows (skipped after one press, the dialog
    as published), the "movie_skip" press among the evidence, the skip dialog among the published choices and its
    ``choice`` row; the rehearsal report prints the skip. Break: drop the overlay in stage_pred (the movie plays out,
    and the record holds no ``movies``)."""
    P, R, SD = _o3_module(), _o3_rehearse_module(), _segment_modules()
    assert "R-FULL-SKIP" not in R.select(R.STAGES, env={}) and R.select(R.STAGES, 61, env={}) == ["R-START"]
    assert R.select(R.STAGES, env={"O3_STAGE": "R-FULL-SKIP"}) == ["R-FULL-SKIP"]
    stage, full = R.STAGES["R-FULL-SKIP"], R.STAGES["R-FULL"]
    warp = ("field", "entrance", "sc", "end")
    assert [stage[k] for k in warp] == [full[k] for k in warp] and "movies" not in full, stage
    fmv = stage["movies"]["cells"][0]                 # FMV003's span: R-FULL's arrival to page 72, not the movie's
    assert fmv["next_page_s"] == 90.0 and "page is 72" in fmv["why"] and "length_s" not in fmv, fmv
    base = _o3_rehearse_pred()
    sp = R.stage_pred(base, stage)
    pol = SD.movies_of(sp)
    assert [(c["donor"], c["sc"]) for c in pol["cells"]] == [(61, 1155)] and pol["policy"] == "skip", pol
    assert "movies" not in base and sp["movies"] == stage["movies"] and sp["movies"] is not stage["movies"]
    frozen = json.loads((REPO / "studies" / "story-trace" / "o3_predictions_v1.json").read_text(encoding="utf-8"))
    assert "movies" not in frozen
    with pytest.raises(ValueError, match="max_presses"):
        R.stage_pred(base, dict(stage, movies=dict(stage["movies"], max_presses=0)))
    _o3_launch_files(game)
    stages = {"R-SKIPTEST": {"field": 30820, "entrance": 0, "sc": 1155, "end": [_O3_END], "runs": 1, "run_s": 60,
                             "cost_s": 5, "movie": {"donor": 30820}, "movies": _o3_movies(),
                             "settles": "the movie-skip plumbing"}}
    fake = _o3_fake(game)

    def bit191(f):
        f.script_store(0, 0, 22, 191 >> 3, "Bit", 0, bit=191)
    phases = [(lambda f: f.field_id == 30820 and f.story_on,
               lambda f: (bit191(f), f.scene({"movie": 6000, "skip": dict(_O3_SKIP)}, _O3_PAGE, control=False))),
              (lambda f: f.field_id == 30820 and _o3_idle(f) and f.movies and f.movies[-1]["end"] is not None,
               lambda f: (_o2_move(f, _O3_END), bit191(f)))]
    stop = threading.Event()
    with session(game, fake) as g:
        boot(g)
        assert g.restore_baseline()[0], "a launch starts at the title"
        _o1_director(fake, stop, phases)
        _o3_grant_in(fake, stop)
        try:
            R.run(g, stages=stages, pred=_o3_rehearse_pred(), floor_for=lambda d, closed: _flat_bgi(),
                  prior_for=lambda d: _prior(), stock=lambda fid: None, recovery=_O3_RECOVERY,
                  env={"O3_STAGE": "R-SKIPTEST"}, census=_O3_CENSUS.__func__)
        finally:
            stop.set()
    run_dir = game / "run"
    doc = json.loads((run_dir / "o3_rehearsal.json").read_text(encoding="utf-8"))
    rec = doc["stages"]["R-SKIPTEST"][0]
    assert rec["outcome"]["end"] == "reached" and doc["stage_defs"]["R-SKIPTEST"]["movies"], rec["outcome"]
    mv = rec["movies"]
    assert len(mv) == 1 and (mv[0]["outcome"], len(mv[0]["presses"]), mv[0]["dialog"]["selected"]) == \
        ("skipped", 1, 1), mv
    assert [p["why"] for p in rec["evidence"]["press"]].count("movie_skip") == 1, rec["evidence"]["press"]
    assert any((c.get("options") or [""])[0].startswith("Do you want to skip") for c in rec["published_choices"])
    assert [(c["rule"], c["index"]) for c in rec["choices"]] == [("movie_skip", 0)], rec["choices"]
    assert fake.answered == [0] and fake.movies[0]["ended"] == "skipped", (fake.answered, fake.movies)
    report = P.rehearsal_report(run_dir)
    assert "movie-skip: 30820 visit 1 skipped" in report, report[:3000]


@pytest.fixture(scope="module")
def o3_stock():
    """The install's stock scripts of 61-64 (what the A/B joins its rows against), or a WARNED skip -- never a silent
    pass (THE WORKTREE SKIP TRAP)."""
    import warnings
    try:
        from ff9mapkit import storytrace
        src = storytrace.stock_script_source()
        assert all(src(f) is not None for f in (61, 62, 63, 64))
    except Exception as err:                                   # noqa: BLE001 -- no install here
        warnings.warn(f"the movie-skip A/B went UNVERIFIED against real bytes in this run: the game install is not "
                      f"readable here ({type(err).__name__}). Run on the machine with the install.", UserWarning)
        pytest.skip("game install unavailable")
    return src


def test_o3_skip_ab_on_synthetic_traces(o3_stock, tmp_path):
    """The movie-skip A/B (``o3_prima_vista.py --skip-ab``; PLAN.md "Movie skip (opt-in)") on synthetic stock runs --
    real store sites of 61-64, emitted as the engine emits them, each run its own battle noise. Two no-skip and two
    skip runs of the same events read EQUIVALENT (the noise aside), the time saved per run printed and each skip's
    evidence that it TOOK (90 s saved against the fastest no-skip run, 39.8 s due: half the 79.6 s its skip left); a
    skip run that lacks 61's ``Byte[8] := 125`` (a key DROPPED) differs on writes and history; one whose two 62
    ``Byte[4] := 0`` stores came in the other order (the same keys, a REORDERED history) on history alone; a skip run
    that played its movie out, and a no-skip run that skipped one, are differences -- never a pass. So is a skip run
    whose row says skipped but whose run took 229 s against 230 (the driver's word alone: the skip did not take, and
    its trace reads as R-FULL's on every axis), and one whose skipped row has no ``left_s`` (no next page registered).
    Through the files too (o3_dryrun.ab_launch): two launches written as o3_rehearse.py writes them (R-FULL; R-FULL-SKIP
    with its policy), paired by warp and end, read EQUIVALENT and the CLI exits 0; the no-skip launch against itself
    holds no policy stage: NOT EQUIVALENT, exit 1; an R-FULL-SKIP ending at 63 has no twin. G13 runs this test (the
    movie-skip review #5). Break: read each history as a set (the reordered one then reads EQUIVALENT); trust the
    row's "skipped" alone (the 229 s run then reads EQUIVALENT); or pair stages by policy inverted (nothing pairs)."""
    P, R = _o3_module(), _o3_rehearse_module()
    import o3_dryrun as D3
    pred, _sha = P.O3.load(P.PREDICTIONS)

    def ab(b1=None, *, skipped=True, a2_skip=False, t1=None, span=True, a_ts=(None, None)):
        a = [D3.ab_run(pred, D3.base_events(seed=0), "no-skip", 1, t=a_ts[0]),
             D3.ab_run(pred, D3.base_events(seed=1), "no-skip", 2, t=a_ts[1])]
        if a2_skip:                                  # a no-skip run carrying a skipped movie row
            a[1]["log"].insert(1, dict(D3.ab_run(pred, D3.base_events(seed=1), "skip", 2)["log"][1]))
        b = [D3.ab_run(pred, b1 if b1 is not None else D3.base_events(seed=2), "skip", 1, skipped=skipped, t=t1),
             D3.ab_run(pred, D3.base_events(seed=3), "skip", 2)]
        if not span:                                 # a skipped row whose cell registered no next page
            b[0]["log"][1].update(next_page_s=None, left_s=None)
        ok, lines = P.skip_ab_runs(a, b, pred, stock=o3_stock)
        at = next((i for i, x in enumerate(lines) if x.startswith("DIFFERENCES")), None)
        return ok, lines, [] if at is None else [x.strip() for x in lines[at + 1:-1]]
    ok, lines, diffs = ab()
    assert ok and lines[-1].startswith("VERDICT: EQUIVALENT") and diffs == [], lines
    assert any(ln.startswith("time: no-skip 230 s, 230 s (mean 230.0 s)") and "(saved 90.0 s)" in ln for ln in lines)
    assert [ln for ln in lines if ln.startswith("took: ")] == [
        f"took: skip R-FULL-SKIP#{n} saved 90.0 s against the fastest no-skip run (230 s), at least 39.8 s due (0.5 of "
        f"the 79.6 s its skip left)" for n in (1, 2)], lines
    ok, lines, diffs = ab(t1=229.0)                  # its row says skipped; the run took as long as the movie
    assert not ok and lines[-1] == "VERDICT: NOT EQUIVALENT", lines
    assert diffs == ["skip R-FULL-SKIP#1 saved 1.0 s against the fastest no-skip run (230 s), at least 39.8 s due (0.5 "
                     "of the 79.6 s its skip left) -- its row says skipped, but it took as long as a movie played out"], \
        diffs
    ok, lines, diffs = ab(t1=190.0, a_ts=(200.0, 260.0))   # 40 s under the no-skip mean, 10 under the fastest
    assert not ok and diffs == ["skip R-FULL-SKIP#1 saved 10.0 s against the fastest no-skip run (200 s), at least "
                                "39.8 s due (0.5 of the 79.6 s its skip left) -- its row says skipped, but it took as "
                                "long as a movie played out"], diffs
    ok, lines, diffs = ab(span=False)
    assert not ok and len(diffs) == 1 and diffs[0].startswith("skip R-FULL-SKIP#1 has a skipped movie row with no "
                                                              "left_s"), diffs
    ok, lines, diffs = ab(D3.drop(D3.base_events(seed=2), D3.B8_61))
    assert not ok and lines[-1] == "VERDICT: NOT EQUIVALENT", lines
    assert [d.split(":")[0] for d in diffs] == ["skip R-FULL-SKIP#1 writes", "skip R-FULL-SKIP#1 history"], diffs
    assert "61 Byte[8] := 125" in diffs[0] and diffs[1].startswith("skip R-FULL-SKIP#1 history: Global.Byte[8]"), diffs
    ok, lines, diffs = ab(D3._swap(D3.base_events(seed=2), D3.S62[12], D3.S62[13]))
    assert not ok and len(diffs) == 1 and diffs[0].startswith("skip R-FULL-SKIP#1 history: Global.Byte[4]"), diffs
    ok, lines, diffs = ab(skipped=False)
    assert not ok and len(diffs) == 1 and "skipped no movie (movie-skip missed" in diffs[0], diffs
    ok, lines, diffs = ab(a2_skip=True)
    assert not ok and diffs == ["no-skip R-FULL#2 skipped a movie: the no-skip side must play every movie out"], diffs
    a_dir = D3.ab_launch(tmp_path / "a", "R-FULL", R.STAGES["R-FULL"],          # as o3_rehearse.py writes a launch
                         [D3.ab_run(pred, D3.base_events(seed=n), "no-skip", n) for n in (1, 2)])
    b_dir = D3.ab_launch(tmp_path / "b", "R-FULL-SKIP", R.STAGES["R-FULL-SKIP"],
                         [D3.ab_run(pred, D3.base_events(seed=n + 2), "skip", n) for n in (1, 2)])
    ok, text = P.skip_ab(a_dir, b_dir, pred=pred, stock=o3_stock)
    assert ok and text.splitlines()[-1].startswith("VERDICT: EQUIVALENT"), text
    assert ("skip stage R-FULL-SKIP: warp 61 0 1155 -> [64]; policy skip, cells 61@1155 after 10.0 s; paired with "
            "R-FULL") in text, text
    ok, text = P.skip_ab(a_dir, a_dir, pred=pred, stock=o3_stock)
    assert not ok and "holds no stage with a movie-skip policy" in text, text
    lone = D3.ab_launch(tmp_path / "c", "R-FULL-SKIP", dict(R.STAGES["R-FULL-SKIP"], end=[63]),
                        [D3.ab_run(pred, D3.base_events(seed=3), "skip", 1)])
    ok, text = P.skip_ab(a_dir, lone, pred=pred, stock=o3_stock)       # no no-skip stage of its warp AND end
    assert not ok and "skip stage R-FULL-SKIP has no no-skip stage of the same warp and end" in text, text
    assert P.main(["--skip-ab", str(a_dir), str(b_dir)]) == 0
    assert P.main(["--skip-ab", str(a_dir), str(a_dir)]) == 1


# ---- O4, PART A (research/o4_design.md section 9): the regression gate extended to O3 (G15-G18) and its source pins
# (G21), then the shared per-side ends (S6) and O3's language clause read from its record (A2). Every test here is
# collected by G7's selection ("segment"), so the gate re-runs it.

def _regress_module():
    sys.path.insert(0, str(REPO / "studies" / "story-trace"))
    import segment_regress as R
    return R


def test_segment_regress_source_pins_catch_an_edit(tmp_path):
    """G21's checker (research/o4_design.md 1.4, 9 A0; rev. 2, the claim critique #7), pure, over a temporary COPY of
    the two pinned files. The pins taken from the copy read clean; a comment and whitespace edit inside a pinned test
    still reads clean (the AST is pinned, never the text); an edit to that test's BODY fails naming it -- and only it;
    a re-baseline row with its reason (old the pin in force, new the edited sha) reads clean again; the re-baseline is
    refused for an empty reason, a name not pinned, a stale old and a source that has not changed; a hand-edited row
    (its reason emptied) fails replayed; an edit to a pinned fake function fails naming it; a renamed pinned test fails
    as gone. G21 itself, through a pins file and the copy, and the --rebaseline-source path (rebaseline_source) on a
    temporary baseline: a refusal writes nothing, a re-baseline appends its one row. Break: pin the function's source
    TEXT instead of its AST (the comment edit then fails), or compare names only (the body edit then passes)."""
    R = _regress_module()
    test_copy, fake_copy = tmp_path / "test_harness.py", tmp_path / "fakegame.py"
    test_copy.write_bytes((REPO / R.TEST_REL).read_bytes())
    fake_copy.write_bytes((REPO / R.FAKE_REL).read_bytes())
    files = {R.TEST_REL: test_copy, R.FAKE_REL: fake_copy}
    door = R.pin_of_test("test_o2_drive_voids_a_walk_into_another_registered_door_as_the_drivers[cross]")
    pick = R.pin_of_test("test_o1_pick_for_reads_the_frozen_rules_by_option_text")
    control = f"{R.FAKE_REL}::_control"
    assert door == f"{R.TEST_REL}::test_o2_drive_voids_a_walk_into_another_registered_door_as_the_drivers", door
    names = [door, pick, f"{R.FAKE_REL}::FakeGame._step_scene", control]
    pins = R.source_shas(names, files=files)
    assert all(isinstance(pins[n], str) and len(pins[n]) == 64 for n in names), pins
    assert R.g21_bad(pins, R.source_shas(names, files=files), []) == []

    def edit(path, old, new):
        text = path.read_text(encoding="utf-8")
        assert text.count(old) == 1, f"premise: {old!r} occurs once in the copy"
        path.write_text(text.replace(old, new), encoding="utf-8")
    head = "def test_o1_pick_for_reads_the_frozen_rules_by_option_text():\n"       # the def line itself, newline and all
    edit(test_copy, head, "def test_o1_pick_for_reads_the_frozen_rules_by_option_text( ) :   # an aside\n"
                          "    # a comment line, and a blank one: no code\n\n")
    now = R.source_shas(names, files=files)
    assert now == pins and R.g21_bad(pins, now, []) == [], "a comment or whitespace edit is no code edit"
    edit(test_copy, "    assert O.pick_for(q, 30820, pred)[0] == 1\n", "    assert O.pick_for(q, 30820, pred)[0] in (1, 2)\n")
    now = R.source_shas(names, files=files)
    bad = R.g21_bad(pins, now, [])
    assert len(bad) == 1 and bad[0].startswith(f"{pick}: changed (") and "--rebaseline-source" in bad[0], bad
    row = R.pin_row(pins, [], pick, pins[pick], now[pick], "  the assertion follows a widened rule ", "abc123")
    assert row == {"name": pick, "old": pins[pick], "new": now[pick], "reason": "the assertion follows a widened rule",
                   "head": "abc123"}, row
    assert R.g21_bad(pins, now, [row]) == [] and R.pins_in_force(pins, [row])[pick] == now[pick]
    for kw, match in (({"reason": ""}, "needs its reason"), ({"reason": "   "}, "needs its reason"),
                      ({"name": f"{R.TEST_REL}::test_nothing_by_this_name"}, "is not pinned"),
                      ({"old": pins[pick]}, "is not the pin in force"), ({"new": now[pick]}, "nothing changed")):
        args = {"name": pick, "old": row["new"], "new": now[pick] + "0", "reason": "why", **kw}
        with pytest.raises(ValueError, match=match):
            R.pin_row(pins, [row], args["name"], args["old"], args["new"], args["reason"], "abc123")
    bad = R.g21_bad(pins, now, [dict(row, reason="")])
    assert bad and bad[0].startswith("row 0: ") and "needs its reason" in bad[0], bad
    edit(fake_copy, "    return DIRECTIONS.get(str(name).lower(), name)\n",
         "    return DIRECTIONS.get(str(name).upper(), name)\n")
    now = R.source_shas(names, files=files)
    bad = R.g21_bad(pins, now, [row])
    assert len(bad) == 1 and bad[0].startswith(f"{control}: changed ("), bad
    edit(test_copy, "def test_o2_drive_voids_a_walk_into_another_registered_door_as_the_drivers(game, kind):\n",
         "def test_o2_drive_voids_a_walk_into_another_door(game, kind):\n")
    now = R.source_shas(names, files=files)
    assert now[door] is None, now
    bad = R.g21_bad(pins, now, [row])
    assert f"{door}: gone (renamed or deleted) -- a pinned source must stay" in bad and len(bad) == 2, bad
    # G21 itself and --rebaseline-source, through files: a temporary baseline (the pins) and pins file
    base_path, pins_path = tmp_path / "o3_regress_baseline.json", tmp_path / "source_pins.json"
    base_path.write_text(json.dumps({"sources": pins, "sources_python": R._py()}), encoding="utf-8")
    pins_path.write_text("[]\n", encoding="utf-8")
    ok, what, detail = R.g21(json.loads(base_path.read_text(encoding="utf-8")), pins_path, files=files)
    assert ok is False and what.startswith("G21: ") and f"{pick}: changed" in detail and f"{door}: gone" in detail, \
        detail
    assert R.rebaseline_source(pick, "", baseline=base_path, pins=pins_path, files=files) == 1
    assert R.rebaseline_source(door, "renamed", baseline=base_path, pins=pins_path, files=files) == 1
    assert pins_path.read_text(encoding="utf-8") == "[]\n", "a refusal writes nothing"
    assert R.rebaseline_source(pick, "the assertion follows a widened rule", baseline=base_path, pins=pins_path,
                               files=files) == 0
    rows = json.loads(pins_path.read_text(encoding="utf-8"))
    assert [(r["name"], r["old"], r["new"]) for r in rows] == [(pick, pins[pick], now[pick])], rows
    assert R.rebaseline_source(pick, "again", baseline=base_path, pins=pins_path, files=files) == 1   # unchanged
    ok, _what, detail = R.g21(json.loads(base_path.read_text(encoding="utf-8")), pins_path, files=files)
    assert ok is False and f"{pick}" not in detail and f"{door}: gone" in detail and f"{control}: changed" in detail, \
        detail


#: S6's places on the fake (research/o4_design.md 9 A1): 30820 is "150" (the start), 30830 "153" (the end: real, never
#: registered, never warped to); the F side's members 31243 ("150") and 31245 ("153"). 31243 is appended to the
#: fixture's DictionaryPatch (O1's pinning test's way); 31245, like the end, is only ever moved to.
_S6_END = 30830
_S6_MEMBERS = {"31243": 30820, "31245": _S6_END}
_S6_START = {"S": 30820, "F": 31243}


def _s6_rows(*specs):
    """Proto-1 trace rows, one per spec, 10 frames apart: ``("e", fld, why)``, ``("r", fld, byte, new)`` or ``("w",
    fld, sid, ip)`` -- a Byte[8] store (0 -> 25) at that site."""
    from ff9mapkit import storytrace as T
    out = []
    for n, (k, fld, *rest) in enumerate(specs):
        row = {"k": k, "f": 1000 + 10 * n, "p": 0, "m": 1, "fld": fld, "don": fld, "sc": 1155}
        if k == "e":
            row["why"] = rest[0]
        elif k == "r":
            row.update(byte=rest[0], old=0, new=rest[1], why="frame")
        else:
            row.update(src="eb", sid=rest[0], uid=rest[0], lvl=0, ip=rest[1], tag=0, add=0, byte=8, w="Byte", bit=-1,
                       old=0, new=25, same=0)
        out.append(row)
    return T.parse_text("".join(json.dumps(x) + "\n" for x in out))


def test_segment_side_ends_split_the_cut_and_the_drive():
    """S6, pure (research/o4_design.md 1.2, 9 A1; the critique's major #1, decision 4). ``side_ends_of`` reads O4's
    shape -- S [153], F [member(153)] -- and refuses each malformed one: not a dict of exactly S and F (a list; S alone;
    a third key), an empty side, a bool for an id, an id twice, S not the end fields, real 153 on F though a member
    forks it, a member whose donor is no end field, F's places short of the end fields. ``side_ends`` keeps each side's
    END FIELDS, ``end_places`` the frozen END PLACES: [153] on both sides. ``Segment.cut`` on F rows cuts at
    member(153)'s first row -- by place: the raw end fields ([31245]) never cut there -- and, as frozen place 153, at a
    real-153 row too (O4-LANDING (d) reads which; the drive's rule 2 VOIDs that run V19 first). ``forbidden_hits`` with
    F's ends [31245] hits a real-150 row and not member(153)'s; with one list for both sides ([153]) member(153)'s row
    is off the route. O1's, O2's and O3's frozen predictions (no ``side_ends``) read their one list on both sides, and
    their cut is today's. Break: cut at the raw end fields (member(153)'s first row is then never cut)."""
    ST, SD = _segment_trace(), _segment_modules()
    pred = {"end_field": 153, "end_fields": [153], "members": {"31240": 64, "31243": 150, "31245": 153},
            "side_ends": {"S": [153], "F": [31245]}, "start": {"S": 64, "F": 31240}, "route": [64, 150],
            "cut_start": True, "forbidden": [{"off_route": True, "cause": "walk", "why": "a write off the route"}]}
    assert ST.side_ends_of(pred) == {"S": [153], "F": [31245]}
    assert (ST.side_ends(pred, "S"), ST.side_ends(pred, "F")) == ([153], [31245])
    assert (ST.end_places(pred, "S"), ST.end_places(pred, "F")) == ([153], [153])
    neither = "is neither an end field no member forks nor a member whose donor is an end field"
    for bad, match in (([153], "a dict of exactly"), ({"S": [153]}, "a dict of exactly"),
                       ({"S": [153], "F": [31245], "B": [1]}, "a dict of exactly"),
                       ({"S": [], "F": [31245]}, "a non-empty list of field ids"),
                       ({"S": [153], "F": [True]}, "a non-empty list of field ids"),
                       ({"S": [153], "F": [31245, 31245]}, "lists an id twice"),
                       ({"S": [150], "F": [31245]}, "is not exactly the end fields"),
                       ({"S": [153], "F": [153]}, neither), ({"S": [153], "F": [31243]}, neither)):
        with pytest.raises(ValueError, match=match):
            ST.side_ends_of({**pred, "side_ends": bad})
    with pytest.raises(ValueError, match="F's places .* are not exactly the end fields"):
        ST.side_ends_of({**pred, "end_fields": [153, 154], "side_ends": {"S": [153, 154], "F": [31245]}})
    # the cut: the warp's residue in 70, member(64)'s start, member(150), then member(153)'s first row
    rows = _s6_rows(("e", 70, "arm"), ("r", 70, 0, 131), ("w", 31240, 0, 22), ("w", 31243, 0, 26), ("w", 31245, 0, 22),
                    ("w", 31245, 3, 40), ("e", 31245, "off"))
    kept, start, end, pre = ST.Segment().cut(rows, pred, "F")
    assert (start, end) == (3, 5) and [x.line for x in pre] == [2], (start, end, pre)
    assert [x.fld for x in kept if x.k == "w"] == [31240, 31243], kept
    assert ST.cut_at_end(rows, ST.side_ends(pred, "F"), ST.members_of(pred))[1] is None    # the raw ids never cut
    real = _s6_rows(("e", 70, "arm"), ("w", 31240, 0, 22), ("w", 31243, 0, 26), ("w", 153, 0, 22), ("w", 31245, 0, 22))
    assert ST.Segment().cut(real, pred, "F")[2] == 4                 # real 153 is place 153 too: LANDING (d) reads it
    # the forbidden scan: F's end fields [31245] -- a real-150 row is off the route, member(153)'s is the end
    scan = _s6_rows(("e", 70, "arm"), ("w", 31240, 0, 22), ("w", 150, 0, 26), ("w", 31245, 0, 22))
    members = ST.members_of(pred)
    hits = SD.forbidden_hits(scan, pred, members, 64, end_fields=ST.side_ends(pred, "F"))
    assert [(h["fld"], h["cause"]) for h in hits] == [(150, "walk")], hits
    hits = SD.forbidden_hits(scan, pred, members, 64, end_fields=[153])             # one list for both sides
    assert [h["fld"] for h in hits] == [150, 31245], hits
    # O1-O3: no side_ends -- their one list on both sides, and today's cut
    here = REPO / "studies" / "story-trace"
    for name in ("o1_predictions_v4.json", "o2_predictions_v1.json", "o3_predictions_v1.json"):
        p = json.loads((here / name).read_text(encoding="utf-8"))
        ends = list(p.get("end_fields") or [p["end_field"]])
        assert ST.side_ends_of(p) is None, name
        for side in ("S", "F"):
            assert ST.side_ends(p, side) == ends and ST.end_places(p, side) == sorted(set(ends)), (name, side)
        m = ST.members_of(p)
        trace = _s6_rows(("e", 70, "arm"), ("w", next(iter(m)), 0, 22), ("w", ends[0], 0, 22), ("w", ends[0], 0, 30))
        assert ST.Segment().cut(trace, {**p, "cut_start": False}, "F")[2] == ST.cut_at_end(trace, ends, m)[1] == 3, name


def _s6_pred(**over):
    """S6's driver keys on the fake's places: no table, no battle; route and visits [30820]; the end 30830 ("153") on
    S, member(153) 31245 on F; ``end_row_s`` 3 (rule 1 waits for the end place's first row)."""
    pred = {"version": 1, "start": dict(_S6_START), "entrance": 325, "scenario": 1155, "end_field": _S6_END,
            "end_fields": [_S6_END], "side_ends": {"S": [_S6_END], "F": [31245]}, "route": [30820],
            "visits": [30820], "members": dict(_S6_MEMBERS), "names": {"31243": "O4_S6_A", "31245": "O4_S6_B"},
            "budget": {"run_s": 60, "run_min_s": 1, "session_s": 600, "settle_s": 0.3, "no_progress_s": 60,
                       "end_row_s": 3.0},
            "beats": [], "table": [], "naming": [], "forbidden": [], "end_state": {}, "regions": {}, "hotspots": {},
            "choices": []}
    pred.update(over)
    return pred


def _s6_run(game, side, lands, *, pred, end_fields=None):
    """One run on the fake: New Game, the RAW warp into the side's start (no control: 64 and 150 give none), a page,
    then the scripted Field() into ``lands``, whose Main_Init writes its first store 240 frames after the arrival.
    ``(the outcome or the RouteVoid, the log, the trace's w rows in ``lands``)``."""
    patch = game / "FF9CustomMap" / "DictionaryPatch.txt"
    if "31243" not in patch.read_text(encoding="utf-8"):
        patch.write_text(patch.read_text(encoding="utf-8") + "FieldScene 31243 11 O4_S6_A O4_S6_A 2\n", encoding="utf-8")
    fake = _o3_fake(game)
    start = _S6_START[side]
    arrived: dict = {}

    def to_end(f):
        arrived["frame"] = f.frame
        _o2_move(f, lands)
    phases = [(lambda f: f.field_id == start, lambda f: f.scene("Narrator\n“The fight is over.”", control=False)),
              (lambda f: f.field_id == start and _o3_idle(f), to_end),
              (lambda f: f.field_id == lands and f.frame >= arrived["frame"] + 240,
               lambda f: f.script_store(0, 0, 22, 191 >> 3, "Bit", 0, bit=191))]
    SD = _segment_modules()
    stop = threading.Event()
    with session(game, fake) as g:
        boot(g)
        g._check_field_id(start, "warp", True)
        g.send(f"warp {start} 325 1155")
        g.wait_for(lambda s: s.field_id == start and s.ui_state == "FieldHUD", timeout=10.0, what=f"field {start}")
        g.storytrace(True)
        _o1_director(fake, stop, phases)
        log: list = []
        try:
            out = SD.drive(g, pred, side, log, deadline=time.time() + 30.0, floor_for=lambda d, c: _flat_bgi(),
                           prior_for=lambda d: _prior(), end_fields=end_fields, forbid_live=False)
        except SD.RouteVoid as err:
            out = err
        finally:
            stop.set()
        rows = [r for r in g.story_rows() if r.k == "w" and r.fld == lands]
    return out, log, rows


def test_segment_drive_ends_per_side_on_the_fake(game):
    """S6 on the drive (research/o4_design.md 1.2, 9 A1; the critique's major #1), opt-in (``side_ends``). F reaches
    member("153") 31245 -- rule 1 on the side's own END FIELDS -- and the end row names it and waits for the run's first
    trace row in the end PLACE ("153"), which member(153)'s Main_Init writes 240 frames after the arrival: ``end_row``
    seen, at that row's frame; the run's one visit is member("150"). S reaches real "153" the same way. On F a landing
    in REAL "153" -- a Field() the chain did not retarget -- is V19 by the GAME, a finding, its cell the real field and
    the published SC, with no end row; the same F landing WITHOUT ``side_ends`` (the end list given as [member(153)],
    the driver as before) is V11 by the game, today's. Break: compare raw ids in ``end_row()`` (member(153)'s arrival
    is then never cut: ``end_row`` unseen)."""
    SD = _segment_modules()
    logs = {}
    for side, lands in (("F", 31245), ("S", _S6_END)):
        out, log, rows = _s6_run(game, side, lands, pred=_s6_pred())
        assert not isinstance(out, Exception) and out["end"] == "reached" and out["why"] == f"field {lands}", (side, out)
        end = [r for r in log if r["k"] == "end"][-1]
        assert end["field"] == lands and len(rows) == 1, (side, end, rows)
        assert end["end_row"]["seen"] is True and end["end_row"]["f"] == rows[0].f, (side, end)
        logs[side] = log
    assert [(r["field"], r["donor"]) for r in logs["F"] if r["k"] == "visit"] == [(31243, 30820)], logs["F"]
    err, log, _rows = _s6_run(game, "F", _S6_END, pred=_s6_pred())
    assert isinstance(err, SD.RouteVoid), err
    assert (err.v, err.by, err.cell) == ("V19", "game", [_S6_END, 1155]), (err.v, err.by, err.cell)
    assert (f"the fork run entered REAL {_S6_END}, where member({_S6_END}) 31245 was due: a Field() the chain did not "
            f"retarget") in str(err), err
    assert not [r for r in log if r["k"] == "end"], log
    pred = _s6_pred()
    del pred["side_ends"]
    err, _log, _rows = _s6_run(game, "F", _S6_END, pred=pred, end_fields=[31245])
    assert isinstance(err, SD.RouteVoid), err
    assert (err.v, err.by) == ("V11", "game") and f"left the route: entered {_S6_END}" in str(err), err


def test_segment_o3_scope_lang_reads_the_recorded_p_text():
    """A2 (research/o4_design.md 9, rev. 2; the claim critique #13): O3's report DERIVES its language clause from the
    session's recorded P-TEXT rows -- never prints "block 2's uk copy is the US text" as a constant: O4's deploy
    rewrites block 2 per language, and an O3 session after it records no defect. Through ``O3.report_extra`` on
    synthetic O3 sessions: block 2's uk KNOWN-KIT-DEFECT line recorded (story-o3's form, and o3_dryrun's TEXT_DEFECT --
    every dry-run session records it) -> rev. 1's SCOPE_LANG, byte for byte; no P-TEXT row recorded, or no preflight at
    all -> SCOPE_LANG; a P-TEXT row with no defect -> "block 2's copies are each their own language's stock text";
    another language's defect -> a clause naming it (neither of the two would be true). Break: print the defect clause
    unconditionally (rev. 1: the clean session then reads uk-ships-us)."""
    P = _o3_module()
    import o3_dryrun as D3
    pred = json.loads(P.PREDICTIONS.read_text(encoding="utf-8"))
    ptext = P.O3.title("P-TEXT")
    uk = ("FF9CustomMap: KNOWN-KIT-DEFECT 1, FAIL 0, 6 byte-equal of 7 languages | KNOWN-KIT-DEFECT uk: ships stock us "
          "(3a6f3246c2; stock uk 7ac9f17435): the build predates the per-language text pick (aa627d52): regenerate it, "
          "or repair its sidecars with tools/refresh_verbatim_text.py")
    clean = "FF9CustomMap: KNOWN-KIT-DEFECT 0, FAIL 0, 7 byte-equal of 7 languages"
    fr = ("FF9CustomMap: KNOWN-KIT-DEFECT 1, FAIL 0, 6 byte-equal of 7 languages | KNOWN-KIT-DEFECT fr: ships stock gr "
          "(0123456789; stock fr 9876543210): another language's stock text: the build's per-language text pick")

    def lang(preflight) -> str:
        session = {"label": "s0"} if preflight is None else {"label": "s0", "preflight": preflight}
        lines = P.O3.report_extra(pathlib.Path("."), session, pred, [], [])
        got = [ln for ln in lines if ln.startswith("  language -- ")]
        assert len(got) == 1, lines
        return got[0][len("  language -- "):]
    assert P.SCOPE_LANG == ("a US session (P-LANG): the members' jp/fr/gr/it/es .eb are US bytecode "
                            "(accept_us_build), and block 2's uk copy is the US text (the KNOWN-KIT-DEFECT line below)")
    assert lang([[True, ptext, uk]]) == P.SCOPE_LANG
    assert lang([[True, ptext, D3.TEXT_DEFECT]]) == P.SCOPE_LANG
    assert lang([[True, "P-CAP: the engine advertises the story trace at proto 1", "{'proto': 1}"]]) == P.SCOPE_LANG
    assert lang(None) == P.SCOPE_LANG
    assert lang([[True, ptext, clean]]) == ("a US session (P-LANG): the members' jp/fr/gr/it/es .eb are US bytecode "
                                            "(accept_us_build); block 2's copies are each their own language's stock "
                                            "text (P-TEXT)")
    assert lang([[True, ptext, fr]]) == ("a US session (P-LANG): the members' jp/fr/gr/it/es .eb are US bytecode "
                                         "(accept_us_build), and block 2's fr copy is another language's stock text "
                                         "(the KNOWN-KIT-DEFECT line below)")


# ---- O4's machine beats on the fake (research/o4_design.md 3, 9 B1): H10's KEYON pair and H11's Chanbara visit,
# stepped BY HAND -- no loop thread, no driver -- so a key goes down on exactly the frame (and the field tick) a test
# names: ``fake._schedule(name, frames)`` before a frame runs puts the key down ON that frame, as the agent's press
# does a frame after it accepts one. At 30 fps "quantized" every frame runs exactly one field tick (FIELD_TPS 30), so
# a prompt's tick S + j runs on its arm frame + j; the 31 / 60 fps tests read the beat's own tick count instead.

_CB_BUTTON = {"LEFT": "left", "RIGHT": "right", "UP": "up", "DOWN": "down", "TRIANGLE": "menu", "CROSS": "confirm",
              "CIRCLE": "cancel", "SQUARE": "special"}


def _cb_fake(game, beat, *, fps=30.0, ticks="quantized", trace=True, publish=None):
    """A FakeGame stepped by hand: armed, on 30820 (the fight's "64") at FieldHUD with control off, its scene the one
    machine ``beat``. ``publish`` (a list) records every publish -- state_every 1 -- as ``{"frame", "texts", "raw",
    "choice", "group", "x", "blank", "ui", "field"}``; without it nothing is published after the first frame."""
    fake = FakeGame(game, render_fps=fps, ticks=ticks)
    fake.dir.mkdir(parents=True, exist_ok=True)
    (fake.dir / "arm").write_text("", encoding="utf-8")
    fake.armed = True
    fake.field_id, fake.ui_state, fake.control = 30820, "FieldHUD", False
    if trace:
        fake._story_start()
    if publish is None:
        fake.state_every = 1 << 30
    else:
        fake.state_every = 1
        real = fake._publish

        def rec(force=False):
            real(force)
            if fake.publish_frame != fake.frame:
                return
            blank = next((b["x"] for b in fake.blockers.get(fake.field_id, ())
                          if isinstance(b, dict) and b.get("sid") == 20), None)
            publish.append({"frame": fake.frame, "texts": list(fake.texts), "raw": list(fake.raw_texts),
                            "choice": json.loads(json.dumps(fake.choice)), "group": (fake.menu or {}).get("group"),
                            "x": fake.player[0], "blank": blank, "ui": fake.ui_state, "field": fake.field_id})
        fake._publish = rec
    fake.scene(beat, control=False)
    return fake


def _cb_default_press(row):
    return _CB_BUTTON[row["dbtn"]], 5, 1


def _cb_play(fake, *, press=_cb_default_press, answers=(1,), until=None, limit=80000, every=7):
    """Play a Chanbara beat by hand: each armed prompt pressed by ``press(row) -> [(name, j, frames), ...] | (name, j,
    frames) | None`` -- the key down on the frame that runs tick arm + j (30 fps quantized: one tick a frame); a listed
    page or KEYON pair Confirmed every ``every`` frames; a COMPLETE choice steered to ``answers[k]`` (k: the choices
    answered so far) and Confirmed. Stops on ``until(fake)``, the beat's end or ``limit`` frames."""
    plan, seen, asked = {}, 0, 0
    for _ in range(limit):
        if until is not None and until(fake):
            return
        m = fake._machine
        if m is None:
            return
        rows = fake.chanbara_log
        while seen < len(rows):
            got = press(rows[seen]) if press is not None else None
            for name, j, frames in ([got] if isinstance(got, tuple) else got or ()):
                plan.setdefault(rows[seen]["arm_frame"] + j, []).append((name, frames))
            seen += 1
        keys = plan.pop(fake.frame + 1, None)
        if keys:
            for name, frames in keys:
                fake._schedule(name, frames)
        elif (fake.frame + 1) % every == 0:
            open_ = [w for w in m.windows if not w.closing]
            if any(w.kind in ("page", "keyon") for w in open_):
                fake._schedule("confirm", 1)
            ch = next((w for w in open_ if w.kind == "choice" and w.complete), None)
            if ch is not None:
                want = answers[min(asked, len(answers) - 1)]
                if ch.cursor != want:
                    fake._schedule("down" if ch.cursor < want else "up", 1)
                else:
                    fake._schedule("confirm", 1)
                    asked += 1
        fake._frame_once()
    raise AssertionError(f"the beat ran {limit} frames without ending")


def _cb_trace(fake):
    """The fake's story.jsonl rows (``w`` only), as ``(sid, tag, ip, byte, old, new, frame)``."""
    rows = [json.loads(ln) for ln in (fake.dir / "story.jsonl").read_text(encoding="utf-8").splitlines() if ln]
    return [(r["sid"], r["tag"], r["ip"], r["byte"], r["old"], r["new"], r["f"]) for r in rows if r["k"] == "w"]


def _cb_opened(fake, kind=None):
    """The texts of the windows the beat opened, in order (``kind`` filters)."""
    return [e["text"] for e in fake.machine_log if e["event"] == "open" and kind in (None, e["kind"])]


def _cb_event(fake, event, text, nth=0):
    """The ``nth`` machine_log row of ``event`` for the window whose text holds ``text``."""
    return [e for e in fake.machine_log if e["event"] == event and text in e["text"]][nth]


def _cb_until(fake, pred, limit=40000):
    """Step ``fake`` by hand until ``pred(fake)`` -- an AssertionError after ``limit`` frames: a mutant must fail a
    test, never hang it."""
    for _ in range(limit):
        if pred(fake):
            return
        fake._frame_once()
    raise AssertionError(f"not reached within {limit} frames")


def test_fake_keyon_pair_takes_only_an_edge_after_its_gate(game):
    """H10 (research/o4_design.md 3): THE KEYON PAIR. Window a, then b ``lag_ticks`` later; a Confirm does not page
    them ([TIME=-1]); from ``gate_ticks`` after b opened each tick reads ``keyon & (Confirm | Special)``, and the first
    such EDGE closes both, each gone a tween later. A press before the gate is consumed by its tick and lost (both stay
    up); a key HELD across the gate gives no edge after it (both stay up); the first press after the gate closes both,
    Confirm or Special. Break: read the level instead of the edge (the held key then closes them at the gate)."""
    texts = ["Blank\n“En garde!”", "Zidane\n“Expect no quarter from me!”"]
    for name in ("confirm", "special"):
        fake = _cb_fake(game, {"keyon_pair": {"texts": texts, "lag_ticks": 15, "gate_ticks": 40}}, trace=False)
        m = fake._machine

        def at(tick):
            _cb_until(fake, lambda f: m.tick >= tick or f._machine is not m)
            assert fake._machine is m and m.tick == tick, f"the beat ended at tick {m.tick}, before tick {tick}"
        at(5)
        fake._schedule(name, 1)                        # down on tick 6: before the gate (tick 16 + 40 = 56)
        at(20)
        assert [w.text for w in m.windows] == texts and not any(w.closing for w in m.windows), m.windows
        assert [e["tick"] for e in fake.machine_log if e["event"] == "open"] == [1, 16], fake.machine_log
        at(50)
        fake._schedule(name, 15)                       # held on ticks 51-65: across the gate
        at(70)
        assert [w.text for w in m.windows] == texts and not any(w.closing for w in m.windows), (name, m.windows)
        assert fake.texts == texts and fake._machine is m
        fake._schedule(name, 1)                        # down on tick 71: the first edge after the gate
        at(71)
        assert [(e["event"], e["tick"]) for e in fake.machine_log if e["event"] != "open"] == [("close", 71)] * 2
        _cb_until(fake, lambda f: f._machine is None, limit=200)
        assert fake.texts == [] and not fake._beats and fake.control is False
        closed = {e["text"]: e["rt"] for e in fake.machine_log if e["event"] == "close"}
        gone = [e for e in fake.machine_log if e["event"] == "gone"]
        assert len(gone) == 2 and all(0.09 <= e["rt"] - closed[e["text"]] < 0.2 for e in gone), fake.machine_log


def test_fake_chanbara_arms_and_publishes_in_one_tick(game):
    """H11's pass machine and its input model (research/o4_design.md 3). The arm and its window in ONE tick (the window
    opens on the prompt's arm tick); the first poll is S+1 -- e3 runs before e20 in a tick, so a key whose edge lands
    on the arm tick S is consumed and lost (the prompt times out); a press landing on tick S+j credits 50 - j: j 1
    credits 49, j 5 45, j 50 none (a hit, not a timeout: e3 hits before TimeLeft's last decrement). And a one-frame tap
    lands on exactly ONE tick at 31 and 60 fps ("quantized"): on a frame that runs no tick it is collected into the
    next tick's input (CollectDelayedInputs), on a frame that runs three (a hitch) only the first sees its edge. Break:
    e3 after e20 (the tap on S then hits, and is credited)."""
    plan = {2: 1, 3: 5, 4: 50}

    def press(row):
        return None if row["n"] == 1 else (_CB_BUTTON[row["dbtn"]], plan.get(row["n"], 5), 1)
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "seed": 0}})
    m = fake._machine
    _cb_play(fake, press=press, until=lambda f: m.t0_tick is not None and m.tick == m.t0_tick + 11)
    fake._schedule("confirm", 1)                       # down on tick T0 + 12: the first arm's tick S (seed 0: CROSS)
    _cb_play(fake, press=press)
    rows = fake.chanbara_log
    assert rows[0]["dbtn"] == "CROSS" and rows[0]["arm_tick"] == m.t0_tick + 12, rows[0]
    opens = [e for e in fake.machine_log if e["event"] == "open" and e["kind"] == "prompt"]
    assert len(rows) == 49 and [e["tick"] for e in opens] == [r["arm_tick"] for r in rows], (rows[:3], opens[:3])
    assert [e["frame"] for e in opens] == [r["arm_frame"] for r in rows]
    assert rows[0]["result"] == "timeout" and rows[0]["j"] is None, rows[0]
    assert rows[1]["arm_tick"] == rows[0]["arm_tick"] + 50, (rows[0], rows[1])      # the timeout re-armed at S + 50
    assert [(r["result"], r["j"]) for r in rows[1:4]] == [("hit", 1), ("hit", 5), ("hit", 50)], rows[1:4]
    assert all((r["result"], r["j"]) == ("hit", 5) for r in rows[4:]), rows[4:]
    v = fake.chanbara_vars                             # 48 hits after the timeout, and the phantom's credit again
    assert v["I30"] == 49 + 45 + 0 + 45 * 45 + 45 and v["I32"] == sum(range(48)) + 48 and v["I42"] == 49, v
    # a one-frame tap is ONE tick's edge, whatever the frame runs
    for fps in (31.0, 60.0):
        fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "walk_in_s": 6.0}}, fps=fps, trace=False)
        m = fake._machine
        edges, ran = [], {}
        real = m.on_tick

        def tick(f, real=real, m=m):
            edges.append(m.keyon & 0x10)
            ran[f.frame] = ran.get(f.frame, 0) + 1
            real(f)
        m.on_tick = tick
        taps = 0
        every = 3 if fps < 40 else 5                   # a tick between two taps must see the key released
        for n in range(int(5.0 * fps)):
            if n % every == 0:
                fake._schedule("up", 1)
                taps += 1
                if n == 30:
                    fake.hitch(0.07)                   # this tap's frame runs three ticks
            fake._frame_once()
        fake._frame_once()                             # a last tap's frame may run no tick: the next one reads it
        assert sum(1 for e in edges if e) == taps, (fps, taps, sum(1 for e in edges if e))
        assert 0 in [ran.get(f, 0) for f in range(1, fake.frame)] and max(ran.values()) >= 3, (fps, ran)


def test_fake_chanbara_scores_a_perfect_run_exactly(game):
    """H11's score (research/o4_design.md 3; 64 e4 t1 ip208-537): 49 hits at j 5 are I30 49 x 45 + 45 (the PHANTOM pass
    credits the 49th again) and I32 0 + ... + 49 = 1225 -- raw 3475 // 29 = 119, the +30% 152, clamped 100; the trace's
    ip338 Byte[475] 0 -> 100 BEFORE page 122 opens and ip390 Bit[3815] 0 -> 1 AFTER page 123 is gone; pages 122 ("Of
    100 nobles watching,\\n100 were impressed.") and 123; choice 127 published with its cursor on Yes (0) and answered
    No; then 128 "They shower you with 10000 Gil!", the gil, "Encore" reported once, and Field(150) into ``exit_to``
    with ip331 and ip528 before it. Break: drop the phantom credit (I42 49: pages 120/121, no ip390)."""
    pub: list = []
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821}}, publish=pub)
    _cb_play(fake)
    v = fake.chanbara_vars
    assert (v["I30"], v["I32"], v["I42"], v["I34"]) == (2250, 1225, 50, 50), v
    assert (v["I48"], v["I50"]) == (100, 10000) and fake.achievements == ["Encore"] and fake.gil == 10000, v
    assert fake.field_id == 30821 and fake._machine is None and not fake._beats and fake.texts == []
    trace = _cb_trace(fake)
    keys = [(sid, tag, ip, old, new) for sid, tag, ip, _b, old, new, _f in trace]
    assert keys == [(0, 0, 22, 0, 0), (0, 0, 49, 0, 0), (0, 0, 57, 0, -1), (0, 0, 119, 0, 0), (0, 0, 138, 0, -1),
                    (0, 0, 200, 0, 0), (0, 0, 416, 0, 0), (0, 0, 425, 0, 0), (0, 0, 475, 0, 125),
                    (4, 1, 338, 0, 100), (4, 1, 390, 0, 1), (2, 1, 331, 125, 0), (2, 1, 528, 0, 325)], keys
    f338, f390 = trace[9][6], trace[10][6]
    assert f338 <= _cb_event(fake, "open", "Of 100 nobles")["frame"], f338      # ip338, then WindowSync ip375
    assert f390 >= _cb_event(fake, "gone", "quite impressed")["frame"], f390
    pages = [t for t in _cb_opened(fake) if t not in ("Press  !",)]
    assert pages == ["Blank\n“En garde!”", "Zidane\n“Expect no quarter from me!”",
                     "To follow Blank’s lead, enter the correct\ncommands from the following choices:",
                     "Blank\n“We shall finish this later!”", "Zidane\n“Come back here!”",
                     "Of 100 nobles watching,\n100 were impressed.", "Queen Brahne was\nquite impressed.",
                     "They demand an encore!\nPerform the fight scene again?\nes\nNo",
                     "They shower you with 10000 Gil!"], pages
    ready = next(p for p in pub if p["choice"] is not None and p["group"] == "Dialog.Choice")
    assert ready["choice"]["selected"] == 0 and ready["choice"]["options"] == [
        "They demand an encore!\nPerform the fight scene again?", "es", "No"], ready
    assert fake.answered == [1]


def test_fake_chanbara_times_out_and_rearms_in_the_same_tick(game):
    """H11 (research/o4_design.md 0.2 #1): prompt 7 left alone times out at S + 50 -- e20's WAIT ends with TimeLeft 0,
    Byte[47] 3, CloseWindow(1), the score, and the NEXT ARM IN THE SAME TICK: prompt 8 armed at S + 50, its window
    published beside 7's still in its close tween, and no prompt-free publication between 7's first and 8's. The combo
    is broken: max combo below 50, pages 120/121, no ip390 row. Break: a Wait(1) between the score and the arm."""
    pub: list = []
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821}}, publish=pub)
    _cb_play(fake, press=lambda r: None if r["n"] == 7 else _cb_default_press(r))
    rows = fake.chanbara_log
    r7, r8 = rows[6], rows[7]
    assert r7["result"] == "timeout" and r8["arm_tick"] == r7["arm_tick"] + 50, (r7, r8)
    seven = f"[DBTN={r7['dbtn']}]"
    eight = f"[DBTN={r8['dbtn']}]"
    first7 = next(p["frame"] for p in pub if p["frame"] > r7["arm_frame"] - 1 and any(seven in r for r in p["raw"]))
    first8 = next(p for p in pub if p["frame"] > r8["arm_frame"] - 1 and any(eight in r for r in p["raw"]))
    between = [p for p in pub if first7 <= p["frame"] < first8["frame"]]
    assert between and all(any("[DBTN=" in r for r in p["raw"]) for p in between), between[-3:]
    assert any(seven in r for r in first8["raw"]) and len(first8["raw"]) == 2, first8
    assert fake.chanbara_vars["I42"] < 50
    assert "Of the 100 nobles watching,\n" in "".join(_cb_opened(fake)) and \
        "Queen Brahne was\nnot impressed." in _cb_opened(fake)
    assert not [t for t in _cb_trace(fake) if t[2] == 390], _cb_trace(fake)


def test_fake_chanbara_misses_a_circle_pressed_as_circle(game):
    """H11's button map, the agent's way (HarnessAgent.ParseControl): ``circle`` is Control.CONFIRM -- the Cross bit
    0x4000 -- so on a CIRCLE prompt (Byte[46] 6, polled on 0x2000) it is a MISS; ``cancel`` (Circle 0x2000) hits it;
    ``x``, another Confirm alias, hits a CROSS prompt. Seed 0's 16th and 27th prompts are CIRCLE (the max combo is 15 by
    the 16th; a miss keeps it). Break: map ``circle`` to Cancel."""
    def press(r):
        if r["dbtn"] == "CIRCLE":
            return ("circle" if r["n"] == 16 else "cancel"), 5, 1
        if r["dbtn"] == "CROSS" and r["n"] == 1:
            return "x", 5, 1
        return _cb_default_press(r)
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "seed": 0}}, trace=False)
    _cb_play(fake, press=press)
    rows = {r["n"]: r for r in fake.chanbara_log}
    assert (rows[1]["dbtn"], rows[1]["result"]) == ("CROSS", "hit"), rows[1]
    assert (rows[16]["dbtn"], rows[16]["result"]) == ("CIRCLE", "miss"), rows[16]
    assert (rows[27]["dbtn"], rows[27]["result"]) == ("CIRCLE", "hit"), rows[27]
    assert [r["result"] for r in fake.chanbara_log].count("miss") == 1


def test_fake_chanbara_misses_two_keys_start_and_a_held_key(game):
    """H11's e3 (64 e3 t1 ip34-429): every check is evaluated in a tick, so two keys in one tick MISS (the wrong one
    sets Byte[46] to its code, and the right one then fails too); Start is read as a LEVEL (B_KEY(8), ip412), so held it
    misses the first poll; and a key HELD across an arm gives no edge after it -- the prompt times out. Seed 0's prompts
    1-3 are CROSS, TRIANGLE, RIGHT. Break: test the right bit first and stop (two keys then hit)."""
    def press(r):
        if r["n"] == 1:
            return [("confirm", 5, 1), ("left", 5, 1)]
        return _cb_default_press(r) if r["n"] > 3 else None
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "seed": 0}}, trace=False)
    m = fake._machine
    _cb_play(fake, press=press, until=lambda f: len(f.chanbara_log) >= 2)
    assert fake.chanbara_log[0]["result"] == "miss" and fake.chanbara_log[0]["j"] == 5, fake.chanbara_log[0]
    r2 = fake.chanbara_log[1]
    fake._schedule("start", 10)                                 # Start held from the tick after prompt 2's arm
    _cb_play(fake, press=press, until=lambda f: f.chanbara_log[1]["result"] is not None)
    assert (r2["dbtn"], r2["result"], r2["j"]) == ("TRIANGLE", "miss", 1), r2
    # prompt 3 (seed 0: RIGHT) arms when prompt 2's reaction ends: its key held from 2 ticks before that to 7 after
    _cb_play(fake, press=press, until=lambda f: m.tick >= m.arm_tick + m.react - 3)
    fake._schedule("right", 10)
    _cb_play(fake, press=press, until=lambda f: len(f.chanbara_log) >= 3 and f.chanbara_log[2]["result"] is not None)
    r3 = fake.chanbara_log[2]
    assert r3["dbtn"] == "RIGHT" and r3["result"] == "timeout", r3
    assert r3["arm_tick"] - 2 <= m.tick, r3


def test_fake_chanbara_filters_hold_on_every_seed(game):
    """H11's roll (64 e20 t1 ip451-707), on seeds 0-19 with every prompt hit at j 5: consecutive prompts always differ
    (ip681); at SByte[38] -1 or 0 never LEFT, at 1 or 2 never RIGHT (ip473-551); no DOWN or UP while the max combo is
    under 10 (ip577/603), no CIRCLE or SQUARE under 15 (they become TRIANGLE and CROSS, ip629/655); 49 prompts over 50
    passes. Break: drop the no-repeat filter."""
    for seed in range(20):
        fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "seed": seed}}, trace=False)
        _cb_play(fake, until=lambda f: f._machine.phase == "done")
        rows = fake.chanbara_log
        assert len(rows) == 49 and fake._machine.v["I34"] == 50, (seed, len(rows))
        for prev, r in zip([None, *rows], rows):
            d = r["dbtn"]
            assert prev is None or d != prev["dbtn"], (seed, r)
            assert not (r["sb38"] in (-1, 0) and d == "LEFT") and not (r["sb38"] in (1, 2) and d == "RIGHT"), (seed, r)
            assert not (r["max_combo"] < 10 and d in ("DOWN", "UP")), (seed, r)
            assert not (r["max_combo"] < 15 and d in ("CIRCLE", "SQUARE")), (seed, r)
        assert {r["result"] for r in rows} == {"hit"}, seed


def test_fake_chanbara_bonus_knob_and_assistance_levels(game):
    """H11's score under the settings (EMinigame.cs:9-38): every prompt hit at j 22 is raw (28 x 50 + 1225) // 29 = 90;
    SwordplayAssistance 1 with the hook firing: +30% -> 117, clamped 100, Byte[475] 100; ``bonus_fires`` False (a fork
    whose EffectiveFieldId wrap fails): 90 -- Byte[475] 90, page 122 "90 were impressed." -- and no achievement; SA 0
    with the hook: 90, "Encore" still reported (>= 75); SA 2: TimeLeft refilled every tick, so an unpressed prompt
    never times out. Break: apply the bonus after the clamp."""
    def j22(r):
        return _CB_BUTTON[r["dbtn"]], 22, 1
    got = {}
    for name, knobs in (("sa1", {}), ("off", {"bonus_fires": False}), ("sa0", {"sa": 0})):
        fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, **knobs}})
        _cb_play(fake, press=j22)
        assert {r["j"] for r in fake.chanbara_log} == {22}, name
        got[name] = (fake.chanbara_vars["I48"], fake.story_bytes[475], fake.achievements,
                     [t for t in _cb_opened(fake, "page") if "nobles" in t])
    assert got["sa1"] == (100, 100, ["Encore"], ["Of 100 nobles watching,\n100 were impressed."]), got["sa1"]
    assert got["off"] == (90, 90, [], ["Of 100 nobles watching,\n90 were impressed."]), got["off"]
    assert got["sa0"] == (90, 90, ["Encore"], ["Of 100 nobles watching,\n90 were impressed."]), got["sa0"]
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "sa": 2}}, trace=False)
    _cb_play(fake, press=None, until=lambda f: f.chanbara_log and f._machine.tick > f.chanbara_log[0]["arm_tick"] + 120)
    m = fake._machine
    assert len(fake.chanbara_log) == 1 and fake.chanbara_log[0]["result"] is None and m.v["b52"] > 0, m.v
    assert [w.kind for w in m.windows] == ["prompt"] and not m.windows[0].closing


def test_fake_chanbara_encore_yes_replays_without_111(game):
    """H11's encore (64 e4 t1 ip462-542, e2 stages 6 -> 7 -> 8 -> 3): Yes replays the fight -- the walk back, the
    109/110 KEYON pair (109 first: e20's Wait(3), e13's Wait(15)), NO tutorial 111, a second fight of 49 prompts, 122,
    123 and 127 again; a second perfect run does not rewrite Byte[475] (ip327: 100 is not below 100) but stores
    Bit[3815] again (1 -> 1); No then pays the gil once. Break: replay through stage 2 (105/106 and 111 again)."""
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821}})
    _cb_play(fake, answers=(0, 1))
    opened = [t for t in _cb_opened(fake) if t != "Press  !"]
    first127 = opened.index("They demand an encore!\nPerform the fight scene again?\nes\nNo")
    after = opened[first127 + 1:]
    assert after[:2] == ["Blank\n“Is that the best thou canst do!?”", "Zidane\n“Die, traitor!”"], after
    assert not [t for t in after if "To follow Blank" in t or "En garde" in t], after
    assert after.count("They demand an encore!\nPerform the fight scene again?\nes\nNo") == 1
    assert [r["fight"] for r in fake.chanbara_log].count(2) == 49 and fake.answered == [0, 1]
    assert [(ip, old, new) for _s, _t, ip, _b, old, new, _f in _cb_trace(fake) if ip in (338, 390)] == [
        (338, 0, 100), (390, 0, 1), (390, 1, 1)], _cb_trace(fake)
    assert fake.gil == 10000 and fake.field_id == 30821


def test_fake_chanbara_close_tween_and_slides(game):
    """H11's timings (research/o4_design.md 0.2 #1, 0.3 #3). A hit's window stays listed a frame plus 0.09 s after
    its hit tick (DialogAnimator.cs:144-173), never the whole 0.15 s; and a LEFT hit on prompt n slides both bodies in
    pass n's reaction, the one that arms prompt n + 1 at S': Blank -60 a tick from S'+1 to -300 after S'+5, Zidane a
    tick behind (-60 after S'+2 ... -300 after S'+6), nothing at S' itself; a MISS on a LEFT prompt slides nothing.
    Seed 0's 5th and 14th prompts are LEFT (the 14th is missed here). Break: release a closed window at once, or move
    the whole slide in the arm tick."""
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "seed": 0}}, fps=60.0, ticks="mean", trace=False)
    _cb_play(fake, until=lambda f: len(f.chanbara_log) >= 3)
    hits = [e for e in fake.machine_log if e["kind"] == "prompt" and e["event"] in ("close", "gone")]
    for close, gone in zip(hits[0::2], hits[1::2]):
        assert (close["event"], gone["event"]) == ("close", "gone"), hits
        assert 0.09 + 1 / 60 - 1e-9 <= gone["rt"] - close["rt"] < 0.15, (close, gone)
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "seed": 0}}, trace=False)
    m = fake._machine
    track = {}
    real = m.on_tick

    def tick(f, real=real):
        real(f)
        track[m.tick] = (m.blank["x"], f.player[0])
    m.on_tick = tick
    _cb_play(fake, press=lambda r: ("special", 5, 1) if r["n"] == 14 else _cb_default_press(r),
             until=lambda f: len(f.chanbara_log) >= 16)
    rows = {r["n"]: r for r in fake.chanbara_log}
    assert (rows[5]["dbtn"], rows[5]["result"], rows[14]["dbtn"], rows[14]["result"]) == ("LEFT", "hit", "LEFT", "miss")
    s = rows[6]["arm_tick"]
    b0, p0 = track[s]
    assert [track[s + k] for k in range(7)] == [(b0, p0), (b0 - 60, p0), (b0 - 120, p0 - 60), (b0 - 180, p0 - 120),
                                                (b0 - 240, p0 - 180), (b0 - 300, p0 - 240), (b0 - 300, p0 - 300)], \
        [track[s + k] for k in range(7)]
    s2 = rows[15]["arm_tick"]
    assert len({track[s2 + k] for k in range(8)}) == 1, [track[s2 + k] for k in range(8)]


def test_fake_chanbara_page_ignores_confirm_while_opening(game):
    """H11's pages and choice take Confirm only once COMPLETE (Dialog.cs:762-802; research/o4_design.md 0.3 #1): at
    60 fps a Confirm going down 4 frames after page 123 opened (past ``open_frames``, inside ``open_s`` 0.105 s) is
    dropped -- 123 stays listed -- and one 12 frames on closes it; on 127 a Confirm 4 frames in closes nothing and moves
    nothing (its cursor still on 0, its group '' until it is ready). Break: ``open_s`` 0."""
    fake = _cb_fake(game, {"chanbara": {"exit_to": 30821}}, fps=60.0, ticks="mean", trace=False)
    m = fake._machine
    _cb_play(fake, press=lambda r: (_CB_BUTTON[r["dbtn"]], 10, 2),
             until=lambda f: any(w.text == "Queen Brahne was\nquite impressed." for w in m.windows))
    w123 = next(w for w in m.windows if w.text == "Queen Brahne was\nquite impressed.")
    _cb_until(fake, lambda f: f.frame >= w123.frame0 + 3)
    fake._schedule("confirm", 2)                                # down 4 frames after it opened
    for _ in range(6):
        fake._frame_once()
    assert w123 in m.windows and not w123.closing and w123.complete, w123.__dict__
    _cb_until(fake, lambda f: f.frame >= w123.frame0 + 11)
    fake._schedule("confirm", 2)
    fake._frame_once()
    assert w123.closing, w123.__dict__
    _cb_until(fake, lambda f: any(w.kind == "choice" for w in m.windows), limit=2000)
    ch = next(w for w in m.windows if w.kind == "choice")
    _cb_until(fake, lambda f: f.frame >= ch.frame0 + 3)
    fake._schedule("confirm", 2)
    for _ in range(3):
        fake._frame_once()
    assert not ch.closing and ch.cursor == 0 and ch.answer is None and fake.menu.get("group") == "", (ch.__dict__,
                                                                                                     fake.menu)
    _cb_until(fake, lambda f: ch.complete, limit=200)
    fake._frame_once()
    assert fake.menu.get("group") == "Dialog.Choice" and fake.choice["selected"] == 0 and fake.answered == []


def test_fake_chanbara_publication_order_and_true_j(game):
    """H11's ``publish_order`` (research/o4_design.md 0.3 #2, 3): under "agent_first" -- the engine's measured order --
    the first publication listing a prompt is the frame AFTER its arm frame (a sample shows the ticks of frames <= f-1);
    under "agent_last" it is the arm frame itself. And ``chanbara_log`` holds each instance's arm tick, edge tick and
    TRUE j: the edge on the first tick of the frames >= the key's down frame, j = edge - arm. At 31 fps (quantized) and
    60 fps (mean ticks). Break: ignore the knob (agent_last always)."""
    for fps, ticks in ((31.0, "quantized"), (60.0, "mean")):
        for order in ("agent_first", "agent_last"):
            pub: list = []
            fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "publish_order": order}}, fps=fps, ticks=ticks,
                            trace=False, publish=pub)
            m = fake._machine
            tick_of = {}
            real = m.on_tick

            def tick(f, real=real, m=m, tick_of=tick_of):
                tick_of.setdefault(f.frame, m.tick)
                real(f)
            m.on_tick = tick

            def press(r):
                return _CB_BUTTON[r["dbtn"]], 6 + r["n"] % 4, 1
            _cb_play(fake, press=press, until=lambda f: len(f.chanbara_log) >= 6)
            for r in fake.chanbara_log[:5]:
                first = next(p["frame"] for p in pub if p["frame"] >= r["arm_frame"]
                             and any(f"[DBTN={r['dbtn']}]" in x for x in p["raw"]))
                want = r["arm_frame"] + (1 if order == "agent_first" else 0)
                assert first == want, (fps, order, r, first)
                down = r["arm_frame"] + 6 + r["n"] % 4
                edge_frame = min(f for f in tick_of if f >= down)
                assert (r["result"], r["edge_frame"], r["edge_tick"]) == ("hit", edge_frame, tick_of[edge_frame]), \
                    (fps, order, r, edge_frame)
                assert r["j"] == r["edge_tick"] - r["arm_tick"] >= 1, r


def test_fake_chanbara_faults(game):
    """H12's fault knobs (research/o4_design.md 3), each alone, seed 0, every prompt pressed at j 5: ``lost`` {7} --
    prompt 7 pressed, the game never reads it: it lingers to its timeout at S + 50; ``miss_read`` {3} -- the right key
    on prompt 3 (RIGHT) scored a miss: its window closes on the key, no slide follows, the combo is broken (120/121);
    ``score_override`` 87 -- page 122 "87 were impressed."; ``extra_prompts`` 1 -- a 50th prompt; ``menu_on_triangle``
    -- a TRIANGLE press opens the main menu (ui "MainMenu"), the prompt left armed; ``unsubstituted_once`` -- 122's first
    publication reads "[NUMB=0] were impressed.", its next "100 were impressed."; ``replay_on_no`` -- No replays (109 and
    110 after the choice). Break: ignore ``lost``."""
    def run(knobs, **kw):
        fake = _cb_fake(game, {"chanbara": {"exit_to": 30821, "seed": 0, **knobs}}, trace=False,
                        publish=kw.pop("publish", None))
        _cb_play(fake, **kw)
        return fake
    fake = run({"lost": [7]}, until=lambda f: len(f.chanbara_log) >= 8)
    r7 = fake.chanbara_log[6]
    assert r7["result"] == "timeout" and fake.chanbara_log[7]["arm_tick"] == r7["arm_tick"] + 50, r7
    assert _cb_event(fake, "close", "Press", 6)["tick"] == r7["arm_tick"] + 50
    fake = run({"miss_read": [3]})
    r3, r5 = fake.chanbara_log[2], fake.chanbara_log[4]
    # a RIGHT hit's reaction (at prompt 4's arm, after its roll) would leave SByte[38] 1 for prompt 5's roll
    assert (r3["dbtn"], r3["result"], r3["j"]) == ("RIGHT", "miss", 5) and r5["sb38"] == 0, (r3, r5)
    assert "Queen Brahne was\nnot impressed." in _cb_opened(fake)
    fake = run({"score_override": 87})
    assert "Of 100 nobles watching,\n87 were impressed." in _cb_opened(fake)
    fake = run({"extra_prompts": 1}, until=lambda f: f._machine.phase == "done")
    assert len(fake.chanbara_log) == 50
    fake = run({"menu_on_triangle": True}, press=lambda r: (_CB_BUTTON[r["dbtn"]], 5, 1) if r["n"] <= 2 else None,
               until=lambda f: f.ui_state == "MainMenu" or len(f.chanbara_log) > 2)
    assert fake.ui_state == "MainMenu" and fake.chanbara_log[1]["dbtn"] == "TRIANGLE", fake.chanbara_log
    assert fake.chanbara_log[1]["result"] is None and fake._machine.v["b47"] == 1
    pub: list = []
    fake = run({"unsubstituted_once": True}, publish=pub)
    nobles = [p["texts"] for p in pub if any("nobles" in t for t in p["texts"])]
    assert nobles[0] == ["Of 100 nobles watching,\n[NUMB=0] were impressed."], nobles[:2]
    assert nobles[1] == ["Of 100 nobles watching,\n100 were impressed."], nobles[:2]
    gil = [p["texts"] for p in pub if any("shower" in t for t in p["texts"])]
    assert gil[0] == ["They shower you with [NUMB=1] Gil!"] and gil[1] == ["They shower you with 10000 Gil!"], gil[:2]
    fake = run({"replay_on_no": True}, until=lambda f: "Zidane\n“Die, traitor!”" in _cb_opened(f))
    assert fake.answered == [1] and _cb_opened(fake)[-2:] == ["Blank\n“Is that the best thou canst do!?”",
                                                               "Zidane\n“Die, traitor!”"]


# ---- O4's Chanbara policy, its pure half (studies/story-trace/segment_drive.py, S7; research/o4_design.md 2.4, 9 B2):
# the policy's strict reading, the prompt recognizers, the j and raw bounds, the judge, the slides and the encore's
# attribution -- each over synthetic rows, no fake, no session.

_O4_BUTTONS = {"LEFT": "left", "RIGHT": "right", "UP": "up", "DOWN": "down", "TRIANGLE": "menu", "CROSS": "confirm",
               "CIRCLE": "cancel", "SQUARE": "special"}
_O4_RATE = {"fps": 59.9, "fps_lo": 59.5, "fps_hi": 60.4, "tick_hz": 30.0, "source": "mtime", "samples": 24,
            "frame": 1000, "stale": False}


def _o4_policy(**over):
    """research/o4_design.md 4.10's draft policy (``over`` replaces keys; a key set to ``...`` is dropped)."""
    pol = {"policy": "fast", "donor": 64, "sc": 1155, "buttons": dict(_O4_BUTTONS), "press_frames": 2, "prompts": 49,
           "j_cap": 16, "raw_floor": 100, "gone_ticks": 12, "zone_start": {"match": "To follow Blank", "dbtns": 8},
           "zone_end": ["We shall finish this later!", "Come back here!"], "first_prompt_s": 3.0,
           "zone_stall_s": 5.0, "page_once_ticks": 10, "quiet": ["Queen Brahne was"], "quiet_cap_s": 5.0,
           "score_page": "Of 100 nobles watching,\n100 were impressed.", "gil_page": "They shower you with 10000 Gil!",
           "encore_match": "encore", "poll_s": 0.005, "state_every": None, "input_every_s": 0.05,
           "ring_every_s": 2.0, "why": "64 stage 3, the sword fight: one mapped press per prompt, fast"}
    for k, v in over.items():
        if v is ...:
            pol.pop(k, None)
        else:
            pol[k] = v
    return pol


def _o4_paced(**over):
    """The paced overlay (2.4.10): no raw_floor, j_cap 40, the pace -- ``over`` on top."""
    return _o4_policy(**{"policy": "paced", "raw_floor": ..., "j_cap": 40,
                         "pace": {"target_ticks": 22, "lead_ticks": 2, "raw_band": [79, 99]}, **over})


def _o4_prompt_raw(dbtn):
    mobi = {"LEFT": 267, "RIGHT": 269, "TRIANGLE": 272, "DOWN": 270, "CROSS": 274, "UP": 268, "CIRCLE": 273,
            "SQUARE": 271}[dbtn]
    return f"[STRT=54,1][TAIL=UPRF][IMME]Press [DBTN={dbtn}][MOBI={mobi}] ![TIME=-1]"


def test_o4_chanbara_of_is_strict():
    """S7's policy is read STRICT before anything is driven (research/o4_design.md 2.4.4, 4.10, section 8's unit), as
    ``movies_of`` reads the movie-skip policy: no key -> None; 4.10's draft and the paced overlay pass (a copy); each
    of these raises, once: an unknown key, a missing one, ``circle`` for CIRCLE (named for what it is:
    Control.Confirm, the Cross bit), any other map, ``j_cap`` 17 under fast, a ``raw_floor`` under paced, a ``pace``
    under fast, ``press_frames`` 0, ``stop_after`` 49, a bool for an int, ``input_every_s`` 0.2 and ``ring_every_s``
    8. Break: accept the ``circle`` alias."""
    SD = _segment_modules()
    assert SD.chanbara_of({}) is None
    draft = _o4_policy()
    got = SD.chanbara_of({"chanbara": draft})
    assert got == draft and got is not draft
    paced = _o4_paced(stop_after=10)
    assert SD.chanbara_of({"chanbara": paced}) == paced
    circle = dict(_O4_BUTTONS, CIRCLE="circle")
    cases = [(_o4_policy(extra=1), "unknown key"), (_o4_policy(gone_ticks=...), "missing"),
             (_o4_policy(buttons=circle), "Control.Confirm"),
             (_o4_policy(buttons=dict(_O4_BUTTONS, TRIANGLE="triangle")), "Control.Menu's second spelling"),
             (_o4_policy(buttons=dict(_O4_BUTTONS, CROSS="start")), "LEVEL"),
             (_o4_policy(buttons=dict(_O4_BUTTONS, LEFT="west")), "an alias of left"),
             (_o4_policy(buttons=dict(_O4_BUTTONS, UP="down")), "where the map is 'up'"),
             (_o4_policy(j_cap=17), "j_cap"), (_o4_paced(raw_floor=100), "raw_floor under the paced"),
             (_o4_policy(pace={"target_ticks": 22, "lead_ticks": 2, "raw_band": [79, 99]}), "a pace under the fast"),
             (_o4_policy(press_frames=0), "press_frames"), (_o4_policy(stop_after=49), "stop_after"),
             (_o4_policy(prompts=True), "prompts"), (_o4_policy(input_every_s=0.2), "input_every_s"),
             (_o4_policy(ring_every_s=8), "ring_every_s"), (_o4_policy(raw_floor=78), "raw_floor"),
             (_o4_paced(pace={"target_ticks": 22, "lead_ticks": 22, "raw_band": [79, 99]}), "pace"),
             (_o4_policy(zone_start={"match": "To follow Blank", "dbtns": 7}), "zone_start"),
             (_o4_policy(quiet=[]), "quiet"), (_o4_policy(state_every=2), "state_every"),
             (_o4_policy(policy="slow"), "policy")]
    for pol, match in cases:
        with pytest.raises(ValueError, match=re.escape(match)):
            SD.chanbara_of({"chanbara": pol})
    with pytest.raises(ValueError, match="CIRCLE -> 'circle' is Control.Confirm -- the Cross bit"):
        SD.chanbara_of({"chanbara": _o4_policy(buttons=circle)})


def test_o4_prompt_recognizers_claim_exactly_the_prompts():
    """S7's recognizers read ``phrase_raw`` (research/o4_design.md 2.4.1, section 8's unit): each of the eight prompt
    forms is its button; 111 (eight [DBTN] tags) is no prompt but the zone start; 150's window 55 (two tags, no
    "Press") is neither; a prompt without [TIME=-1] is none; the rendered "Press  !" alone is none (the glyph renders
    to nothing, so all eight read alike); a zone-end text is read off the rendered texts. Break: read the rendered
    text (strip the tags first)."""
    SD = _segment_modules()
    pol = _o4_policy()
    for dbtn in _O4_BUTTONS:
        assert SD.prompt_dbtn(_o4_prompt_raw(dbtn)) == dbtn, dbtn
        assert not SD.is_zone_start([_o4_prompt_raw(dbtn)], pol)
    from harness.fakegame import CHANBARA_MES
    t111 = "[STRT=233,5][TAIL=DEFT]" + CHANBARA_MES[111][2]
    assert SD.prompt_dbtn(t111) is None and SD.is_zone_start([t111], pol)
    assert not SD.is_zone_start([t111.replace("[DBTN=SQUARE]", "")], pol)
    w55 = "[STRT=180,3][TAIL=DEFT]Set Scenario Counter()\n[DBTN=START] OK  [DBTN=SELECT] Cancel"
    assert SD.prompt_dbtn(w55) is None and not SD.is_zone_start([w55], pol)
    assert SD.prompt_dbtn(_o4_prompt_raw("LEFT").replace("[TIME=-1]", "")) is None
    assert SD.prompt_dbtn("Press  !") is None and SD.prompt_dbtn(None) is None
    assert SD.prompt_dbtn("[IMME]Press [DBTN=LEFT][DBTN=RIGHT] ![TIME=-1]") is None
    assert SD.prompt_dbtn("[IMME]Press [DBTN=START] ![TIME=-1]") is None
    assert SD.is_zone_end(["Blank\n“We shall finish this later!”"], pol) and SD.is_zone_end(["Zidane\n“Come back here!”"],
                                                                                           pol)
    assert not SD.is_zone_end(["Press  !"], pol)


def _o4_row(n, dbtn, *, seen=None, prev=-2, down=4, excess=0.0, rate=None, **kw):
    """A prompt row as the executor completes it (2.4.6): ``seen`` its first frame (default 100 n), ``prev`` / ``down``
    offsets from it, its rate, the press and its accepted event, the j bounds from those frames, evidence "closed"."""
    SD = _segment_modules()
    seen = 100 * n if seen is None else seen
    row = {"k": "prompt", "n": n, "dbtn": dbtn, "button": _O4_BUTTONS[dbtn], "seq": 10 + n, "prev_frame": seen + prev,
           "prev_kind": "none", "seen_frame": seen, "accepted_frame": seen + down - 1, "down_frame": seen + down,
           "ack_frame": seen + down + 3, "rate": dict(rate or _O4_RATE), "excess": excess, "evidence": "closed",
           "read_gap": {"frames": 2, "ticks": 1, "s": 0.03}, "slide": None,
           "x_prev": {"player": 0.0, "blank": 600.0}, "x_seen": {"player": 0.0, "blank": 600.0}}
    row.update(kw)
    row["j_lo"], row["j_hi"] = SD.j_bounds(row)
    return row


def _o4_rows(n=49, **kw):
    seq = ["CROSS", "TRIANGLE", "RIGHT", "TRIANGLE", "LEFT", "CROSS", "TRIANGLE"]
    return [_o4_row(i, seq[(i - 1) % len(seq)], **kw) for i in range(1, n + 1)]


def _o4_zone(rows, **kw):
    end = rows[-1]["seen_frame"] + 60 if rows else 0
    zone = {"k": "zone", "end": {"frame": end, "text": "Blank\n“We shall finish this later!”"},
            "max_read_gap": {"frames": 2, "ticks": 1, "s": 0.03}}
    zone.update(kw)
    return zone


def _o4_presses(rows):
    return [{"k": "press", "why": "prompt", "n": r["n"], "seq": r["seq"], "button": r["button"],
             "down_frame": r["down_frame"]} for r in rows]


def test_o4_j_and_raw_bounds():
    """S7's bounds (research/o4_design.md 2.4.7, section 8's unit). j_bounds at 60 and 31 fps from a row's frames and
    rate -- ``j_hi = ticks_most(down - prev) + 1 + ceil(excess)``, ``j_lo = max(1, ticks_sure(down - seen - 1))`` --
    and a hitch's excess raising j_hi; raw_bounds on uniform j reproduces the plan's table (j 1 -> 126, 5 -> 119, 10 ->
    111, 16 -> 100, 17 -> 99, 20 -> 93, 28 -> 80, 29 -> 78), and the SA 1 display (79 -> 100, 78 -> 99). Then the
    bounds against the TRUE j, BOTH publication orders: synthetic frame / tick schedules at 31 and 60 fps (+-5% frame
    jitter, FPSManager's accumulator, a measured band of +-2%), each case's arm tick S placed in the frame the order
    lets its first listing sample show it (agent first: a sample of frame f shows the ticks of frames <= f-1; agent
    last: <= f; one sample every 2nd frame), the key down 1-8 frames after, its edge the first tick of the frames >=
    its down frame -- the true j lies in [j_lo, j_hi] in every case. Break: count j_hi from the first listing sample
    (``seen``) instead of the last before it (``prev``) -- at 31 fps, agent first, the true j exceeds it; or count
    j_lo from ``prev`` -- it overstates."""
    SD = _segment_modules()
    from harness.tickrate import Rate, TickAccumulator
    r60 = _o4_row(1, "LEFT", seen=1000)                    # 60 fps: prev = seen - 2, down = seen + 4
    assert (r60["j_lo"], r60["j_hi"]) == (1, 5), (r60["j_lo"], r60["j_hi"])
    assert SD.j_bounds(dict(r60, excess=2.3))[1] == 8
    r31 = _o4_row(1, "LEFT", seen=1000, prev=-1, down=3,
                  rate={"fps": 31.2, "fps_lo": 30.5, "fps_hi": 31.9, "tick_hz": 30.0, "source": "mtime"})
    assert (r31["j_lo"], r31["j_hi"]) == (1, 5), (r31["j_lo"], r31["j_hi"])
    assert SD.j_bounds({"prev_frame": 1, "seen_frame": 2, "down_frame": None, "rate": _O4_RATE}) == (None, None)
    for j, raw in ((1, 126), (5, 119), (10, 111), (16, 100), (17, 99), (20, 93), (28, 80), (29, 78)):
        assert SD.raw_bounds([{"j_lo": j, "j_hi": j}] * 49) == (raw, raw), j
    assert SD.raw_bounds([{"j_lo": 0, "j_hi": 60}] * 49) == (1225 // 29, 126)       # each j clamped to 1..50
    assert SD.raw_bounds(_o4_rows()) == (119, 126)                                # from the frames: [1, 5] each
    assert SD.raw_bounds([]) == (None, None)
    for raw, shown in ((79, 100), (78, 99)):
        assert min(100, raw + raw // 10 * 3) == shown
    rng = __import__("random").Random(11)
    for fps in (31.0, 60.0):
        acc, ticks_of, first_tick, tick_frame, t = TickAccumulator(30.0), {}, {}, {}, 0
        for f in range(1, 4001):
            n = acc.advance((1.0 / fps) * (1 + rng.uniform(-0.05, 0.05)))
            first_tick[f] = t + 1 if n else None
            for _ in range(n):
                t += 1
                tick_frame[t] = f
        rate = Rate(fps=fps, fps_lo=fps * 0.98, fps_hi=fps * 1.02, tick_hz=30.0, source="rt", samples=20, frame=1)
        for order in ("agent_first", "agent_last"):
            for _ in range(1500):
                s = rng.randint(200, t - 400)
                arm, phase = tick_frame[s], rng.randrange(2)
                pubs = [f for f in range(arm - 20, arm + 40) if f % 2 == phase]
                seen = next(f for f in pubs if (f - 1 if order == "agent_first" else f) >= arm)
                prev = max(f for f in pubs if f < seen)
                down = seen + rng.randint(1, 8)
                edge = next(first_tick[f] for f in range(down, down + 50) if first_tick.get(f))
                row = {"prev_frame": prev, "seen_frame": seen, "down_frame": down, "excess": 0.0,
                       "rate": rate.as_dict()}
                lo, hi = SD.j_bounds(row)
                assert lo <= edge - s <= hi, (fps, order, row, edge - s, lo, hi)


def test_o4_chanbara_judge_classes():
    """S7's judge (research/o4_design.md 2.4.8, section 8's unit), every line: proper rows -> None (raw [119, 126]);
    one instance at j_hi 45 -> V17 (over the cap); proper rows and a score page "99 were impressed." in two samples ->
    V18; one sample "[NUMB=0] ..." then "100 ..." -> None; ``evidence`` "lingered" on a proper press -> V18;
    "unobserved" (a read stall) -> V17, NEVER V18; "before" -> V17; a proper L/R press whose measured slide is 0 -> V18;
    a measured slide of -240 -> V17 (the instrument's samples); a wrong name, a double press, a missing accepted
    event, an unmeasured rate, a page press inside the fight -> V17 each; 48 instances with a 60-tick read gap -> V17,
    with no gap above 50 ticks -> V18; 50 instances -> V18; paced raw [80, 92] -> None, paced [76, 85] -> V17
    "uninformative"; a fast policy with raw_floor 110 and every j_hi 12 (raw_lo 107) -> V17. Break: rate an
    "unobserved" instance V18 (rev. 1's negative evidence)."""
    SD = _segment_modules()
    pol = _o4_policy()

    def judge(rows=None, *, zone=None, presses=None, policy=pol, page=None):
        rows = _o4_rows() if rows is None else rows
        return SD.chanbara_judge(_o4_zone(rows) if zone is None else zone, rows,
                                 _o4_presses(rows) if presses is None else presses, policy, page=page)

    def with_row(i, **kw):
        rows = _o4_rows()
        rows[i] = dict(rows[i], **kw)
        return rows
    assert judge() == {"v": None, "by": None, "why": None, "faults": [], "raw": [119, 126]}
    rows = _o4_rows()
    rows[6] = _o4_row(7, rows[6]["dbtn"], prev=-82)
    assert rows[6]["j_hi"] == 45 and judge(rows)["v"] == "V17" and "over j_cap 16" in judge(rows)["why"]
    score = pol["score_page"].replace("\n100 ", "\n99 ")
    got = judge(page={"kind": "score", "want": pol["score_page"], "texts": [score, score]})
    assert (got["v"], got["by"]) == ("V18", "game") and "99 were impressed" in got["why"], got
    unsub = pol["score_page"].replace("\n100 ", "\n[NUMB=0] ")
    assert judge(page={"kind": "score", "want": pol["score_page"], "texts": [unsub, pol["score_page"]]})["v"] is None
    assert judge(page={"kind": "gil", "want": pol["gil_page"], "texts": [pol["gil_page"]] * 2})["v"] is None
    got = judge(with_row(4, evidence="lingered"))
    assert (got["v"], got["by"]) == ("V18", "game") and "instance 5" in got["why"], got
    got = judge(with_row(8, evidence="unobserved", read_gap={"frames": 30, "ticks": 15, "s": 0.5}))
    assert (got["v"], got["by"]) == ("V17", "driver") and got["why"].startswith("instrument: a read gap of 0.5 s"), got
    assert judge(with_row(2, evidence="before"))["v"] == "V17"
    left = {"want": 300.0, "dx_player": 0.0, "dx_blank": 0.0, "ok": False, "left_out": [3]}
    got = judge(with_row(2, slide=left))
    assert (got["v"], got["by"]) == ("V18", "game") and "left out" in got["why"], got
    odd = {"want": -300.0, "dx_player": -240.0, "dx_blank": -240.0, "ok": False, "left_out": None}
    assert judge(with_row(4, slide=odd))["v"] == "V17"
    assert judge(with_row(0, button="x"))["v"] == "V17" and "not 'confirm'" in judge(with_row(0, button="x"))["why"]
    rows = _o4_rows()
    assert judge(rows, presses=_o4_presses(rows) + _o4_presses(rows)[:1])["v"] == "V17"
    assert "no accepted event" in judge(with_row(1, accepted_frame=None))["why"]
    assert "not measured" in judge(with_row(3, rate=dict(_O4_RATE, source="default")))["why"]
    rows = _o4_rows()
    stray = {"k": "press", "why": "page", "seq": 999, "down_frame": rows[0]["prev_frame"]}
    assert "inside the fight" in judge(rows, presses=_o4_presses(rows) + [stray])["why"]
    early = dict(stray, down_frame=rows[0]["prev_frame"] - 1)
    assert judge(rows, presses=_o4_presses(rows) + [early])["v"] is None
    rows = _o4_rows(48)
    assert judge(rows, zone=_o4_zone(rows, max_read_gap={"frames": 120, "ticks": 60, "s": 2.0}))["v"] == "V17"
    got = judge(rows, zone=_o4_zone(rows, max_read_gap={"frames": 100, "ticks": 50, "s": 1.7}))
    assert (got["v"], got["by"]) == ("V18", "game") and "fewer than 49" in got["why"], got
    got = judge(_o4_rows(50))
    assert got["v"] == "V18" and "more than the 49" in got["why"], got
    paced = _o4_paced()
    band = [dict(r, j_lo=21, j_hi=28) for r in _o4_rows()]
    assert judge(band, policy=paced) == {"v": None, "by": None, "why": None, "faults": [], "raw": [80, 92]}
    low = [dict(r, j_lo=25, j_hi=30) for r in _o4_rows()]
    got = judge(low, policy=paced)
    assert got["v"] == "V17" and got["why"] == "uninformative: raw [76, 85] is outside the band [79, 99]", got
    floor = [dict(r, j_lo=1, j_hi=12) for r in _o4_rows()]
    got = judge(floor, policy=_o4_policy(raw_floor=110))
    assert got["v"] == "V17" and got["why"] == "raw_lo 107 is under raw_floor 110", got
    stopped = _o4_rows(10) + [dict(_o4_row(11, "LEFT"), stopped=True, seq=None)]
    zone = _o4_zone(stopped, end=None)
    assert judge(stopped, zone=zone, presses=_o4_presses(stopped[:10]))["v"] is None


def test_o4_chanbara_judge_never_skips_an_unbounded_raw():
    """THE RAW IS NEVER LEFT UNJUDGED (research/o4_design.md 2.4.7, 2.4.8; the review, 11.5): a row with no prev frame
    -- instance 1 of a zone entered on a prompt, had nothing given its prev -- has no j bounds, so a complete zone's raw
    is unbounded and neither the fast policy's raw_floor nor the paced band can be judged on it. Each such zone is V17
    (the driver's: its play is not proven), never None: fast rows each pressed at j 16 (raw 100, at the floor) with
    instance 1 unbounded; the same rows with instance 1 at j 50 had it been bounded (raw 99: under the floor, the case
    an unjudged floor would pass); paced rows inside the band with instance 1 unbounded (R-GATE would read it
    informative). The first fault names the row and what it lacks, and "raw unbounded" is among a complete zone's
    faults; a zone stopped mid-fight (no end) names the row and no raw. Break: judge the floor and the band only when
    raw_bounds gives bounds (rev. 1: the zone then reads None)."""
    SD = _segment_modules()

    def judge(rows, policy, *, zone=None):
        return SD.chanbara_judge(_o4_zone(rows) if zone is None else zone, rows, _o4_presses(rows), policy)

    def unbound(rows):
        rows = [dict(r) for r in rows]
        rows[0] = dict(rows[0], prev_frame=None, j_lo=None, j_hi=None)
        rows[0]["j_lo"], rows[0]["j_hi"] = SD.j_bounds(rows[0])
        assert (rows[0]["j_lo"], rows[0]["j_hi"]) == (None, None)
        return rows
    fast = _o4_policy()
    j16 = [dict(r, j_lo=12, j_hi=16) for r in _o4_rows()]
    assert judge(j16, fast) == {"v": None, "by": None, "why": None, "faults": [], "raw": [100, 107]}
    slow = [dict(j16[0], j_lo=50, j_hi=50)] + j16[1:]
    got = judge(slow, fast)
    assert got["v"] == "V17" and "raw_lo 99 is under raw_floor 100" in got["faults"], got
    for rows in (unbound(j16), unbound(slow)):
        got = judge(rows, fast)
        assert (got["v"], got["by"], got["raw"]) == ("V17", "driver", [None, None]), got
        assert got["why"] == ("instance 1 (CROSS) has no j bounds (no prev frame): its press cannot be placed against "
                              "its arm"), got
        assert any(f.startswith("raw unbounded: the zone is complete but instance(s) [1]") and "raw_floor" in f
                   for f in got["faults"]), got["faults"]
    paced = _o4_paced()
    band = [dict(r, j_lo=21, j_hi=28) for r in _o4_rows()]
    assert judge(band, paced)["v"] is None
    got = judge(unbound(band), paced)
    assert got["v"] == "V17" and "has no j bounds" in got["why"], got
    assert any(f.startswith("raw unbounded") and "raw band" in f for f in got["faults"]), got["faults"]
    rows = unbound(_o4_rows(10))
    got = judge(rows, fast, zone=_o4_zone(rows, end=None))
    assert got["v"] == "V17" and "has no j bounds" in got["why"], got
    assert not any(f.startswith("raw unbounded") for f in got["faults"]), got["faults"]


def test_o4_slides_bracket_the_slide_from_the_prev_samples():
    """S7's slide witness (research/o4_design.md 2.4.6, section 8's unit; rev. 2, the driver critique #3, the claim
    critique #1), at ~31 fps with the agent-first publication: a synthetic L/R run -- a LEFT / RIGHT hit on prompt n
    slides Blank -60 a tick from S_{n+1}+1 and Zidane a tick behind, prompt n+1 armed at S_{n+1} -- whose first sample
    listing each prompt already shows a step of it. Measured between the PREV samples (instance n+1's and n+2's) every
    L/R slide reads its want exactly; a base sample under 7 sure ticks after its predecessor's ``seen_frame`` is
    "unmeasured"; the tail (48 LEFT, 49 LEFT) is measured jointly, -600 from instance 49's prev sample to the zone end's
    first; (48 RIGHT, 49 LEFT) is "unmeasured"; a miss (no slide) reads 0, its instance left out. Break: measure from
    the next instance's ``x_seen`` (rev. 1: the slides read -240)."""
    SD = _segment_modules()
    r31 = {"fps": 31.0, "fps_lo": 30.4, "fps_hi": 31.6, "tick_hz": 30.0, "source": "mtime", "samples": 30}

    def track(dbtns, *, missed=()):
        arm = {n: 100 + 30 * n + n % 2 for n in range(1, len(dbtns) + 2)}         # the last: the phantom pass
        moves = []
        for n, d in enumerate(dbtns, 1):
            step = {"LEFT": -60.0, "RIGHT": 60.0}.get(d)
            if step and n not in missed:
                s = arm[n + 1]
                moves += [(s + k, "blank", step) for k in range(1, 6)] + [(s + 1 + k, "player", step) for k in range(1, 6)]

        def pos(tick):                          # the bodies after ``tick`` (a frame a tick at ~31 fps)
            return {"player": 0.0 + sum(dx for t, b, dx in moves if b == "player" and t <= tick),
                    "blank": 600.0 + sum(dx for t, b, dx in moves if b == "blank" and t <= tick)}
        rows = []
        for n, d in enumerate(dbtns, 1):
            seen = arm[n] + 1 if (arm[n] + 1) % 2 == 0 else arm[n] + 2           # agent first, a sample every 2nd frame
            rows.append(_o4_row(n, d, seen=seen, rate=r31, x_prev=pos(seen - 3), x_seen=pos(seen - 1)))
        end = arm[len(dbtns) + 1] + 40
        return rows, {"frame": end, "x_player": pos(end - 1)["player"], "x_blank": pos(end - 1)["blank"]}
    seq = (["CROSS", "LEFT", "TRIANGLE", "RIGHT", "LEFT", "CROSS", "RIGHT", "TRIANGLE"] * 6)[:47] + ["LEFT", "LEFT"]
    rows, end = track(seq)
    lr = [r["n"] for r in rows if r["dbtn"] in ("LEFT", "RIGHT")]
    seen1 = [r["x_seen"]["blank"] - rows[r["n"] - 2]["x_prev"]["blank"] for r in rows[1:]]
    assert any(abs(dx) % 300 for dx in seen1 if dx), "premise: a first listing sample shows a step"
    slides = SD.measure_slides(rows, end, 49)
    assert sorted(slides) == lr
    for n in lr[:-2]:
        s = slides[n]
        assert s["ok"] is True and s["dx_blank"] == s["dx_player"] == s["want"], (n, s)
        assert (s["base"], s["end"]) == (rows[n]["prev_frame"], rows[n + 1]["prev_frame"]), (n, s)
    tail = slides[48]
    assert tail is slides[49] and tail["joint"] == [48, 49] and tail["want"] == -600.0 and tail["ok"] is True, tail
    assert (tail["base"], tail["end"]) == (rows[48]["prev_frame"], end["frame"]) and tail["dx_blank"] == -600.0
    near = [dict(r) for r in rows]
    n = lr[0]                                                   # its base: under 7 sure ticks after n's seen frame
    near[n] = dict(near[n], prev_frame=near[n - 1]["seen_frame"] + 3)
    assert SD.measure_slides(near, end, 49)[n]["ok"] == "unmeasured"
    rows2, end2 = track(seq[:47] + ["RIGHT", "LEFT"])
    assert SD.measure_slides(rows2, end2, 49)[48]["ok"] == "unmeasured"
    rows3, end3 = track(seq, missed={lr[1]})
    s = SD.measure_slides(rows3, end3, 49)[lr[1]]
    assert (s["ok"], s["left_out"], s["dx_blank"]) == (False, [lr[1]], 0.0), s
    s = SD.measure_slides(rows3, end3, 49)[lr[2]]
    assert s["ok"] is True, s


def test_o4_stray_answer_attributes_by_the_down_frame():
    """S9's encore attribution (research/o4_design.md 2.4.11, section 8's unit): over every Confirm-bearing press of the
    visit -- page, prompt and ``choose``'s, each placed by its accepted event (down = accepted + 1) -- a page press whose
    DOWN frame lies in [127's first frame, its close) is V17 (driver) though it was decided before 127 opened;
    ``choose``'s Confirm with the cursor on Yes before its down frame is V17; the same with the cursor on No is the
    answer's own, excluded: V2 (game); a prompt press long before 127 is ignored: V2; none: V2; a press landing on the
    close frame is past it; a Confirm with no accepted event cannot be placed: V17. Break: place a press by the frame
    it was decided on (``pre``) instead of its down frame; or leave out ``choose``'s presses."""
    SD = _segment_modules()
    first, close = 5000, 5040
    events = [{"frame": f, "kind": "accepted", "seq": str(s), "steps": "1"}
              for s, f in ((1, 100), (2, 5001), (3, 5010), (4, 5020), (6, 5039))]
    steps = [{"kind": "step", "seq": 3, "steps": ["press down 4"]}, {"kind": "step", "seq": 4, "steps": ["press confirm 4"]}]
    page = {"k": "press", "why": "page", "seq": 2, "button": "confirm", "pre": {"frame": 4996}}
    prompt = {"k": "press", "why": "prompt", "seq": 1, "button": "confirm", "pre": {"frame": 98}}
    down = {"k": "press", "why": "choose", "seq": 3, "pre": None}

    def answer(sel):
        return {"k": "press", "why": "choose", "seq": 4, "answer": True, "selected_before": sel, "pre": None}
    got = SD.stray_answer([page], events, steps, first, close)
    assert (got["v"], got["by"]) == ("V17", "driver") and "before its answer" in got["why"], got
    got = SD.stray_answer([prompt, down, answer(0)], events, steps, first, close)
    assert (got["v"], got["by"]) == ("V17", "driver") and "with the cursor on Yes" in got["why"], got
    for log in ([prompt, down, answer(1)], [prompt], []):
        got = SD.stray_answer(log, events, steps, first, close)
        assert (got["v"], got["by"], got["why"]) == ("V2", "game", "the game replayed though the driver confirmed No")
    late = {"k": "press", "why": "page", "seq": 6, "button": "ok", "pre": {"frame": 5038}}
    assert SD.stray_answer([late], events, steps, first, close)["v"] == "V2"            # down 5040: the close frame
    assert SD.stray_answer([late], events, steps, first, None)["v"] == "V17"            # no close yet
    lost = {"k": "press", "why": "page", "seq": 7, "button": "confirm", "pre": {"frame": 4990}}
    got = SD.stray_answer([lost], events, steps, first, close)
    assert got["v"] == "V17" and "no accepted event" in got["why"], got


# ---- O4's Chanbara policy on the drive (studies/story-trace/segment_drive.py, rule 6b, S7-S9; research/o4_design.md
# 2.2, 2.4, 9 B3), against H11 on the fake's fields: 30820 is "64", 30821 "150" (where the run ends, R-CHANBARA's
# shape); the F side's members 31240 ("64") and 31243 ("150") are appended to the fixture's DictionaryPatch, O1's
# pinning test's way. Every test models the engine where O4 needs it (O3's knobs: a warp lands without control and is
# refused off the field), publishes agent-first unless it says otherwise, and keeps the fake's loop at 4x its render
# rate (240 at 60 fps, 124 at 31): the driver's wall latency reaches the fight that much compressed, in ticks.

_O4_FIELDS = {"S": (30820, 30821), "F": (31240, 31243)}
_O4_RUNS = __import__("itertools").count(1)
_O4_NAMES = {"31240": "O4_ALEX_STANDS", "31243": "O4_ALEX_HALL"}


def _o4_pred(**over):
    """O4's driver keys (research/o4_design.md 2.1, 4.1, 4.10) on the fake's fields: no table, no battle, the stop
    pages, the encore rule and O1's skip net, route and visits "64", the end "150" per side, the policy at "64"."""
    pred = {"version": 1, "start": {"S": 30820, "F": 31240}, "entrance": 100, "scenario": 1155,
            "end_field": 30821, "end_fields": [30821], "side_ends": {"S": [30821], "F": [31243]},
            "route": [30820], "visits": [30820], "members": {"31240": 30820, "31243": 30821},
            "names": dict(_O4_NAMES),
            "budget": {"run_s": 120, "run_min_s": 1, "session_s": 600, "settle_s": 0.3, "no_progress_s": 60},
            "beats": ["sword", "encore"], "table": [], "naming": [], "forbidden": [], "end_state": {}, "regions": {},
            "hotspots": {}, "battles": [],
            "stop_pages": [{"match": "Env Play()", "why": "64's ambient error window"},
                           {"match": "Set Scenario Counter()", "why": "150's debug window 55"}],
            "choices": [{"donor": 30820, "sc": [1155], "match": "encore", "pick": "No", "once": True, "beat": "encore"},
                        {"donor": None, "sc": None, "match": "want to skip", "pick": "default", "once": False,
                         "beat": None}],
            "chanbara": _o4_policy(donor=30820)}
    pred.update(over)
    return pred


def _o4_register(game):
    patch = game / "FF9CustomMap" / "DictionaryPatch.txt"
    patch.write_text(patch.read_text(encoding="utf-8")
                     + "".join(f"FieldScene {f} 11 {n} {n} 2\n" for f, n in _O4_NAMES.items()), encoding="utf-8")


def _o4_fake(game, *, fps=60.0, ticks="mean", loop=None):
    fake = FakeGame(game, fps=loop or 4 * fps, render_fps=fps, ticks=ticks)
    fake.warp_arrive_control, fake.warp_field_only = False, True
    return fake


def _o4_run(game, side="S", *, knobs=None, pol=None, pred=None, fps=60.0, ticks="mean", sc=1155, trace=False,
            witness=None, wrap=None, phases=(), budget=120.0, register=True):
    """One O4 run on the fake: New Game, the raw warp into "64" (entrance 100, ``sc``), H11's Chanbara visit staged on
    arrival (``knobs`` over ``exit_to`` "150"), and the driver with ``pred`` (default :func:`_o4_pred`, ``pol``
    merged into its policy). ``wrap(g, fake)`` may wrap the session's calls before the drive; ``phases`` are more
    director phases after the beat's. ``(outcome or the exception raised, log, fake, story rows)``."""
    SD = _segment_modules()
    if side == "F" and register:
        _o4_register(game)
    fake = _o4_fake(game, fps=fps, ticks=ticks)
    start, exit_to = _O4_FIELDS[side]
    pred = _o4_pred() if pred is None else pred
    if pol:
        pred["chanbara"] = {**pred["chanbara"], **pol}
        for k in [k for k, v in pol.items() if v is ...]:
            pred["chanbara"].pop(k)
    log: list = []
    stop = threading.Event()
    beat = {"chanbara": {"exit_to": exit_to, **(knobs or {})}}
    with Session(game_path=game, run_dir=game / f"run-o4-{next(_O4_RUNS)}", save_dir=game / "player-saves",
                 pid_probe=lambda: [], launcher=lambda exe: fake.start(), boot_timeout=15.0, verbose=False) as g:
        boot(g)
        if trace:
            g.storytrace(True)
        g._check_field_id(start, "warp", True)
        g.send(f"warp {start} 100 {sc}")
        g.wait_for(lambda s: s.field_id == start and s.ui_state == "FieldHUD", timeout=10.0, what=f"field {start}")
        if wrap is not None:
            wrap(g, fake)
        _o1_director(fake, stop, [(lambda f: f.field_id == start and not f._beats,
                                   lambda f: f.scene(beat, control=False)), *phases])
        try:
            try:
                out = SD.drive(g, pred, side, log, deadline=time.time() + budget, floor_for=lambda d, c: _flat_bgi(),
                               prior_for=lambda d: _prior(), forbid_live=False, witness=witness)
            except (SD.RouteVoid, HarnessError) as err:
                out = err
        finally:
            stop.set()
        rows = _cb_trace(fake) if trace else []
    return out, log, fake, rows


def _o4_rows_of(log, k, **match):
    return [r for r in log if r.get("k") == k and all(r.get(a) == b for a, b in match.items())]


def _o4_void(out, v, by=None):
    """The run's VOID as raised: a RouteVoid of class ``v`` (and ``by``), or the instrument's HarnessError for V13."""
    SD = _segment_modules()
    if v == "V13":
        assert isinstance(out, HarnessError) and not isinstance(out, SD.RouteVoid), out
        return
    assert isinstance(out, SD.RouteVoid) and out.v == v, (getattr(out, "v", None), out)
    assert by is None or out.by == by, (out.by, out)


#: The fight zone's VOIDs only the INSTRUMENT's read gap gives -- the driver's V17 (segment_drive.chanbara_judge and
#: the instance tracker): a gap straddling an instance's down frame or its mark (evidence "unobserved"), a gap that could
#: hide a prompt's whole life, a gap that hid an instance from the tracker. On a LOADED machine (the nightly's -n 6,
#: another session's run beside it) a starved poll alone makes one: the fake's loop runs a 60 fps game up to 4x fast
#: (``fps`` 240), so the 24 frames from a press's down frame to its mark (gone_ticks 12) pass in about a tenth of a
#: second of wall time, and the window's close tween in a third of that. A fake drive test re-runs that run as R-GATE
#: re-runs an uninformative one (research/o4_design.md 7.4 G2) -- and NEVER a late press (a j over j_cap, a paced raw
#: out of its band, evidence "before", no press): a pace test asserts exactly those. The judge reads every V17 fault
#: before any V18, so a gap in ANY judged instance voids a clean end and a V18 alike: every fake drive test that
#: asserts either runs on :func:`_o4_run_informative`. One that asserts a READ-GAP V17, a V13 or a V2, or starves its
#: reads on purpose, stays on :func:`_o4_run`. A test whose V17 can never match a read gap (a reason none of these
#: patterns matches, pinned by its own row -- the quiet page's ``observed``) may run on :func:`_o4_run_informative`:
#: test_o4_drive_page_once_and_the_quiet_windows does, since a read gap flaked it serially on master. One that starves
#: its reads to assert the read-gap V17 re-runs only a read-gap VOID raised BEFORE its starve fired (a run that never
#: reached the starved press, :func:`_o4_starve_reads`'s ``fired``): test_o4_drive_read_stall_in_a_gap_is_v17_never_v18.
_O4_READ_GAP_VOIDS = (
    re.compile(r"instrument: a read gap of \S+ s straddles instance \d+'s mark \(evidence unobserved\)$"),
    re.compile(r"\d+ instances, and a read gap of \d+ ticks could hide a prompt's whole life$"),
    re.compile(r"a read gap hid an instance: "))


def _o4_read_gap_void(out, log):
    """The run's reason when its VOID is the instrument's read gap alone (:data:`_O4_READ_GAP_VOIDS`) -- a RouteVoid V17
    (driver) raised by the fight zone (its one ``zone`` row's ``why``) whose reason names a read gap -- else None. The
    reason alone decides (the judge's first fault, or the tracker's live stop): its later faults may follow from the gap
    (the next instance's j bounds widened by it), and a run set aside is never asserted on."""
    SD = _segment_modules()
    if not isinstance(out, SD.RouteVoid) or (out.v, out.by) != ("V17", "driver") or not out.args:
        return None
    why, zones = out.args[0], _o4_rows_of(log, "zone")
    if len(zones) != 1 or zones[0].get("why") != why or not any(p.match(str(why)) for p in _O4_READ_GAP_VOIDS):
        return None
    return why


def _o4_run_informative(game, *, attempts=3, **kw):
    """:func:`_o4_run` until a run is no read-gap VOID (:func:`_o4_read_gap_void`), at most ``attempts`` runs (R-GATE's
    3): ``(out, log, fake, story rows, set_aside)``, ``set_aside`` the reasons of the runs re-run. The last run is
    returned whatever it is -- a gap on every run still fails its test -- and a test asserts on the run returned exactly
    as on a single run. An F side registers its members on the first run only (the folder keeps them): a re-run is the
    same run."""
    aside: list = []
    for k in range(1, attempts + 1):
        out, log, fake, rows = _o4_run(game, **kw)
        why = _o4_read_gap_void(out, log)
        if why is None or k == attempts:
            return out, log, fake, rows, aside
        aside.append(why)
        kw["register"] = False


def _o4_starve_reads(n, for_frames, *, runs=None):
    """A ``wrap`` for :func:`_o4_run` -- THE LOADED MACHINE, deterministic: once instance ``n``'s press request is
    written, the driver's next read -- the press's own first wait for its ack -- waits, reading nothing, until the fake
    has ACCEPTED that request and run ``for_frames`` more frames (a starved poll, counted in the fake's frames so that a
    slow machine starves it no less). The gap opens at the acceptance, before the down frame, so no read lands between
    the down frame and the mark -- not even the press's own: on a loaded machine its ack read can land after the
    window's close tween (evidence "closed"), which a gap opened after the press returns no longer hides. ``for_frames`` over 27 --
    the 25 from the acceptance to the mark (down = accepted + 1, gone_ticks 12 at 60 fps on the game clock) and the 2
    a read's sample can lag the fake's frame (state.json every 2nd frame) -- make it straddle instance ``n``'s mark:
    the read-gap V17. The driver's live check measures from its ack frame, read after the gap, so the run goes on to
    its close, where the judge finds it. ``runs`` (1-based, None: every run, (): none) the runs it starves, of
    those it wraps -- ``wrap.runs`` counts them all, ``wrap.fired`` the runs whose press it starved."""
    def wrap(g, fake):
        wrap.runs += 1
        if runs is not None and wrap.runs not in runs:
            return
        real_press, real_send, real_state = g.press, g.channel.send, g.channel.state
        flag = {"count": 0, "arm": False, "seq": None}

        def press(button, frames=2):
            if frames == 2:
                flag["count"] += 1
                flag["arm"] = flag["count"] == n
            return real_press(button, frames)

        def send(steps, **kw):
            seq = real_send(steps, **kw)
            if flag["arm"]:                             # the press's own request, just written
                flag["arm"], flag["seq"] = False, seq
                wrap.fired.append(wrap.runs)
            return seq

        def state(*a, **kw):
            if flag["seq"] is not None:
                seq, flag["seq"], end = flag["seq"], None, time.time() + 10.0
                while fake.seq < seq and time.time() < end:
                    time.sleep(0.002)
                until = fake.frame + for_frames
                while fake.frame < until and time.time() < end:
                    time.sleep(0.002)
            return real_state(*a, **kw)
        g.press, g.channel.send, g.channel.state = press, send, state
    wrap.runs, wrap.fired = 0, []
    return wrap


def test_o4_drive_scores_100_on_the_fake(game):
    """THE OWNER'S REQUIREMENT on the fake (research/o4_design.md 0.1 #1, 2.2-2.4; S at 60 fps mean ticks, F through
    the members at 31 fps quantized): 105/106 closed after their gate by page-once; 111 pressed until it closed; 49
    prompt rows, each pressed once with its mapped button, every j_hi within 16, raw_lo >= 100, every evidence
    "closed", the zone's judge None; 122 == ``score_page`` (beat ``sword``), then 123 pressed until gone and nothing
    pressed from its going until 127; 127 answered No by ``g.choose(1)``, its presses rowed with their seqs (the
    confirm's cursor on No); 128 == ``gil_page``; the trace's ip338 0 -> 100 no later than 122 and ip390 0 -> 1 after
    123; beats sword and encore; the end reached in "150" (member(150) on F). Each side is :func:`_o4_run_informative`'s
    run (a read-gap VOID alone re-run). Break: drop rule 6b (111 then reaches rule 7, whose [DBTN= refusal stops the
    run V17 -- without it, rule 7's Confirm would miss 7 prompts of 8)."""
    for side, fps, ticks in (("S", 60.0, "mean"), ("F", 31.0, "quantized")):
        _o4_scores_100(game, side, fps, ticks)


def _o4_scores_100(game, side, fps, ticks):
    pol = _o4_policy(donor=30820)
    out, log, fake, trace, aside = _o4_run_informative(game, side=side, fps=fps, ticks=ticks, trace=True)
    assert not isinstance(out, Exception), (out, aside)
    assert out["end"] == "reached" and out["beats"] == {"sword": True, "encore": True}, out
    assert fake.field_id == _O4_FIELDS[side][1]
    zones, prompts = out["zones"], out["prompts"]
    assert len(zones) == 1 and zones[0]["judge"]["v"] is None and zones[0]["v"] is None, zones
    z = zones[0]
    assert z["raw"][0] >= 100 and z["instances"] == 49 and z["presses"] == 49, z
    assert len(prompts) == 49 and [p["n"] for p in prompts] == list(range(1, 50))
    assert all(p["button"] == pol["buttons"][p["dbtn"]] and p["evidence"] == "closed" for p in prompts), prompts
    assert max(p["j_hi"] for p in prompts) <= 16, [p["j_hi"] for p in prompts]
    presses = _o4_rows_of(log, "press", why="prompt")
    assert sorted(p["n"] for p in presses) == list(range(1, 50))
    pages = _o4_rows_of(log, "press", why="page")
    pair = [p for p in pages if any("En garde" in t or "no quarter" in t for t in p["texts"])]
    assert len(pair) >= 2 and any("Expect no quarter" in t for t in pair[-1]["texts"]), pair
    assert z["start_page"]["presses"] and z["start_page"]["first_without_frame"] is not None, z["start_page"]
    assert pol["score_page"] in out["pages"] and pol["gil_page"] in out["pages"], out["pages"]
    q = _o4_rows_of(log, "quiet")
    first127 = _cb_event(fake, "open", "They demand an encore!")["frame"]
    assert len(q) == 1, q
    inside = [p for p in log if p.get("k") == "press" and p.get("pre") and q[0]["open_frame"] <= p["pre"]["frame"]
              < first127 + 2]
    assert not inside, inside
    ch = [r for r in log if r.get("k") == "choice"]
    assert len(ch) == 1 and ch[0]["index"] == 1 and ch[0]["options"][1:] == ["es", "No"], ch
    chooses = _o4_rows_of(log, "press", why="choose")
    assert [c["button"] for c in chooses] == ["down", "confirm"] and chooses[1]["answer"] is True, chooses
    assert chooses[0]["seq"] < chooses[1]["seq"] and chooses[1]["selected_before"] == 1, chooses
    keys = {ip: (old, new, f) for sid, tag, ip, _b, old, new, f in trace if (sid, tag) == (4, 1)}
    assert keys[338][:2] == (0, 100) and keys[390][:2] == (0, 1), keys
    assert keys[338][2] <= _cb_event(fake, "open", "Of 100 nobles")["frame"]
    assert keys[390][2] >= _cb_event(fake, "gone", "quite impressed")["frame"]


def test_o4_drive_opens_one_instance_beside_a_lingering_prompt(game):
    """The instance tracker at a timeout (research/o4_design.md 0.2 #1, 2.4.3 step 8): instance 3's press stalls --
    the test's wrapped ``g.press`` reads the channel (every read lands in the ring) until prompt 4 is armed and 50 ms
    more, then sends -- so prompt 3 times out and prompt 4 arms in that tick, 3 still listed in its close tween beside
    it. The tracker opens EXACTLY instance 4 -- its ``prev`` the last sample without 4, which lists 3 (``prev_kind``
    "dbtn"), 3 still listed at 4's first sample (into ``closing``) -- and judges the switch: 3's press had not landed
    (the switch sample's published seq is below it), so the run stops V17 (driver); instance 3's evidence is not
    "closed"; nothing is pressed for 4. Break: open an instance per listed DBTN (the tracker drops its ``cur``
    exclusion)."""
    def wrap(g, fake):
        real, count = g.press, {"n": 0}

        def read_until(pred, limit):
            end = time.time() + limit
            while time.time() < end and not pred():
                g.state
                time.sleep(0.002)

        def press(button, frames=2):
            if frames == 2:
                count["n"] += 1
                if count["n"] == 3:
                    read_until(lambda: len(fake.chanbara_log) >= 4, 5.0)
                    read_until(lambda: False, 0.05)
            return real(button, frames)
        g.press = press
    out, log, fake, _t = _o4_run(game, wrap=wrap)
    _o4_void(out, "V17", "driver")
    rows = _o4_rows_of(log, "prompt")
    assert [r["n"] for r in rows] == [1, 2, 3, 4], rows
    r3, r4 = rows[2], rows[3]
    assert r4["prev_kind"] == "dbtn" and r4.get("stopped") is True and r4["seq"] is None, r4
    assert r3["last_listed_frame"] >= r4["seen_frame"] and r3["evidence"] != "closed", r3
    assert fake.chanbara_log[2]["result"] == "timeout", fake.chanbara_log[:4]
    assert [p["n"] for p in _o4_rows_of(log, "press", why="prompt")] == [1, 2, 3]
    assert "instance 3" in out.args[0], out


def test_o4_drive_paced_tracks_the_closing_prompt_beside_its_successor(game):
    """THE PACED POLICY's overlap (research/o4_design.md 0.2 #2, 2.4.3 step 8; rev. 2, the driver critique #2, the
    claim critique #3): pressed at ``target_ticks`` 22 (j ~22-25) against the reactions -- the defaults (28 after a
    LEFT / RIGHT hit, 30 after the rest), and every one 25 and 21 -- a hit later than the reaction re-arms in its own
    tick, the closing prompt listed beside its successor. Exactly 49 instances, every evidence "closed", the zone's
    judge None, raw inside [79, 99]: the run informative. Each is :func:`_o4_run_informative`'s run (a read-gap VOID
    alone re-run). Break: track instances on D without ``closing`` (the closing DBTN reopens as a phantom instance:
    V17)."""
    pol = {"policy": "paced", "raw_floor": ..., "j_cap": 40, "pace": {"target_ticks": 22, "lead_ticks": 2,
                                                                     "raw_band": [79, 99]}}
    for reaction in (None, 25, 21):
        knobs = {} if reaction is None else {"reaction": {99: reaction, 0: reaction, 1: reaction, "others": reaction}}
        out, log, fake, _t, aside = _o4_run_informative(game, knobs=knobs, pol=pol)
        assert not isinstance(out, Exception), (reaction, out, aside)
        z = out["zones"][0]
        assert z["judge"]["v"] is None and 79 <= z["raw"][0] <= z["raw"][1] <= 99, (reaction, z)
        rows = out["prompts"]
        assert len(rows) == 49 and {r["evidence"] for r in rows} == {"closed"}, \
            (reaction, [(r["n"], r["evidence"]) for r in rows])
        assert any(r["gone_kind"] == "dbtn" for r in rows), (reaction, "premise: a prompt closed beside its successor")


def test_o4_drive_entered_on_a_prompt_bounds_instance_one_from_the_ring(game):
    """A ZONE ENTERED ON A PROMPT (research/o4_design.md 2.4.2; the review, 11.5): H12's ``tutorial`` False stages the
    visit with no 111, so the main loop's first sample in the zone already lists prompt 1 and the executor starts at Z2
    (``start_page`` None, no T0). Instance 1's ``prev`` -- the last sample not listing its DBTN -- lies BEFORE the
    entry, in the ring the main loop's own reads filled: its prev frame is below its seen frame, its j bounds and the
    zone's raw are bounded, and the paced fight is judged None inside its band, the run reaching "150" -- on
    :func:`_o4_run_informative`'s run (a read-gap VOID alone re-run). Break: take instance 1's prev from the zone's own
    samples only (None: the judge then reads the row unbounded, V17)."""
    pol = {"policy": "paced", "raw_floor": ..., "j_cap": 40, "pace": {"target_ticks": 22, "lead_ticks": 2,
                                                                     "raw_band": [79, 99]}}
    out, log, fake, _t, aside = _o4_run_informative(game, knobs={"tutorial": False}, pol=pol)
    assert not isinstance(out, Exception) and out["end"] == "reached", (out, aside)
    z = out["zones"][0]
    assert z["start_page"] is None and z["first_prompt"]["t0_frame"] is None, z
    assert not [p for p in log if p.get("k") == "press" and any("To follow" in t for t in p.get("texts") or ())]
    r1 = out["prompts"][0]
    assert r1["prev_frame"] is not None and r1["prev_frame"] < r1["seen_frame"], r1
    assert r1["j_lo"] is not None and r1["j_hi"] is not None and r1["prev_kind"] == "none", r1
    assert z["judge"]["v"] is None and z["v"] is None and 79 <= z["raw"][0] <= z["raw"][1] <= 99, z
    assert len(out["prompts"]) == 49 and {r["evidence"] for r in out["prompts"]} == {"closed"}


def test_o4_drive_fails_closed_on_an_unclaimed_dialog(game):
    """The fight zone is FAIL-CLOSED (research/o4_design.md 2.4.3 steps 5-7; critique minor #4): prompts published in
    a form the recognizer does not claim (no [TIME=-1]) are V17 at the first one -- an ``observed`` row, nothing
    pressed after 111's Confirm; and a page injected among the prompts is V17 with its ``observed`` row, never rule 7's
    Confirm. Break: let an unclaimed dialog pass (the run then waits out ``first_prompt_s``: V14)."""
    out, log, fake, _t = _o4_run(game, knobs={"prompt_raw": "[STRT=54,1][TAIL=UPRF][IMME]Press [DBTN={dbtn}]"
                                                            "[MOBI={mobi}] !"})
    _o4_void(out, "V17", "driver")
    obs = _o4_rows_of(log, "observed")
    assert len(obs) == 1 and obs[0]["kind"] == "unclaimed_dialog" and obs[0]["cell"] == [30820, 1155], obs
    zone = _o4_rows_of(log, "zone")[0]
    pressed = [p for p in log if p.get("k") == "press" and p.get("seq") is not None]
    assert pressed and {p["why"] for p in pressed} == {"page"}, pressed
    assert zone["instances"] == 0 and zone["v"] == "V17" and zone["start_page"]["presses"], zone

    def inject(f):
        f._machine.queue_window(3, "page", "Blank\n“Hold!”", "[STRT=60,2][TAIL=LORF]Blank\n“Hold!”")
    out, log, fake, _t = _o4_run(game, phases=[(lambda f: len(f.chanbara_log) >= 5 and f._machine is not None, inject)])
    _o4_void(out, "V17", "driver")
    obs = _o4_rows_of(log, "observed")
    assert len(obs) == 1 and obs[0]["kind"] == "unclaimed_dialog" and "Blank\n“Hold!”" in obs[0]["texts"], obs
    assert not [p for p in log if p.get("k") == "press" and any("Hold" in t for t in p.get("texts") or ())]


def test_o4_drive_refuses_an_unrecognized_dbtn_page(game):
    """S8 a, THE DBTN REFUSAL (research/o4_design.md 2.2 rule 7; rev. 2, the driver critique #11): 111 and the prompts
    in a form neither recognizer claims -- here a policy whose zone start does not match 111's text, and prompts with
    an extra tag before "Press" -- are a page in the cell holding ``[DBTN=``: V17 at 111, with nothing pressed on it
    and an ``observed`` row. Break: let rule 7 press a ``[DBTN=`` page."""
    knobs = {"prompt_raw": "[STRT=54,1][TAIL=UPRF][IMME][DBTN=UP]Press [DBTN={dbtn}][MOBI={mobi}] ![TIME=-1]"}
    out, log, fake, _t = _o4_run(game, knobs=knobs, pol={"zone_start": {"match": "To follow Blank's", "dbtns": 8}})
    _o4_void(out, "V17", "driver")
    obs = _o4_rows_of(log, "observed")
    assert len(obs) == 1 and obs[0]["kind"] == "unrecognized_dbtn", obs
    assert any("To follow Blank" in t for t in obs[0]["texts"]), obs
    assert not [p for p in log if p.get("k") == "press" and any("To follow" in t for t in p.get("texts") or ())]
    assert not _o4_rows_of(log, "zone") and not fake.chanbara_log


def test_o4_drive_v17_on_a_stalled_press(game):
    """A DRIVER STALL is the driver's (research/o4_design.md 2.4.8): the test's wrapped ``g.press`` stalls BLIND before
    instance 5's press goes out -- it watches the fake's own log, never the channel -- while the game times prompt 5
    out and arms on: (switch) until prompt 6 is up, a new DBTN: the switch, 5's press not landed by it; (hidden) until a
    later prompt with 5's DBTN is up: the HIDDEN switch, that DBTN listed past 5's window's longest life (a
    successor's). The first sample after the stall -- read by the press itself before it writes its request -- stops
    the run V17 (driver) at once: the judge's first fault instance 5's window gone before its press could land
    (evidence "before": a successor's listing is never read as 5's window), nothing pressed after. Break: judge a stall
    as V18; or drop the hidden switch; or read a successor's listing as the window's."""
    for case in ("switch", "hidden"):
        def wrap(g, fake, case=case):
            real, count = g.press, {"n": 0}

            def blind_until(up):
                end = time.time() + 15.0
                while time.time() < end and not up(fake.chanbara_log):
                    time.sleep(0.002)
                time.sleep(0.1)                     # the earlier window's close tween done, the later one still up

            def press(button, frames=2):
                if frames == 2:
                    count["n"] += 1
                    if count["n"] == 5 and case == "switch":
                        blind_until(lambda cl: len(cl) >= 6)
                    elif count["n"] == 5:
                        blind_until(lambda cl: any(r["n"] > 5 and r["dbtn"] == cl[4]["dbtn"] and r["result"] is None
                                                   for r in cl))
                return real(button, frames)
            g.press = press
        out, log, fake, _t = _o4_run(game, wrap=wrap)
        _o4_void(out, "V17", "driver")
        z = _o4_rows_of(log, "zone")[0]
        rows = _o4_rows_of(log, "prompt")
        assert z["v"] == "V17" and z["why"].startswith("instance 5's window left before its press could land") \
            and z["judge"]["faults"], (case, z)
        assert [r["n"] for r in rows] == list(range(1, 7 if case == "switch" else 6)), (case, rows)
        assert rows[4]["evidence"] == "before" and rows[4]["seq"] is not None, (case, rows[4])
        assert max(p["n"] for p in _o4_rows_of(log, "press", why="prompt")) == 5, case


def test_o4_drive_read_stall_in_a_gap_is_v17_never_v18(game):
    """A READ STALL is the instrument's (research/o4_design.md 2.4.6, 2.4.8; rev. 2, the driver critique #4, the claim
    critique #2): the channel's reads starve from instance 9's press request until the fake has accepted it and run 30
    frames more (:func:`_o4_starve_reads`, counted in the fake's frames -- a 0.5 s wall-clock stall after the press
    returned flaked at -n 8 on a loaded machine: the press's own late ack read saw the window close, evidence "closed")
    -- inside the gap, so no sample shows instance 9's window leave in time. Its evidence is "unobserved" and the run is
    V17 "instrument: a read gap ...", never V18: a missing sample is no evidence about the game. A run a read gap voided
    BEFORE the starve fired (a starved poll under load, instance 9 never pressed) proves nothing here and is re-run, at
    most R-GATE's 3 runs; a run the starve fired in is asserted on whatever it is. Break: rate a missing sample as
    V18."""
    starve = _o4_starve_reads(9, 30)
    for _attempt in range(3):
        out, log, fake, _t = _o4_run(game, wrap=starve)
        if starve.runs in starve.fired or _o4_read_gap_void(out, log) is None:
            break
    assert starve.runs in starve.fired, ("premise: instance 9's press starved", starve.runs, out)
    _o4_void(out, "V17", "driver")
    rows = {r["n"]: r for r in _o4_rows_of(log, "prompt")}
    assert rows[9]["evidence"] == "unobserved", rows[9]
    assert out.args[0].startswith("instrument: a read gap"), out


def test_o4_drive_v18_on_a_lost_press(game):
    """A LOST PRESS is the game's (research/o4_design.md 2.4.3 step 10, 2.4.8): H12's ``lost`` {7} -- the agent takes
    instance 7's press and the game never reads it, so prompt 7 stays listed past its mark: V18 (game) at once, the cell
    [64, 1155], the zone's evidence "lingered", and nothing re-pressed -- on :func:`_o4_run_informative`'s run (the stop
    judges instances 1-7, so a gap in one of them is a read-gap VOID, re-run). Break: re-press a lingering prompt."""
    out, log, fake, _t, aside = _o4_run_informative(game, knobs={"lost": [7]})
    _o4_void(out, "V18", "game")
    assert out.cell == [30820, 1155], out.cell
    rows = {r["n"]: r for r in _o4_rows_of(log, "prompt")}
    assert rows[7]["evidence"] == "lingered" and max(rows) == 7, rows.get(7)
    assert [p["n"] for p in _o4_rows_of(log, "press", why="prompt")] == list(range(1, 8))


def test_o4_drive_v18_on_a_miss_read(game):
    """A MISS READ is the game's (research/o4_design.md 2.4.6, 2.4.8; rev. 2): H12's ``miss_read`` on seed 0's third
    prompt (RIGHT) -- the right key, scored a miss: its window closes on the key (evidence "closed") but neither body
    slides (its measured slide 0: left out), so the zone's judge reads V18 at Z3, before any score page -- on
    :func:`_o4_run_informative`'s run (a read-gap VOID alone re-run: the judge reads its V17 first). Break: ignore the
    slides (the run then goes on to a score page that reads otherwise)."""
    out, log, fake, _t, aside = _o4_run_informative(game, knobs={"miss_read": [3], "seed": 0})
    _o4_void(out, "V18", "game")
    z = _o4_rows_of(log, "zone")[0]
    rows = {r["n"]: r for r in _o4_rows_of(log, "prompt")}
    assert rows[3]["dbtn"] == "RIGHT" and rows[3]["evidence"] == "closed", rows[3]
    assert rows[3]["slide"]["ok"] is False and rows[3]["slide"]["left_out"] == [3], rows[3]["slide"]
    assert z["v"] == "V18" and "left out" in z["why"] and z["end"] is not None, z
    assert not [p for p in _o4_page_texts(log) if "nobles" in p]


def _o4_page_texts(log):
    """Every window text a ``page`` press row says it pressed."""
    return [t for p in log if p.get("k") == "press" and p.get("why") == "page" for t in p.get("texts") or ()]


def test_o4_drive_v18_on_what_the_game_shows(game):
    """What the GAME SHOWS after a proven play (research/o4_design.md 2.4.8, 2.4.12): H12's ``score_override`` 87 --
    page 122 reads "87 were impressed." in two samples: V18 with nothing pressed on it; ``extra_prompts`` 1 -- a 50th
    prompt: V18 at instance 50; ``unsubstituted_once`` -- 122 and 128 publish their raw [NUMB] first (for 48 frames
    here, ``unsubstituted_frames``, so a read of the driver's lands on it -- the premise, counted by the test's wrapped
    ``channel.state``): no stop (no one sample is read as the page) and the run reaches its end. Each is
    :func:`_o4_run_informative`'s run (a read-gap VOID alone re-run; the premise counted on the run returned). Break:
    read the page from one sample; or check only the trace (no page reading)."""
    SD = _segment_modules()
    out, log, fake, _t, aside = _o4_run_informative(game, knobs={"score_override": 87})
    _o4_void(out, "V18", "game")
    assert "87 were impressed" in out.args[0], out
    assert not [t for t in _o4_page_texts(log) if "nobles" in t]
    out, log, fake, _t, aside = _o4_run_informative(game, knobs={"extra_prompts": 1})
    _o4_void(out, "V18", "game")
    rows = _o4_rows_of(log, "prompt")
    assert len(rows) == 50 and rows[-1].get("stopped") and "50 prompts" in out.args[0], out
    raw = {"reads": 0}

    def wrap(g, fake):
        raw["reads"] = 0                            # each run's own: the premise is the run returned's
        real = g.channel.state

        def state(*a, **kw):
            st = real(*a, **kw)
            if st is not None and any("[NUMB=0]" in t for _p, t in SD.dialog_rows(st.raw)):
                raw["reads"] += 1
            return st
        g.channel.state = state
    out, log, fake, _t, aside = _o4_run_informative(game, knobs={"unsubstituted_once": True,
                                                                 "unsubstituted_frames": 48}, wrap=wrap)
    assert not isinstance(out, Exception) and out["end"] == "reached" and out["beats"]["sword"] is True, (out, aside)
    assert raw["reads"] >= 1, "premise: a read of the driver's saw page 122 unsubstituted"


def test_o4_drive_slides_at_31_fps_agent_first(game):
    """THE SLIDE WITNESS on the drive (research/o4_design.md 2.4.6; rev. 2, the driver critique #3, the claim critique
    #1): at 31 fps quantized, published agent-first -- a frame about a tick, so the first sample listing a prompt often
    shows a slide step already -- every LEFT/RIGHT slide is measured between the PREV samples: none measured and not ok,
    at least 3 of 4 measured; on :func:`_o4_run_informative`'s run (a read-gap VOID alone re-run). Break: measure from
    ``x_seen`` (about half the L/R slides read -240)."""
    out, log, fake, _t, aside = _o4_run_informative(game, fps=31.0, ticks="quantized", knobs={"seed": 0})
    assert not isinstance(out, Exception), (out, aside)
    s = out["zones"][0]["slides"]
    assert s["not_ok"] == 0 and s["ok"] >= 3 * (s["ok"] + s["unmeasured"]) / 4 and s["ok"] >= 4, s


def test_o4_drive_page_once_and_the_quiet_windows(game):
    """S8 b and c (research/o4_design.md 2.2 rule 7, 2.4.11): the KEYON pair 105/106 (``gates`` 40) is pressed by
    page-once -- every press at least ``page_once_ticks`` after the last unless it presses a window not pressed before
    (106 joining 105) -- until both close; 111 is pressed until gone; and a page injected after 123 has gone, before
    127, falls in the quiet window: V17 with an ``observed`` row, nothing pressed on it. The run is
    :func:`_o4_run_informative`'s: a read-gap V17 (a starved poll on a loaded machine, no ``observed`` row) is the
    instrument's, re-run as R-GATE re-runs it -- it flaked this test serially on master. Break: page-once off."""
    def inject(f):
        f._machine.queue_window(3, "page", "Queen Brahne\n“Encore!”",
                                "[STRT=60,2][TAIL=DEFT]Queen Brahne\n“Encore!”")
    gone = {}

    def after_123(f):
        if gone.get("fake") is not f:               # a re-run's fake starts the watch afresh
            gone.clear()
            gone["fake"] = f
        e = [x for x in f.machine_log if x["event"] == "gone" and "quite impressed" in x["text"]]
        if e and "tick" not in gone:
            gone["tick"] = e[0]["tick"]
        return f._machine is not None and "tick" in gone and f._machine.tick >= gone["tick"] + 4
    out, log, fake, _t, aside = _o4_run_informative(game, knobs={"gates": {"105": 40}}, phases=[(after_123, inject)])
    _o4_void(out, "V17", "driver")
    obs = _o4_rows_of(log, "observed")
    assert len(obs) == 1 and obs[0]["kind"] == "quiet_page", obs
    pair = [p for p in _o4_rows_of(log, "press", why="page")
            if any("garde" in t or "quarter" in t for t in p["texts"])]
    assert len(pair) >= 3, pair
    hold = 20                                       # page_once_ticks 10 at 60 fps: 20 frames at the least
    for a, b in zip(pair, pair[1:]):
        new = set(b["texts"]) - {t for p in pair[:pair.index(b)] for t in p["texts"]}
        assert new or b["pre"]["frame"] >= a["ack_frame"] + hold - 2, (a, b)
    z = _o4_rows_of(log, "zone")[0]
    assert z["start_page"]["presses"] and z["start_page"]["first_without_frame"] is not None
    assert not [p for p in log if p.get("k") == "press" and any("Encore!" in t for t in p.get("texts") or ())]


def test_o4_drive_presses_123_again_when_its_first_press_is_dropped(game):
    """S8 b, c on a dropped Confirm (research/o4_design.md 0.3 #1, 2.4.11; rev. 2, the driver critique #1, the claim
    critique #6): with the pages' opening long (``open_s`` 0.25 s) 123's first press lands in its opening and is
    dropped; page-once presses it again ``page_once_ticks`` later, the quiet window opens only at the first sample
    without it, and 127 comes and is answered No -- the run reaches its end, on :func:`_o4_run_informative`'s run (a
    read-gap VOID alone re-run). Break: open the quiet window at the press (rev. 1: the dropped press leaves 123 up in
    an open quiet window)."""
    out, log, fake, _t, aside = _o4_run_informative(game, knobs={"open_s": 0.25})
    assert not isinstance(out, Exception) and out["end"] == "reached", (out, aside)
    p123 = [p for p in _o4_rows_of(log, "press", why="page") if "Queen Brahne was\nquite impressed." in p["texts"]]
    assert len(p123) >= 2, p123
    q = _o4_rows_of(log, "quiet")
    assert len(q) == 1 and q[0]["open_frame"] > p123[-1]["pre"]["frame"], (q, p123)
    assert [c["index"] for c in log if c.get("k") == "choice"] == [1]


def test_o4_drive_attributes_a_stray_yes(game):
    """S9's encore attribution on the drive (research/o4_design.md 2.4.11; rev. 2, the claim critique #8): a mutant
    driver whose ``choose`` confirms at the cursor (Yes) makes the game replay -- the replay's first page (109) goes to
    the attribution, which finds the driver's own Confirm with the cursor on Yes: V17 (driver), never the fight judge;
    the game replaying on its own (H12's ``replay_on_no``) after a proper No: V2 (game) -- ``choose``'s presses rowed
    with their seqs (down, then the confirm with the cursor on No, the answer's own). Break: V2 always; or send a
    replay page to the fight judge."""
    def wrap(g, fake):
        g.choose = lambda index, **kw: g.press("confirm", 4)
    out, log, fake, _t = _o4_run(game, wrap=wrap)
    _o4_void(out, "V17", "driver")
    assert "with the cursor on Yes" in out.args[0], out
    stray = _o4_rows_of(log, "encore_stray")
    assert len(stray) == 1 and stray[0]["v"] == "V17" and not _o4_rows_of(log, "page_judge"), stray
    out, log, fake, _t = _o4_run(game, knobs={"replay_on_no": True})
    _o4_void(out, "V2", "game")
    assert out.cell == [30820, 1155] and _o4_rows_of(log, "encore_stray")[0]["v"] == "V2"
    chooses = _o4_rows_of(log, "press", why="choose")
    assert [(c["button"], c["answer"]) for c in chooses] == [("down", False), ("confirm", True)], chooses
    assert chooses[0]["seq"] < chooses[1]["seq"], chooses
    assert chooses[1]["selected_before"] == 1 and all(c["down_frame"] for c in chooses), chooses


def test_o4_drive_paced_policy_lands_in_its_band(game):
    """THE PACE (research/o4_design.md 2.4.10, R-GATE's): paced at ``target_ticks`` 22 the zone's judge is None and
    raw lies in [79, 99]; with the +30% firing page 122 reads 100 and the run reaches its end; with ``bonus_fires``
    False (a fork whose wrap fails) page 122 reads the raw itself -- V18 at the score page, and the trace's ip338 row
    holds that raw, inside the zone's raw bounds; and with the render rate switched 60 -> 31 mid-fight (and the loop
    with it) j stays in the band. Each is :func:`_o4_run_informative`'s run: on a loaded machine a starved poll alone
    can void a run V17 by the instrument's read gap -- re-run, as R-GATE re-runs it; nothing else is (a late press is
    this test's failure). Break: pace by ``ticks_sure`` of the frames (rev. 1: after the switch the presses land about
    twice as late, j ~40: V17)."""
    pol = {"policy": "paced", "raw_floor": ..., "j_cap": 40,
           "pace": {"target_ticks": 22, "lead_ticks": 2, "raw_band": [79, 99]}}
    out, log, fake, _t, aside = _o4_run_informative(game, pol=pol)
    assert not isinstance(out, Exception) and out["end"] == "reached", (out, aside)
    z = out["zones"][0]
    assert z["judge"]["v"] is None and 79 <= z["raw"][0] <= z["raw"][1] <= 99, z
    assert "Of 100 nobles watching,\n100 were impressed." in out["pages"]
    out, log, fake, trace, aside = _o4_run_informative(game, pol=pol, knobs={"bonus_fires": False}, trace=True)
    _o4_void(out, "V18", "game")
    z = _o4_rows_of(log, "zone")[0]
    raw = [new for sid, tag, ip, _b, _o, new, _f in trace if (sid, tag, ip) == (4, 1, 338)]
    assert len(raw) == 1 and z["raw"][0] <= raw[0] <= z["raw"][1] and f"{raw[0]} were impressed" in out.args[0], \
        (raw, z["raw"], out)

    def switch(f):
        f.render_fps, f.fps = 31.0, 124.0
    out, log, fake, _t, aside = _o4_run_informative(game, pol=pol,
                                                    phases=[(lambda f: len(f.chanbara_log) >= 20, switch)])
    assert not isinstance(out, Exception) and out["end"] == "reached", (out, aside)
    z = out["zones"][0]
    assert z["judge"]["v"] is None and 79 <= z["raw"][0] <= z["raw"][1] <= 99, z
    assert {r["regime"] for r in out["prompts"]} >= {"60", "31"}, {r["regime"] for r in out["prompts"]}


def test_o4_read_gap_void_reads_the_zone_reason_alone():
    """THE LOAD-ONLY RE-RUN's reading (:func:`_o4_read_gap_void`), pure: a V17 (driver) the fight zone raised whose
    REASON names the instrument's read gap -- a gap straddling a mark (a later fault following it), one that could hide
    a prompt's whole life, one that hid an instance from the tracker (an unjudged stop) -- is set aside; nothing else
    is: a late press with a gap among the later faults, a V18 (one naming a gap too), a V17 with no attribution, a V17
    another step raised (the zone's reason another, or no zone), the driver's observed V17, the instrument's V13, a run
    that reached its end. Break: read every fault; or set aside any V17; or drop the zone's reason or the class."""
    SD = _segment_modules()
    gap = "instrument: a read gap of 0.083 s straddles instance 43's mark (evidence unobserved)"
    late = "instance 44's j_hi 44 is over j_cap 40"

    def run(why, v="V17", by="driver", *, zone_why=..., faults=None):
        zone_why = why if zone_why is ... else zone_why
        judge = None if faults is None else {"v": v, "by": by, "why": faults[0], "faults": faults, "raw": [80, 90]}
        log = [{"k": "prompt", "n": 1}]
        if zone_why is not None:
            log.append({"k": "zone", "v": v, "by": by, "why": zone_why, "judge": judge})
        return SD.RouteVoid(why, v=v, cell=[30820, 1155], by=by), log
    whole = "48 instances, and a read gap of 60 ticks could hide a prompt's whole life"
    hid = "a read gap hid an instance: ['UP', 'LEFT'] first listed together at frame 2911"
    for why, faults in ((gap, [gap, late]), (whole, [whole]), (hid, None)):
        assert _o4_read_gap_void(*run(why, faults=faults)) == why, why
    before = "instance 3's window left before its press could land (evidence before)"
    quiet = "a page in the quiet window, nothing pressed: 'Queen Brahne\\n“Encore!”'"
    kept = {"a late press first": run(late, faults=[late, gap]),
            "a V18 naming a gap": run(gap, "V18", "game", faults=[gap]),
            "a V18": run("48 prompts, fewer than 49, and no read gap could hide one", "V18", "game", faults=["x"]),
            "no attribution": run(gap, by=None, faults=[gap]),
            "the zone's reason another": run(gap, zone_why=before, faults=[before, gap]),
            "no zone": run(gap, zone_why=None),
            "an observed V17": run(quiet)}
    for what, (out, log) in kept.items():
        assert _o4_read_gap_void(out, log) is None, what
    assert _o4_read_gap_void(HarnessError(f"left FieldHUD (MainMenu) {gap}"), []) is None
    assert _o4_read_gap_void({"end": "reached", "zones": []}, [{"k": "zone", "why": gap}]) is None


def test_o4_drive_paced_policy_reruns_only_a_read_gap(game):
    """THE LOADED MACHINE, deterministic -- test_o4_drive_paced_policy_lands_in_its_band's -n 6 flake ("instrument: a
    read gap of 0.083 s straddles instance 43's mark (evidence unobserved)", V17 where its bonus run's V18 was due):
    :func:`_o4_starve_reads` blinds the driver's reads 30 frames after instance 43's press in that run's FIRST attempt,
    past its mark -- the read-gap V17, set aside -- and the next attempt reads V18 at the score page with the trace's
    raw inside the zone's bounds, as that test asserts. Starved on EVERY attempt (instance 3; H12's ``lost`` [5] stops
    each early, its V18 behind the gap's V17 -- a play the instrument did not prove is never a finding), the third
    attempt's V17 is returned, two set aside: a gap never passes. A V18 (``lost`` [7]) and the driver's other V17
    (``stop_after``) are returned at once. A loaded machine may add a natural gap to any attempt, so a set-aside is
    read as a read gap, never counted on an unstarved run. Break: re-run every V17 (or every VOID); or drop the bound;
    or return a set-aside run."""
    pol = {"policy": "paced", "raw_floor": ..., "j_cap": 40,
           "pace": {"target_ticks": 22, "lead_ticks": 2, "raw_band": [79, 99]}}

    def gaps(aside):
        return all(any(p.match(w) for p in _O4_READ_GAP_VOIDS) for w in aside)
    starve = _o4_starve_reads(43, 30, runs={1})
    out, log, fake, trace, aside = _o4_run_informative(game, pol=pol, knobs={"bonus_fires": False}, trace=True,
                                                       wrap=starve)
    assert aside and gaps(aside) and starve.runs == len(aside) + 1, (starve.runs, aside)
    _o4_void(out, "V18", "game")
    z = _o4_rows_of(log, "zone")[0]
    raw = [new for sid, tag, ip, _b, _o, new, _f in trace if (sid, tag, ip) == (4, 1, 338)]
    assert len(raw) == 1 and z["raw"][0] <= raw[0] <= z["raw"][1] and f"{raw[0]} were impressed" in out.args[0], \
        (raw, z["raw"], out)
    starve = _o4_starve_reads(3, 30)
    out, log, fake, _t, aside = _o4_run_informative(game, pol=pol, knobs={"lost": [5]}, wrap=starve)
    assert starve.runs == 3 and len(aside) == 2 and gaps(aside), (starve.runs, aside)
    _o4_void(out, "V17", "driver")
    rows = {r["n"]: r for r in _o4_rows_of(log, "prompt")}
    assert _o4_read_gap_void(out, log) == out.args[0] and max(rows) == 5 and rows[5]["evidence"] == "lingered", \
        (out, {n: r["evidence"] for n, r in rows.items()})
    count = _o4_starve_reads(1, 0, runs=())
    out, log, fake, _t, aside = _o4_run_informative(game, knobs={"lost": [7]}, wrap=count)
    _o4_void(out, "V18", "game")
    assert gaps(aside) and count.runs == len(aside) + 1, (count.runs, aside)
    count = _o4_starve_reads(1, 0, runs=())
    out, log, fake, _t, aside = _o4_run_informative(game, pol={"stop_after": 10}, wrap=count)
    _o4_void(out, "V17", "driver")
    assert out.args[0] == "the rehearsal's stop after instance 10" and gaps(aside) and count.runs == len(aside) + 1, \
        (out, count.runs, aside)


