    f502 = rec["trace"]["movie"]["ip502"]["f"]
    assert ms is not None and ms["field"] == s["166"] and ms["f502"] == f502 < ms["frame"], (ms, f502)
    assert ms["after_s"] >= 1.5 and ms["holds_after"] == 0 and ms["presses_after"] == 0, ms
    mv = fake.movies
